INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爱', 'ài', 'Yêu; thương; yêu quý', '爸爸爱妈妈。', 'Bàba ài māmā', 'Ba yêu mẹ.', 'Động từ', '[{"pos":"Động từ","meaning":"Yêu; thương; yêu quý","example":"爸爸爱妈妈。","example_pinyin":"/Bàba ài māmā/","example_meaning":"Ba yêu mẹ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爱好', 'àihào', 'Yêu thích; yêu chuộng', '我爱好打篮球。', 'Wǒ àihào dǎ lánqiú', 'Tôi thích chơi bóng rổ.', 'Động từ', '[{"pos":"Động từ","meaning":"Yêu thích; yêu chuộng","example":"我爱好打篮球。","example_pinyin":"/Wǒ àihào dǎ lánqiú/","example_meaning":"Tôi thích chơi bóng rổ.","is_approved":true},{"pos":"Danh từ","meaning":"Sở thích","example":"我的爱好是听音乐。","example_pinyin":"/Wǒ de àihào shì tīng yīnyuè/","example_meaning":"Sở thích của tôi là nghe nhạc.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('八', 'bā', 'Số tám', '他买了八个苹果。', 'Tā mǎi le bā gè píngguǒ', 'Anh ấy đã mua tám quả táo.', 'Số từ', '[{"pos":"Số từ","meaning":"Số tám","example":"他买了八个苹果。","example_pinyin":"/Tā mǎi le bā gè píngguǒ/","example_meaning":"Anh ấy đã mua tám quả táo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爸爸 | 爸', 'bàba', 'Bố; ba', '他是我的爸爸。', 'Tā shì wǒ de bàba', 'Ông ấy là ba của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bố; ba","example":"他是我的爸爸。","example_pinyin":"/Tā shì wǒ de bàba/","example_meaning":"Ông ấy là ba của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('吧', 'ba', 'Nhé; chứ; nào; thôi', '我们去公园玩儿吧。', 'Wǒmen qù gōngyuán wán er ba', 'Chúng mình đi công viên chơi nhé.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Nhé; chứ; nào; thôi","example":"我们去公园玩儿吧。","example_pinyin":"/Wǒmen qù gōngyuán wán er ba/","example_meaning":"Chúng mình đi công viên chơi nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('白', 'bái', 'Trắng, màu trắng', '我姐姐的皮肤很白。', 'Wǒ jiějiě de pífū hěn bái', 'Da của chị tôi rất trắng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Trắng, màu trắng","example":"我姐姐的皮肤很白。","example_pinyin":"/Wǒ jiějiě de pífū hěn bái/","example_meaning":"Da của chị tôi rất trắng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('白天', 'báitiān', 'Ban ngày', '早睡吧，你白天还要去上课。', 'Zǎo shuì ba, nǐ báitiān hái yào qù shàngkè', 'Ngủ sớm đi, bạn ban ngày còn phải đi học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ban ngày","example":"早睡吧，你白天还要去上课。","example_pinyin":"/Zǎo shuì ba, nǐ báitiān hái yào qù shàngkè/","example_meaning":"Ngủ sớm đi, bạn ban ngày còn phải đi học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('百', 'bǎi', 'Một trăm; số 100', '我有一百块钱。', 'Wǒ yǒu yībǎi kuài qián', 'Tôi có một trăm tệ.', 'Số từ', '[{"pos":"Số từ","meaning":"Một trăm; số 100","example":"我有一百块钱。","example_pinyin":"/Wǒ yǒu yībǎi kuài qián/","example_meaning":"Tôi có một trăm tệ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('班', 'bān', 'Lớp học', '我们班有四十五个学生。', 'Wǒmen bān yǒu sìshíwǔ gè xuéshēng', 'Lớp của chúng tôi có 45 học sinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lớp học","example":"我们班有四十五个学生。","example_pinyin":"/Wǒmen bān yǒu sìshíwǔ gè xuéshēng/","example_meaning":"Lớp của chúng tôi có 45 học sinh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('半', 'bàn', 'Một nửa

giữa; trung gian', '现在六点半。

我们在半路上遇到了他。', 'Xiànzài liù diǎn bàn

Wǒmen zài bàn lùshàng yù dàole tā', 'Bây giờ là 6 giờ rưỡi.

