INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('半年', 'bànnián', 'Nửa năm', '我来上海学习已经有半年了。', 'Wǒ lái shànghǎi xuéxí yǐjīng yǒu bànnián le', 'Tôi đến Thượng Hải học đã được nửa năm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nửa năm","example":"我来上海学习已经有半年了。","example_pinyin":"/Wǒ lái shànghǎi xuéxí yǐjīng yǒu bànnián le/","example_meaning":"Tôi đến Thượng Hải học đã được nửa năm.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('半天', 'bàntiān', 'Nửa ngày

cả buổi; rất lâu', '我今天要工作半天。

