INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('帮', 'bāng', 'Giúp đỡ, trợ giúp', '他经常帮我做家务。', 'Tā jīngcháng bāng wǒ zuò jiāwù', 'Anh ấy thường giúp tôi làm việc nhà.', 'Động từ', '[{"pos":"Động từ","meaning":"Giúp đỡ, trợ giúp","example":"他经常帮我做家务。","example_pinyin":"/Tā jīngcháng bāng wǒ zuò jiāwù/","example_meaning":"Anh ấy thường giúp tôi làm việc nhà.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('帮忙', 'bāngmáng', 'Giúp, giúp đỡ', '你可以来帮忙吗？', 'Nǐ kěyǐ lái bāngmáng ma?', 'Bạn có thể lại giúp đỡ không?', 'Động từ', '[{"pos":"Động từ","meaning":"Giúp, giúp đỡ","example":"你可以来帮忙吗？","example_pinyin":"/Nǐ kěyǐ lái bāngmáng ma?/","example_meaning":"Bạn có thể lại giúp đỡ không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('包', 'bāo', 'Bao; gói; bọc; quấn', '妈妈在包饺子。', 'Māma zài bāo jiǎozǐ', 'Mẹ đang gói sủi cảo.', 'Động từ', '[{"pos":"Động từ","meaning":"Bao; gói; bọc; quấn","example":"妈妈在包饺子。","example_pinyin":"/Māma zài bāo jiǎozǐ/","example_meaning":"Mẹ đang gói sủi cảo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('包子', 'bāozǐ', 'Bánh bao', '我今天早上吃了两个包子。', 'Wǒ jīntiān zǎoshang chī le liǎng gè bāozǐ', 'Sáng nay tôi đã ăn 2 cái bánh bao.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bánh bao","example":"我今天早上吃了两个包子。","example_pinyin":"/Wǒ jīntiān zǎoshang chī le liǎng gè bāozǐ/","example_meaning":"Sáng nay tôi đã ăn 2 cái bánh bao.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('杯', 'bēi', 'Ly; cốc

