INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('杯子', 'bēizi', 'Ly; cốc; tách', '这个杯子太小了。', 'Zhège bēizǐ tài xiǎole', 'Cái ly này quá nhỏ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ly; cốc; tách","example":"这个杯子太小了。","example_pinyin":"/Zhège bēizǐ tài xiǎole/","example_meaning":"Cái ly này quá nhỏ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('北', 'běi', 'Bắc, phía bắc', '我们一直往北走吧。', 'Wǒmen yīzhí wǎng běi zǒu ba', 'Chúng ta cứ đi về phía bắc đi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bắc, phía bắc","example":"我们一直往北走吧。","example_pinyin":"/Wǒmen yīzhí wǎng běi zǒu ba/","example_meaning":"Chúng ta cứ đi về phía bắc đi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('北边', 'běibian', 'Phía bắc', '北边的天气很冷。', 'Běibian de tiānqì hěn lěng', 'Thời tiết của phương bắc rất lạnh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía bắc","example":"北边的天气很冷。","example_pinyin":"/Běibian de tiānqì hěn lěng/","example_meaning":"Thời tiết của phương bắc rất lạnh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('北京', 'Běijīng', 'Bắc kinh', '北京是中国的首都。', 'Běijīng shì zhōngguó de shǒudū', 'Bắc Kinh là thủ đô của Trung Quốc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bắc kinh","example":"北京是中国的首都。","example_pinyin":"/Běijīng shì zhōngguó de shǒudū/","example_meaning":"Bắc Kinh là thủ đô của Trung Quốc.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('本', 'běn', 'Cuốn; tập; vở', '你读过这本书了吗？', 'Nǐ dúguò zhè běn shū le ma?', 'Bạn đã đọc cuốn sách này chưa?', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Cuốn; tập; vở","example":"你读过这本书了吗？","example_pinyin":"/Nǐ dúguò zhè běn shū le ma?/","example_meaning":"Bạn đã đọc cuốn sách này chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('本子', 'běnzǐ', 'Cuốn; tập; vở

giấy phép; chứng chỉ', '这个歌剧的本子挺有意思的。

在越南，满18周岁就可以考本子了。', 'Zhège gējù de běnzi tǐng yǒuyìsi de

