Ở Việt Nam, bạn đủ 18 tuổi đã có thể thi giấy phép lấy xe.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cuốn; tập; vở\n\ngiấy phép; chứng chỉ","example":"这个歌剧的本子挺有意思的。\n\n在越南，满18周岁就可以考本子了。","example_pinyin":"/Zhège gējù de běnzi tǐng yǒuyìsi de/\n\n/Zài Yuènán, mǎn 18 zhōusuì jiù kěyǐ kǎo běnzǐ le/","example_meaning":"Bản nhạc kịch này thật thú vị.\n\nỞ Việt Nam, bạn đủ 18 tuổi đã có thể thi giấy phép lấy xe.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('比', 'bǐ', 'Hơn, so, so với', '我哥哥比我高。', 'Wǒ gēge bǐ wǒ gāo', 'Anh trai tôi cao hơn tôi.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Hơn, so, so với","example":"我哥哥比我高。","example_pinyin":"/Wǒ gēge bǐ wǒ gāo/","example_meaning":"Anh trai tôi cao hơn tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('别', 'bié', 'Đừng; chớ

hẳn là; hay là; lẽ nào', '在医院，大家别大声说话。

他到现在还没来，别是忘了吗？', 'Zài yīyuàn, dàjiā bié dàshēng shuōhuà

Tā dào xiànzài hái méi lái, bié shì wàng le ma', 'Ở bệnh viện, mọi người đừng nói lớn tiếng.

Anh ấy đến bây giờ vẫn chưa đến, lẽ nào anh ấy quên rồi sao?', 'Phó từ', '[{"pos":"Phó từ","meaning":"Đừng; chớ\n\nhẳn là; hay là; lẽ nào","example":"在医院，大家别大声说话。\n\n他到现在还没来，别是忘了吗？","example_pinyin":"/Zài yīyuàn, dàjiā bié dàshēng shuōhuà/\n\n/Tā dào xiànzài hái méi lái, bié shì wàng le ma/","example_meaning":"Ở bệnh viện, mọi người đừng nói lớn tiếng.\n\nAnh ấy đến bây giờ vẫn chưa đến, lẽ nào anh ấy quên rồi sao?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('别的', 'bié de', 'Khác; cái khác', '我不要别的，只要那支钢笔。', 'Wǒ bùyào bié de, zhǐyào nà zhī gāngbǐ', 'Tôi không cần cái nào khác, chỉ cần cây bút đó.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Khác; cái khác","example":"我不要别的，只要那支钢笔。","example_pinyin":"/Wǒ bùyào bié de, zhǐyào nà zhī gāngbǐ/","example_meaning":"Tôi không cần cái nào khác, chỉ cần cây bút đó.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('别人', 'biérén', 'Người khác; người ta', '这本书可能是别人的。', 'Chúle Xiǎo Lì yǐwài, biérén dōu bù yuànyì qù', 'Ngoại trừ Tiểu Lệ ra, những người khác đều không muốn đi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người khác; người ta","example":"这本书可能是别人的。","example_pinyin":"/Chúle Xiǎo Lì yǐwài, biérén dōu bù yuànyì qù/","example_meaning":"Ngoại trừ Tiểu Lệ ra, những người khác đều không muốn đi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('病', 'bìng', 'Bệnh; ốm', '我生病了。', 'Wǒ shēng bìng le', 'Tôi bị bệnh rồi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bệnh; ốm","example":"我生病了。","example_pinyin":"/Wǒ shēng bìng le/","example_meaning":"Tôi bị bệnh rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('病人', 'bìngrén', 'Bệnh nhân; người bệnh', '王医生每天都要看十到二十位病人。', 'Wáng yīshēng měitiān dōu yào kàn shí dào èrshí wèi bìngrén', 'Bác sĩ Vương mỗi ngày đều phải khám từ 10 đến 20 bệnh nhân.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bệnh nhân; người bệnh","example":"王医生每天都要看十到二十位病人。","example_pinyin":"/Wáng yīshēng měitiān dōu yào kàn shí dào èrshí wèi bìngrén/","example_meaning":"Bác sĩ Vương mỗi ngày đều phải khám từ 10 đến 20 bệnh nhân.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不大', 'bù dà', 'Không to; không lớn', '这个房间不大。', 'Zhège fángjiān bù dà', 'Căn phòng này không lớn.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không to; không lớn","example":"这个房间不大。","example_pinyin":"/Zhège fángjiān bù dà/","example_meaning":"Căn phòng này không lớn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不对', 'bùduì', 'Không đúng', '你的答案不对。', 'Nǐ de dá''àn bù duì', 'Đáp án của bạn không đúng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Không đúng","example":"你的答案不对。","example_pinyin":"/Nǐ de dá''àn bù duì/","example_meaning":"Đáp án của bạn không đúng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不客气', 'búkèqi', 'Không có gì; đừng khách sáo', 'A: 谢谢你！
B: 不客气！', 'A: Xièxiè nǐ
B: Búkèqi', 'A: Cảm ơn bạn! 
B: Đừng khách sáo!', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Không có gì; đừng khách sáo","example":"A: 谢谢你！\nB: 不客气！","example_pinyin":"A: /Xièxiè nǐ/\nB: /Búkèqi/","example_meaning":"A: Cảm ơn bạn! \nB: Đừng khách sáo!","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不用', 'búyòng', 'Không cần; không phải', '你不用担心。', 'Nǐ búyòng dānxīn', 'Bạn không cần phải lo lắng.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không cần; không phải","example":"你不用担心。","example_pinyin":"/Nǐ búyòng dānxīn/","example_meaning":"Bạn không cần phải lo lắng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不', 'bù', 'Không', '我不喜欢吃辣。', 'Wǒ bù xǐhuān chī là', 'Tôi không thích ăn cay.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không","example":"我不喜欢吃辣。","example_pinyin":"/Wǒ bù xǐhuān chī là/","example_meaning":"Tôi không thích ăn cay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('菜', 'cài', 'Món ăn; đồ ăn', '今天的菜很好吃。', 'Jīntiān de cài hěn hǎo chī', 'Món ăn của hôm nay rất ngon.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Món ăn; đồ ăn","example":"今天的菜很好吃。","example_pinyin":"/Jīntiān de cài hěn hǎo chī/","example_meaning":"Món ăn của hôm nay rất ngon.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('茶', 'chá', 'Trà (đồ uống)', '我喜欢喝茶。', 'Wǒ xǐhuān hē chá', 'Tôi thích uống trà.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trà (đồ uống)","example":"我喜欢喝茶。","example_pinyin":"/Wǒ xǐhuān hē chá/","example_meaning":"Tôi thích uống trà.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('差', 'chà', 'Kém; tệ; không đạt', '他今天状态很差。', 'Tā jīntiān zhuàngtài hěn chà', 'Trạng thái của anh hôm nay rất tệ.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Kém; tệ; không đạt","example":"他今天状态很差。","example_pinyin":"/Tā jīntiān zhuàngtài hěn chà/","example_meaning":"Trạng thái của anh hôm nay rất tệ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('常', 'cháng', 'Thường; thường xuyên', '我常去跑步。', 'Wǒ cháng qù pǎobù', 'Tôi thường xuyên chạy bộ.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Thường; thường xuyên","example":"我常去跑步。","example_pinyin":"/Wǒ cháng qù pǎobù/","example_meaning":"Tôi thường xuyên chạy bộ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('尝尝', 'cháng cháng', 'Nếm; thử (ăn, uống)', '你尝尝这个菜。', 'Nǐ cháng cháng zhège cài', 'Bạn hãy nếm thử món ăn này.', 'Động từ', '[{"pos":"Động từ","meaning":"Nếm; thử (ăn, uống)","example":"你尝尝这个菜。","example_pinyin":"/Nǐ cháng cháng zhège cài/","example_meaning":"Bạn hãy nếm thử món ăn này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('唱', 'chàng', 'Hát; ca', '她唱太好了，大家都起立鼓掌。', 'Tā chàng tài hǎo le, dàjiā dōu qǐlì gǔzhǎng', 'Cô ấy hát rất hay, mọi người đều đứng dậy vỗ tay.', 'Động từ', '[{"pos":"Động từ","meaning":"Hát; ca","example":"她唱太好了，大家都起立鼓掌。","example_pinyin":"/Tā chàng tài hǎo le, dàjiā dōu qǐlì gǔzhǎng/","example_meaning":"Cô ấy hát rất hay, mọi người đều đứng dậy vỗ tay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('唱歌', 'chànggē', 'Hát; ca hát', '我家邻居昨天一直不停地唱歌。', 'Wǒjiā línjū zuótiān yīzhí bù tíng de chànggē', 'Ngày hôm qua hàng xóm của tôi ca hát không ngừng.', 'Động từ', '[{"pos":"Động từ","meaning":"Hát; ca hát","example":"我家邻居昨天一直不停地唱歌。","example_pinyin":"/Wǒjiā línjū zuótiān yīzhí bù tíng de chànggē/","example_meaning":"Ngày hôm qua hàng xóm của tôi ca hát không ngừng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('车', 'chē', 'Xe', '我们开车去旅行。', 'Wǒmen kāichē qù lǚxíng', 'Chúng tôi lái xe đi du lịch.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Xe","example":"我们开车去旅行。","example_pinyin":"/Wǒmen kāichē qù lǚxíng/","example_meaning":"Chúng tôi lái xe đi du lịch.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('车票', 'chēpiào', 'Vé xe', '快过年了，你买火车票了吗？', 'Kuài guò nián le, nǐ mǎi huǒchē piào huí jiā le ma?', 'Tết sắp đến rồi, bạn đã mua vé tàu về nhà chưa?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Vé xe","example":"快过年了，你买火车票了吗？","example_pinyin":"/Kuài guò nián le, nǐ mǎi huǒchē piào huí jiā le ma?/","example_meaning":"Tết sắp đến rồi, bạn đã mua vé tàu về nhà chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('车上', 'chē shàng', 'Trên xe', '她在车上学英语。', 'Tā zài chē shàng xué yīngyǔ', 'Cô ấy học tiếng Anh trên xe.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trên xe","example":"她在车上学英语。","example_pinyin":"/Tā zài chē shàng xué yīngyǔ/","example_meaning":"Cô ấy học tiếng Anh trên xe.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('车站', 'chēzhàn', 'Trạm xe', '车站离这里不远。', 'Chēzhàn lí zhè lǐ bù yuǎn', 'Trạm xe cách đây không xa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trạm xe","example":"车站离这里不远。","example_pinyin":"/Chēzhàn lí zhè lǐ bù yuǎn/","example_meaning":"Trạm xe cách đây không xa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('吃', 'chī', 'Ăn', '我喜欢吃苹果。', 'Wǒ xǐhuan chī píngguǒ', 'Tôi thích ăn táo.', 'Động từ', '[{"pos":"Động từ","meaning":"Ăn","example":"我喜欢吃苹果。","example_pinyin":"/Wǒ xǐhuan chī píngguǒ/","example_meaning":"Tôi thích ăn táo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('吃饭', 'chīfàn', 'Ăn cơm', '我们一起去吃饭吧。', 'Wǒmen yīqǐ qù chīfàn ba', 'Chúng ta cùng nhau đi ăn cơm nhé.', 'Động từ', '[{"pos":"Động từ","meaning":"Ăn cơm","example":"我们一起去吃饭吧。","example_pinyin":"/Wǒmen yīqǐ qù chīfàn ba/","example_meaning":"Chúng ta cùng nhau đi ăn cơm nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出', 'chū', 'Đi; xuất phát', '他出去买东西了。', 'Tā chū qù mǎi dōngxi le', 'Anh ấy ra ngoài mua đồ ăn rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi; xuất phát","example":"他出去买东西了。","example_pinyin":"/Tā chū qù mǎi dōngxi le/","example_meaning":"Anh ấy ra ngoài mua đồ ăn rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出来', 'chūlái', 'Ra; ra đây', '你出来，我跟你说句话。', 'Nǐ chūlái，wǒ gēn nǐ shuō jù huà', 'Anh ra đây tôi nói chuyện với anh.', 'Động từ', '[{"pos":"Động từ","meaning":"Ra; ra đây","example":"你出来，我跟你说句话。","example_pinyin":"/Nǐ chūlái，wǒ gēn nǐ shuō jù huà/","example_meaning":"Anh ra đây tôi nói chuyện với anh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出去', 'chūqù', 'Ra; ra ngoài', '我们一起出去玩儿吧。', 'Wǒmen yīqǐ chūqù wánr ba', 'Chúng ta cùng nhau đi chơi đi.', 'Động từ', '[{"pos":"Động từ","meaning":"Ra; ra ngoài","example":"我们一起出去玩儿吧。","example_pinyin":"/Wǒmen yīqǐ chūqù wánr ba/","example_meaning":"Chúng ta cùng nhau đi chơi đi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('穿', 'chuān', 'Mặc; đi; mang; đeo', '今天我穿了件新衣服。', 'Jīntiān wǒ chuān le jiàn xīn yīfu', 'Hôm nay tôi mặc quần áo mới.', 'Động từ', '[{"pos":"Động từ","meaning":"Mặc; đi; mang; đeo","example":"今天我穿了件新衣服。","example_pinyin":"/Jīntiān wǒ chuān le jiàn xīn yīfu/","example_meaning":"Hôm nay tôi mặc quần áo mới.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('床', 'chuáng', 'Giường', '我很累，想躺在床上。', 'Wǒ hěn lèi, xiǎng tǎng zài chuáng shàng', 'Tôi rất mệt, muốn nằm trên giường.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Giường","example":"我很累，想躺在床上。","example_pinyin":"/Wǒ hěn lèi, xiǎng tǎng zài chuáng shàng/","example_meaning":"Tôi rất mệt, muốn nằm trên giường.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('次', 'cì', 'Lần; lượt; đợt', '这是我第一次来这里。', 'Zhè shì wǒ dì yī cì lái zhè lǐ', 'Đây là lần đầu tiên tôi đến đây.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Lần; lượt; đợt","example":"这是我第一次来这里。","example_pinyin":"/Zhè shì wǒ dì yī cì lái zhè lǐ/","example_meaning":"Đây là lần đầu tiên tôi đến đây.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('从', 'cóng', 'Từ; bắt đầu từ', '我从家里走到学校。', 'Wǒ cóng jiālǐ zǒu dào xuéxiào', 'Tôi đi bộ từ nhà đến trường.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Từ; bắt đầu từ","example":"我从家里走到学校。","example_pinyin":"/Wǒ cóng jiālǐ zǒu dào xuéxiào/","example_meaning":"Tôi đi bộ từ nhà đến trường.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('错', 'cuò', 'Sai; nhầm; không đúng', '你做错了。', 'Nǐ zuò cuò le', 'Bạn làm sai rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Sai; nhầm; không đúng","example":"你做错了。","example_pinyin":"/Nǐ zuò cuò le/","example_meaning":"Bạn làm sai rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打', 'dǎ', 'Gõ; đánh; đập;...', '我弟弟在打篮球。', 'Wǒ dìdi zài dǎqiú', 'Em trai tôi đang chơi bóng rổ.', 'Động từ', '[{"pos":"Động từ","meaning":"Gõ; đánh; đập;...","example":"我弟弟在打篮球。","example_pinyin":"/Wǒ dìdi zài dǎqiú/","example_meaning":"Em trai tôi đang chơi bóng rổ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打车', 'dǎchē', 'Bắt xe; gọi xe (taxi)', '我们打车去机场。', 'Wǒmen dǎ chē qù jīchǎng', 'Chúng ta bắt xe đến sân bay.', 'Động từ', '[{"pos":"Động từ","meaning":"Bắt xe; gọi xe (taxi)","example":"我们打车去机场。","example_pinyin":"/Wǒmen dǎ chē qù jīchǎng/","example_meaning":"Chúng ta bắt xe đến sân bay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打电话', 'dǎ diànhuà', 'Gọi điện thoại', '等一下，我要打电话问问。', 'Děng yīxià, wǒ yào dǎ diànhuà wèn wèn', 'Đợi chút nha, tôi cần gọi điện thoại hỏi thăm.', 'Động từ', '[{"pos":"Động từ","meaning":"Gọi điện thoại","example":"等一下，我要打电话问问。","example_pinyin":"/Děng yīxià, wǒ yào dǎ diànhuà wèn wèn/","example_meaning":"Đợi chút nha, tôi cần gọi điện thoại hỏi thăm.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打开', 'dǎkāi', 'Mở ra', '请你把门打开。', 'Qǐng nǐ bǎ mén dǎkāi', 'Xin bạn hãy mở cửa ra.', 'Động từ', '[{"pos":"Động từ","meaning":"Mở ra","example":"请你把门打开。","example_pinyin":"/Qǐng nǐ bǎ mén dǎkāi/","example_meaning":"Xin bạn hãy mở cửa ra.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打球', 'dǎqiú', 'Đánh bóng; chơi bóng', '他们很喜欢打球。', 'Tā xǐhuān dǎ lánqiú', 'Cậu ấy thích chơi bóng rổ.', 'Động từ', '[{"pos":"Động từ","meaning":"Đánh bóng; chơi bóng","example":"他们很喜欢打球。","example_pinyin":"/Tā xǐhuān dǎ lánqiú/","example_meaning":"Cậu ấy thích chơi bóng rổ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大', 'dà', 'Lớn; to', '这个房子很大。', 'Zhège fángzi hěn dà', 'Căn nhà này rất lớn.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Lớn; to","example":"这个房子很大。","example_pinyin":"/Zhège fángzi hěn dà/","example_meaning":"Căn nhà này rất lớn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大学', 'dàxué', 'Đại học', '他在北京大学学习。', 'Tā zài Běijīng dàxué xuéxí', 'Anh ấy học ở Đại học Bắc Kinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đại học","example":"他在北京大学学习。","example_pinyin":"/Tā zài Běijīng dàxué xuéxí/","example_meaning":"Anh ấy học ở Đại học Bắc Kinh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大学生', 'dàxuéshēng', 'Sinh viên đại học', '我是大学生。', 'Wǒ shì dàxuéshēng', 'Tôi là sinh viên đại học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sinh viên đại học","example":"我是大学生。","example_pinyin":"/Wǒ shì dàxuéshēng/","example_meaning":"Tôi là sinh viên đại học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('到', 'dào', 'Đến', '我们到达了目的地。', 'Wǒmen dàodá le mùdìdì', 'Chúng ta đã đến nơi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đến","example":"我们到达了目的地。","example_pinyin":"/Wǒmen dàodá le mùdìdì/","example_meaning":"Chúng ta đã đến nơi.","is_approved":true}]', 'HSK1');
