INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地', 'de', 'Mà, một cách', '孩子们快乐地唱歌。', 'Háizimen kuàilè de chànggē', 'Mấy đứa nhỏ vui vẻ hát ca.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Mà, một cách","example":"孩子们快乐地唱歌。","example_pinyin":"/Háizimen kuàilè de chànggē/","example_meaning":"Mấy đứa nhỏ vui vẻ hát ca.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('的', 'de', 'Của (chỉ sở hữu)', '这是我的书。', 'Zhè shì wǒ de shū', 'Đây là sách của tôi.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Của (chỉ sở hữu)","example":"这是我的书。","example_pinyin":"/Zhè shì wǒ de shū/","example_meaning":"Đây là sách của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('等', 'děng', 'Đợi; chờ; chờ đợi', '我在等她的电话。', 'Wǒ zài děng tā de diànhuà', 'Tôi đang đợi cuộc gọi của cô ấy.', 'Động từ', '[{"pos":"Động từ","meaning":"Đợi; chờ; chờ đợi","example":"我在等她的电话。","example_pinyin":"/Wǒ zài děng tā de diànhuà/","example_meaning":"Tôi đang đợi cuộc gọi của cô ấy.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地', 'dì', 'Đất; trái đất', '地球上有许多不同的生物。', 'Dìqiú shàng yǒu xǔduō bùtóng de shēngwù', 'Trên Trái Đất có rất nhiều sinh vật khác nhau.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đất; trái đất","example":"地球上有许多不同的生物。","example_pinyin":"/Dìqiú shàng yǒu xǔduō bùtóng de shēngwù/","example_meaning":"Trên Trái Đất có rất nhiều sinh vật khác nhau.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地点', 'dìdiǎn', 'Địa điểm; nơi chốn', '会议的地点已经确定了。', 'Huìyì de dìdiǎn yǐjīng quèdìng le', 'Địa điểm cuộc họp đã được xác định.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Địa điểm; nơi chốn","example":"会议的地点已经确定了。","example_pinyin":"/Huìyì de dìdiǎn yǐjīng quèdìng le/","example_meaning":"Địa điểm cuộc họp đã được xác định.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地方', 'dìfāng', 'Bản xứ, bản địa', '他是这个地方的人。', 'Tā shì zhège dìfāng de rén', 'Anh ấy là người bản địa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bản xứ, bản địa","example":"他是这个地方的人。","example_pinyin":"/Tā shì zhège dìfāng de rén/","example_meaning":"Anh ấy là người bản địa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地上', 'dìshàng', 'Mặt đất; dưới đất', '地上有很多树叶。', 'Dìshàng yǒu hěnduō shùyè', 'Dưới đất có rất nhiều lá cây.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mặt đất; dưới đất","example":"地上有很多树叶。","example_pinyin":"/Dìshàng yǒu hěnduō shùyè/","example_meaning":"Dưới đất có rất nhiều lá cây.","is_approved":true}]', 'HSK1');
