INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('对', 'duì', 'Đúng; chính xác', '你的答案是对的。', 'Nǐ de dá''àn shì duì de', 'Câu trả lời của bạn là đúng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Đúng; chính xác","example":"你的答案是对的。","example_pinyin":"/Nǐ de dá''àn shì duì de/","example_meaning":"Câu trả lời của bạn là đúng.","is_approved":true}]', 'HSK1');
