INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多', 'duō', 'Nhiều; rất nhiều', '今天的作业不太多。', 'Jīntiān de zuòyè bù tài duō', 'Bài tập hôm nay không nhiều lắm.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nhiều; rất nhiều","example":"今天的作业不太多。","example_pinyin":"/Jīntiān de zuòyè bù tài duō/","example_meaning":"Bài tập hôm nay không nhiều lắm.","is_approved":true},{"pos":"Động từ","meaning":"Dư ra; thừa ra","example":"今天的水果多了一些。","example_pinyin":"/Jīntiān de shuǐguǒ duōle yīxiē/","example_meaning":"Hôm nay, trái cây còn dư một ít.","is_approved":true}]', 'HSK1');
