INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('饭', 'fàn', 'Cơm; bữa', '我还没吃晚饭呢。

他每天都吃三顿饭。', 'Wǒ hái méi chī wǎnfàn ne

Tā měitiān dōu chī sān dùn fàn', 'Tôi vẫn chưa ăn cơm tối. 

Mỗi ngày anh ấy đều ăn ba bữa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cơm; bữa","example":"我还没吃晚饭呢。\n\n他每天都吃三顿饭。","example_pinyin":"/Wǒ hái méi chī wǎnfàn ne/\n\n/Tā měitiān dōu chī sān dùn fàn/","example_meaning":"Tôi vẫn chưa ăn cơm tối. \n\nMỗi ngày anh ấy đều ăn ba bữa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('饭店', 'fàndiàn', 'Quán cơm; nhà hàng', '这家饭店的菜很好吃。', 'Zhè jiā fàndiàn de cài hěn hǎochī', 'Đồ ăn của nhà hàng này rất ngon.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Quán cơm; nhà hàng","example":"这家饭店的菜很好吃。","example_pinyin":"/Zhè jiā fàndiàn de cài hěn hǎochī/","example_meaning":"Đồ ăn của nhà hàng này rất ngon.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('房间', 'fángjiān', 'Căn phòng', '这是我的房间。', 'Zhè shì wǒ de fángjiān', 'Đây là phòng của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Căn phòng","example":"这是我的房间。","example_pinyin":"/Zhè shì wǒ de fángjiān/","example_meaning":"Đây là phòng của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('房子', 'fángzi', 'Căn nhà; nhà', '他们买了一套新房子。', 'Tāmen mǎi le yī tào xīn fángzi', 'Họ đã mua một căn nhà mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Căn nhà; nhà","example":"他们买了一套新房子。","example_pinyin":"/Tāmen mǎi le yī tào xīn fángzi/","example_meaning":"Họ đã mua một căn nhà mới.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('放', 'fàng', 'Đặt; để', '请把书放在桌子上。', 'Qǐng bǎ shū fàng zài zhuōzi shàng', 'Vui lòng đặt quyển sách lên bàn.', 'Động từ', '[{"pos":"Động từ","meaning":"Đặt; để","example":"请把书放在桌子上。","example_pinyin":"/Qǐng bǎ shū fàng zài zhuōzi shàng/","example_meaning":"Vui lòng đặt quyển sách lên bàn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('放假', 'fàngjià', 'Nghỉ, nghỉ lễ', '放假了，我们一起去玩吧。', 'Fàngjià le, wǒmen yīqǐ qù wán ba', 'Nghỉ lễ rồi, chúng ta cùng đi chơi nhé.', 'Động từ', '[{"pos":"Động từ","meaning":"Nghỉ, nghỉ lễ","example":"放假了，我们一起去玩吧。","example_pinyin":"/Fàngjià le, wǒmen yīqǐ qù wán ba/","example_meaning":"Nghỉ lễ rồi, chúng ta cùng đi chơi nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('放学', 'fàngxué', 'Tan học', '我们下午四点半放学。', 'Wǒmen xiàwǔ sì diǎn bàn fàngxué', 'Chúng tôi tan học lúc 4 giờ 30 chiều.', 'Động từ', '[{"pos":"Động từ","meaning":"Tan học","example":"我们下午四点半放学。","example_pinyin":"/Wǒmen xiàwǔ sì diǎn bàn fàngxué/","example_meaning":"Chúng tôi tan học lúc 4 giờ 30 chiều.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('飞', 'fēi', 'Bay', '小鸟在天上飞得很快。', 'Xiǎo niǎo zài tiān shàng fēi de hěn kuài', 'Con chim nhỏ bay rất nhanh trên trời.', 'Động từ', '[{"pos":"Động từ","meaning":"Bay","example":"小鸟在天上飞得很快。","example_pinyin":"/Xiǎo niǎo zài tiān shàng fēi de hěn kuài/","example_meaning":"Con chim nhỏ bay rất nhanh trên trời.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('飞机', 'fēijī', 'Máy bay', '我第一次坐飞机时特别开心。', 'Wǒ dì yī cì zuò fēijī shí tèbié kāixīn', 'Lần đầu tiên tôi đi máy bay, tôi rất vui mừng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Máy bay","example":"我第一次坐飞机时特别开心。","example_pinyin":"/Wǒ dì yī cì zuò fēijī shí tèbié kāixīn/","example_meaning":"Lần đầu tiên tôi đi máy bay, tôi rất vui mừng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('非常', 'fēicháng', 'Đặc biệt; rất; vô cùng', '这个地方非常漂亮。', 'Zhège dìfāng fēicháng piàoliang', 'Nơi này cực kỳ đẹp.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Đặc biệt; rất; vô cùng","example":"这个地方非常漂亮。","example_pinyin":"/Zhège dìfāng fēicháng piàoliang/","example_meaning":"Nơi này cực kỳ đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('分', 'fēn', 'Điểm số', '这次考试我考了100分。', 'Zhè cì kǎoshì wǒ kǎole 100 fēn', 'Kỳ thi lần này tôi thi được 100 điểm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Điểm số","example":"这次考试我考了100分。","example_pinyin":"/Zhè cì kǎoshì wǒ kǎole 100 fēn/","example_meaning":"Kỳ thi lần này tôi thi được 100 điểm.","is_approved":true},{"pos":"Lượng từ","meaning":"Phần\n\nphút","example":"这个蛋糕有八分。\n\n现在是三点十分。","example_pinyin":"/Zhège dàngāo yǒu bā fēn/ \n\n/Xiànzài shì sān diǎn shí fēn/","example_meaning":"Chiếc bánh này có tám phần.\n\nBây giờ là 3 giờ 10 phút.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('风', 'fēng', 'Gió', '今天的风很大，不要出去。', 'Jīntiān de fēng hěn dà, bù yào chūqù', 'Hôm nay gió lớn, đừng ra ngoài.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Gió","example":"今天的风很大，不要出去。","example_pinyin":"/Jīntiān de fēng hěn dà, bù yào chūqù/","example_meaning":"Hôm nay gió lớn, đừng ra ngoài.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干', 'gān', 'Khô; cạn', '这件衣服干了，可以穿了。', 'Zhè jiàn yīfu gān le, kěyǐ chuān le', 'Quần áo này khô rồi, có thể mặc rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Khô; cạn","example":"这件衣服干了，可以穿了。","example_pinyin":"/Zhè jiàn yīfu gān le, kěyǐ chuān le/","example_meaning":"Quần áo này khô rồi, có thể mặc rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干净', 'gānjìng', 'Sạch sẽ, gọn gàng', '你的房间很干净。', 'Nǐ de fángjiān hěn gānjìng', 'Phòng của bạn rất sạch sẽ.', NULL, '[{"pos":"","meaning":"Sạch sẽ, gọn gàng","example":"你的房间很干净。","example_pinyin":"/Nǐ de fángjiān hěn gānjìng/","example_meaning":"Phòng của bạn rất sạch sẽ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干', 'gàn', 'Quấy rầy; làm loạn

uống cạn; uống sạch', '他总干乱我的计划。

咱们干了这杯酒吧。', 'Tā zǒng gān luàn wǒ de jìhuà

