INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干什么', 'gàn shénme', 'Làm gì thế; tại sao', '你干什么不早说呀?', 'Nǐ gànshénme bù zǎo shuō ya', 'Tại sao bạn không nói sớm?', 'Động từ', '[{"pos":"Động từ","meaning":"Làm gì thế; tại sao","example":"你干什么不早说呀?","example_pinyin":"/Nǐ gànshénme bù zǎo shuō ya/","example_meaning":"Tại sao bạn không nói sớm?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('高', 'gāo', 'Cao', '你比我高一点儿。', 'Nǐ bǐ wǒ gāo yìdiǎnr', 'Bạn cao hơn tôi một chút.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Cao","example":"你比我高一点儿。","example_pinyin":"/Nǐ bǐ wǒ gāo yìdiǎnr/","example_meaning":"Bạn cao hơn tôi một chút.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('高兴', 'gāoxìng', 'Vui mừng; háo hức', '今天我很高兴。', 'Jīntiān wǒ hěn gāoxìng', 'Hôm nay tôi rất vui.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Vui mừng; háo hức","example":"今天我很高兴。","example_pinyin":"/Jīntiān wǒ hěn gāoxìng/","example_meaning":"Hôm nay tôi rất vui.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('告诉', 'gàosu', 'Nói; bày tỏ', '妈妈告诉我早点回家。', 'Māma gàosu wǒ zǎodiǎn huíjiā', 'Mẹ bảo tôi về nhà sớm.', 'Động từ', '[{"pos":"Động từ","meaning":"Nói; bày tỏ","example":"妈妈告诉我早点回家。","example_pinyin":"/Māma gàosu wǒ zǎodiǎn huíjiā/","example_meaning":"Mẹ bảo tôi về nhà sớm.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('哥哥  | 哥', 'gēge  |  gē', 'Anh trai', '我的哥哥比我大五岁。', 'Wǒ de gēge bǐ wǒ dà wǔ suì', 'Anh trai tôi lớn hơn tôi năm tuổi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Anh trai","example":"我的哥哥比我大五岁。","example_pinyin":"/Wǒ de gēge bǐ wǒ dà wǔ suì/","example_meaning":"Anh trai tôi lớn hơn tôi năm tuổi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('歌', 'gē', 'Hát; ca', '这首歌很好听。', 'Zhè shǒu gē hěn hǎotīng', 'Bài hát này rất hay.', 'Động từ', '[{"pos":"Động từ","meaning":"Hát; ca","example":"这首歌很好听。","example_pinyin":"/Zhè shǒu gē hěn hǎotīng/","example_meaning":"Bài hát này rất hay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('个', 'gè', 'Cái này', '我买了一个新手机。', 'Wǒ mǎi le yī gè xīn shǒujī', 'Tôi đã mua một chiếc điện thoại mới.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Cái này","example":"我买了一个新手机。","example_pinyin":"/Wǒ mǎi le yī gè xīn shǒujī/","example_meaning":"Tôi đã mua một chiếc điện thoại mới.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('给', 'gěi', 'Đưa', '妈妈给我买了一本书。', 'Māma gěi wǒ mǎi le yī běn shū', 'Mẹ đã mua cho tôi một quyển sách.', 'Động từ', '[{"pos":"Động từ","meaning":"Đưa","example":"妈妈给我买了一本书。","example_pinyin":"/Māma gěi wǒ mǎi le yī běn shū/","example_meaning":"Mẹ đã mua cho tôi một quyển sách.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('跟', 'gēn', 'Cùng; với', '我跟朋友一起去旅行。', 'Wǒ gēn péngyǒu yīqǐ qù lǚxíng', 'Tôi đi du lịch cùng bạn bè.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Cùng; với","example":"我跟朋友一起去旅行。","example_pinyin":"/Wǒ gēn péngyǒu yīqǐ qù lǚxíng/","example_meaning":"Tôi đi du lịch cùng bạn bè.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('工人', 'gōngrén', 'Công nhân', '工人们每天都努力工作。', 'Gōngrénmen měitiān dōu nǔlì gōngzuò', 'Những công nhân làm việc chăm chỉ mỗi ngày.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Công nhân","example":"工人们每天都努力工作。","example_pinyin":"/Gōngrénmen měitiān dōu nǔlì gōngzuò/","example_meaning":"Những công nhân làm việc chăm chỉ mỗi ngày.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('工作', 'gōngzuò', 'Công việc', '他的工作非常忙。', 'Tā de gōngzuò fēicháng máng', 'Công việc của anh ấy rất bận.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Công việc","example":"他的工作非常忙。","example_pinyin":"/Tā de gōngzuò fēicháng máng/","example_meaning":"Công việc của anh ấy rất bận.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('关', 'guān', 'Đóng; tắt', '睡觉前别忘了关灯。', 'Shuìjiào qián bié wàngle guān dēng', 'Trước khi ngủ đừng quên tắt đèn.', 'Động từ', '[{"pos":"Động từ","meaning":"Đóng; tắt","example":"睡觉前别忘了关灯。","example_pinyin":"/Shuìjiào qián bié wàngle guān dēng/","example_meaning":"Trước khi ngủ đừng quên tắt đèn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('关上', 'guān shàng', 'Đóng; đóng vào; đóng lại', '请关上门，谢谢你！', 'Qǐng guānshàng mén, xièxiè nǐ', 'Hãy đóng cửa lại, cảm ơn bạn.', 'Động từ', '[{"pos":"Động từ","meaning":"Đóng; đóng vào; đóng lại","example":"请关上门，谢谢你！","example_pinyin":"/Qǐng guānshàng mén, xièxiè nǐ/","example_meaning":"Hãy đóng cửa lại, cảm ơn bạn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('贵', 'guì', 'Đắt; mắc', '这件衣服太贵了。', 'Zhè jiàn yīfu tài guì le', 'Bộ quần áo này quá đắt!', 'Tính từ', '[{"pos":"Tính từ","meaning":"Đắt; mắc","example":"这件衣服太贵了。","example_pinyin":"/Zhè jiàn yīfu tài guì le/","example_meaning":"Bộ quần áo này quá đắt!","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('国', 'guó', 'Nước; quốc gia', '中国的美食非常有名。', 'Zhōngguó de měishí fēicháng yǒumíng', 'Ẩm thực của Trung Quốc rất nổi tiếng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nước; quốc gia","example":"中国的美食非常有名。","example_pinyin":"/Zhōngguó de měishí fēicháng yǒumíng/","example_meaning":"Ẩm thực của Trung Quốc rất nổi tiếng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('国家', 'guó jiā', 'Quốc gia', '我爱我的国家。', 'Wǒ ài wǒ de guójiā', 'Tôi yêu đất nước của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Quốc gia","example":"我爱我的国家。","example_pinyin":"/Wǒ ài wǒ de guójiā/","example_meaning":"Tôi yêu đất nước của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('国外', 'guó wài', 'Nước ngoài', '他在国外上大学。', 'Tā zài guówài shàng dàxué', 'Anh ấy học đại học ở nước ngoài.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nước ngoài","example":"他在国外上大学。","example_pinyin":"/Tā zài guówài shàng dàxué/","example_meaning":"Anh ấy học đại học ở nước ngoài.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('过', 'guò', 'Qua; đi qua; vượt qua', '我去过中国三次。', 'Wǒ qù guò Zhōngguó sān cì', 'Tôi đã đến Trung Quốc ba lần.', 'Động từ', '[{"pos":"Động từ","meaning":"Qua; đi qua; vượt qua","example":"我去过中国三次。","example_pinyin":"/Wǒ qù guò Zhōngguó sān cì/","example_meaning":"Tôi đã đến Trung Quốc ba lần.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('还', 'hái', 'Vẫn; còn; vẫn còn', '他有一个哥哥，还有一个妹妹。', 'Tā yǒu yī gè gēge, hái yǒu yī gè mèimei', 'Cậu ấy có một anh trai, còn có một em gái nữa.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Vẫn; còn; vẫn còn","example":"他有一个哥哥，还有一个妹妹。","example_pinyin":"/Tā yǒu yī gè gēge, hái yǒu yī gè mèimei/","example_meaning":"Cậu ấy có một anh trai, còn có một em gái nữa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('还是', 'hái shì', 'Vẫn; còn; vẫn còn', '你想喝茶还是咖啡？', 'Nǐ xiǎng hē chá háishì kāfēi?', 'Bạn muốn uống trà hay cà phê?', 'Phó từ', '[{"pos":"Phó từ","meaning":"Vẫn; còn; vẫn còn","example":"你想喝茶还是咖啡？","example_pinyin":"/Nǐ xiǎng hē chá háishì kāfēi?/","example_meaning":"Bạn muốn uống trà hay cà phê?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('还有', 'hái yǒu', 'Vẫn; còn; vẫn còn', '我家里还有两只猫。', 'Wǒ jiālǐ hái yǒu liǎng zhī māo', 'Nhà tôi còn có hai con mèo.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Vẫn; còn; vẫn còn","example":"我家里还有两只猫。","example_pinyin":"/Wǒ jiālǐ hái yǒu liǎng zhī māo/","example_meaning":"Nhà tôi còn có hai con mèo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('孩子', 'hái zi', 'Con; bọn trẻ; trẻ em', '孩子们在公园玩儿。', 'Háizimen zài gōngyuán wánr', 'Mấy đứa trẻ đang chơi trong công viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Con; bọn trẻ; trẻ em","example":"孩子们在公园玩儿。","example_pinyin":"/Háizimen zài gōngyuán wánr/","example_meaning":"Mấy đứa trẻ đang chơi trong công viên.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('汉语', 'Hàn yǔ', 'Tiếng hán; hán ngữ', '他的汉语说得很好。', 'Tā de Hànyǔ shuō de hěn hăo', 'Anh ấy nói tiếng Trung rất giỏi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tiếng hán; hán ngữ","example":"他的汉语说得很好。","example_pinyin":"/Tā de Hànyǔ shuō de hěn hăo/","example_meaning":"Anh ấy nói tiếng Trung rất giỏi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('汉字', 'Hàn zì', 'Chữ hán', '我会写汉字。', 'Wǒ huì xiě Hànzì', 'Tôi biết viết chữ Hán.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chữ hán","example":"我会写汉字。","example_pinyin":"/Wǒ huì xiě Hànzì/","example_meaning":"Tôi biết viết chữ Hán.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('好', 'hǎo', 'Tốt; hay; ổn', '你身体好吗？', 'Nǐ shēntǐ hǎo ma', 'Bạn có khỏe không?', 'Tính từ', '[{"pos":"Tính từ","meaning":"Tốt; hay; ổn","example":"你身体好吗？","example_pinyin":"/Nǐ shēntǐ hǎo ma/","example_meaning":"Bạn có khỏe không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('好吃', 'hǎo chī', 'Ngon; ngon miệng', '这家餐厅的菜非常好吃。', 'Zhè jiā cāntīng de cài fēicháng hǎochī', 'Món ăn của nhà hàng này rất ngon.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Ngon; ngon miệng","example":"这家餐厅的菜非常好吃。","example_pinyin":"/Zhè jiā cāntīng de cài fēicháng hǎochī/","example_meaning":"Món ăn của nhà hàng này rất ngon.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('好看', 'hǎo kàn', 'Đẹp; hay; thú vị', '这本书很好看，我喜欢。', 'Zhè běn shū hěn hǎokàn, wǒ xǐhuān', 'Cuốn sách này rất hay, tôi thích.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Đẹp; hay; thú vị","example":"这本书很好看，我喜欢。","example_pinyin":"/Zhè běn shū hěn hǎokàn, wǒ xǐhuān/","example_meaning":"Cuốn sách này rất hay, tôi thích.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('好听', 'hǎotīng', 'Hay; dễ nghe; êm tai (âm thanh)', '这首歌很好听。', 'Zhè shǒu gē hěn hǎotīng', 'Bài hát này rất hay.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Hay; dễ nghe; êm tai (âm thanh)","example":"这首歌很好听。","example_pinyin":"/Zhè shǒu gē hěn hǎotīng/","example_meaning":"Bài hát này rất hay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('好玩儿', 'hǎowánr', 'Hay; thú vị; thích thú', '这个游戏很好玩儿。', 'Zhège yóuxì hěn hǎowánr', 'Trò chơi này rất vui.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Hay; thú vị; thích thú","example":"这个游戏很好玩儿。","example_pinyin":"/Zhège yóuxì hěn hǎowánr/","example_meaning":"Trò chơi này rất vui.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('号', 'hào', 'Số; số thứ tự', '你的房间号是多少？', 'Nǐ de fángjiān hào shì duōshǎo', 'Số phòng của bạn là bao nhiêu?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Số; số thứ tự","example":"你的房间号是多少？","example_pinyin":"/Nǐ de fángjiān hào shì duōshǎo/","example_meaning":"Số phòng của bạn là bao nhiêu?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('喝', 'hē', 'Uống', '我每天早上都喝咖啡。', 'Wǒ měitiān zǎoshang dōu hē kāfēi', 'Mỗi sáng tôi đều uống cà phê.', 'Động từ', '[{"pos":"Động từ","meaning":"Uống","example":"我每天早上都喝咖啡。","example_pinyin":"/Wǒ měitiān zǎoshang dōu hē kāfēi/","example_meaning":"Mỗi sáng tôi đều uống cà phê.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('和', 'hé', 'Và; với', '我买了一本书和一件衣服。', 'Wǒ mǎile yī běn shū hé yī jiàn yīfú', 'Tôi đã mua 1 cuốn sách và 1 bộ quần áo.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Và; với","example":"我买了一本书和一件衣服。","example_pinyin":"/Wǒ mǎile yī běn shū hé yī jiàn yīfú/","example_meaning":"Tôi đã mua 1 cuốn sách và 1 bộ quần áo.","is_approved":true},{"pos":"Giới từ","meaning":"Với; cùng","example":"我和他一起去公园散步。","example_pinyin":"/Wǒ hé tā yīqǐ qù gōngyuán sànbù/","example_meaning":"Tôi đi dạo với cậu ấy trong công viên.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('很', 'hěn', 'Rất, nhiều', '今天的课文很长， 生词很多。', 'Jīntiān de kèwén hěn cháng, shēngcí hěnduō', 'Hôm nay bài khoá rất dài, nên từ mới rất nhiều.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Rất, nhiều","example":"今天的课文很长， 生词很多。","example_pinyin":"/Jīntiān de kèwén hěn cháng, shēngcí hěnduō/","example_meaning":"Hôm nay bài khoá rất dài, nên từ mới rất nhiều.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('后 | 后边', 'hòu | hòubian', 'Sau; phía sau', '书店在学校的后边。', 'Shūdiàn zài xuéxiào de hòubian', 'Hiệu sách ở phía sau trường học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sau; phía sau","example":"书店在学校的后边。","example_pinyin":"/Shūdiàn zài xuéxiào de hòubian/","example_meaning":"Hiệu sách ở phía sau trường học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('后天', 'hòutiān', 'Ngày hôm sau', '我们后天去北京。', 'Wǒmen hòutiān qù Běijīng', 'Chúng tôi sẽ đi Bắc Kinh vào ngày kia.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ngày hôm sau","example":"我们后天去北京。","example_pinyin":"/Wǒmen hòutiān qù Běijīng/","example_meaning":"Chúng tôi sẽ đi Bắc Kinh vào ngày kia.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('花', 'huā', 'Hoa; bông hoa', '花园里有很多花。', 'Huāyuán lǐ yǒu hěn duō huā', 'Trong vườn có rất nhiều hoa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Hoa; bông hoa","example":"花园里有很多花。","example_pinyin":"/Huāyuán lǐ yǒu hěn duō huā/","example_meaning":"Trong vườn có rất nhiều hoa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('话', 'huà', 'Lời nói; ngôn từ', '她的话让我很高兴。', 'Tā de huà ràng wǒ hěn gāoxìng', 'Lời của cô ấy làm tôi rất vui.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lời nói; ngôn từ","example":"她的话让我很高兴。","example_pinyin":"/Tā de huà ràng wǒ hěn gāoxìng/","example_meaning":"Lời của cô ấy làm tôi rất vui.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('坏', 'huài', 'Hư; hư hỏng; xấu', '我的手机坏了，不能用。', 'Wǒ de shǒujī huài le, bù néng yòng', 'Điện thoại của tôi bị hỏng, không thể dùng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Hư; hư hỏng; xấu","example":"我的手机坏了，不能用。","example_pinyin":"/Wǒ de shǒujī huài le, bù néng yòng/","example_meaning":"Điện thoại của tôi bị hỏng, không thể dùng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('还', 'huán', 'Trả lại', '她明天把书还给图书馆。', 'Tā míngtiān bǎ shū huán gěi túshū guǎn', 'Ngày mai cô ấy sẽ đem sách trả lại cho thư viện', 'Động từ', '[{"pos":"Động từ","meaning":"Trả lại","example":"她明天把书还给图书馆。","example_pinyin":"/Tā míngtiān bǎ shū huán gěi túshū guǎn/","example_meaning":"Ngày mai cô ấy sẽ đem sách trả lại cho thư viện","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回', 'huí', 'Quay lại; quay về', '我每天六点回家。', 'Wǒ měitiān liù diǎn huí jiā', 'Tôi về nhà lúc 6 giờ mỗi ngày.', 'Động từ', '[{"pos":"Động từ","meaning":"Quay lại; quay về","example":"我每天六点回家。","example_pinyin":"/Wǒ měitiān liù diǎn huí jiā/","example_meaning":"Tôi về nhà lúc 6 giờ mỗi ngày.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回答', 'huídá', 'Trả lời', '请回答我的问题。', 'Qǐng huídá wǒ de wèntí', 'Hãy trả lời câu hỏi của tôi.', 'Động từ', '[{"pos":"Động từ","meaning":"Trả lời","example":"请回答我的问题。","example_pinyin":"/Qǐng huídá wǒ de wèntí/","example_meaning":"Hãy trả lời câu hỏi của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回到', 'huídào', 'Về đến; trở về', '他回到家了。', 'Tā huídào jiā le', 'Anh ấy đã về đến nhà rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Về đến; trở về","example":"他回到家了。","example_pinyin":"/Tā huídào jiā le/","example_meaning":"Anh ấy đã về đến nhà rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回家', 'huí jiā', 'Về nhà; đến nhà', '朋友们都回家了。', 'Péngyǒumen dōu huí jiā le', 'Các bạn tôi đều đã về nhà rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Về nhà; đến nhà","example":"朋友们都回家了。","example_pinyin":"/Péngyǒumen dōu huí jiā le/","example_meaning":"Các bạn tôi đều đã về nhà rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回来', 'huí lái', 'Trở lại', '他晚上七点回来。', 'Tā wǎnshàng qī diǎn huí lái', 'Anh ấy sẽ quay lại lúc 7 giờ tối.', 'Động từ', '[{"pos":"Động từ","meaning":"Trở lại","example":"他晚上七点回来。","example_pinyin":"/Tā wǎnshàng qī diǎn huí lái/","example_meaning":"Anh ấy sẽ quay lại lúc 7 giờ tối.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('回去', 'huí qù', 'Về; trở lại; đi về', '我们早点回去吧。', 'Wǒmen zǎodiǎn huí qù ba', 'Chúng ta về sớm một chút đi.', 'Động từ', '[{"pos":"Động từ","meaning":"Về; trở lại; đi về","example":"我们早点回去吧。","example_pinyin":"/Wǒmen zǎodiǎn huí qù ba/","example_meaning":"Chúng ta về sớm một chút đi.","is_approved":true}]', 'HSK1');
