INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('火车', 'huǒchē', 'Tàu hỏa; xe lửa', '我坐火车去北京。', 'Wǒ zuò huǒchē qù Běijīng', 'Tôi đi Bắc Kinh bằng tàu hỏa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tàu hỏa; xe lửa","example":"我坐火车去北京。","example_pinyin":"/Wǒ zuò huǒchē qù Běijīng/","example_meaning":"Tôi đi Bắc Kinh bằng tàu hỏa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('机场', 'jīchǎng', 'Sân bay', '他去机场接朋友。', 'Tā qù jīchǎng jiē péngyǒu', 'Anh ấy đến sân bay đón bạn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sân bay","example":"他去机场接朋友。","example_pinyin":"/Tā qù jīchǎng jiē péngyǒu/","example_meaning":"Anh ấy đến sân bay đón bạn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('机票', 'jīpiào', 'Vé máy bay', '你买机票了吗？', 'Nǐ mǎi jīpiào le ma', 'Bạn đã mua vé máy bay chưa?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Vé máy bay","example":"你买机票了吗？","example_pinyin":"/Nǐ mǎi jīpiào le ma/","example_meaning":"Bạn đã mua vé máy bay chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('鸡蛋', 'jīdàn', 'Trứng gà', '我买了一些鸡蛋。', 'Wǒ mǎi le yīxiē jīdàn', 'Tôi đã mua một vài quả trứng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trứng gà","example":"我买了一些鸡蛋。","example_pinyin":"/Wǒ mǎi le yīxiē jīdàn/","example_meaning":"Tôi đã mua một vài quả trứng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('几', 'jǐ', 'Mấy; bao nhiêu', '你有几个兄弟姐妹？', 'Nǐ yǒu jǐ gè xiōngdì jiěmèi', 'Bạn có mấy anh chị em?', 'Số từ', '[{"pos":"Số từ","meaning":"Mấy; bao nhiêu","example":"你有几个兄弟姐妹？","example_pinyin":"/Nǐ yǒu jǐ gè xiōngdì jiěmèi/","example_meaning":"Bạn có mấy anh chị em?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('记', 'jì', 'Nhớ', '我记不住这个汉字。', 'Wǒ jì bù zhù zhège hànzì', 'Tôi không nhớ được chữ Hán này.', 'Động từ', '[{"pos":"Động từ","meaning":"Nhớ","example":"我记不住这个汉字。","example_pinyin":"/Wǒ jì bù zhù zhège hànzì/","example_meaning":"Tôi không nhớ được chữ Hán này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('记得', 'jìde', 'Ghi nhớ', '你还记得他的生日吗？', 'Nǐ hái jìdé tā de shēngrì ma', 'Bạn còn nhớ sinh nhật của anh ấy không?', 'Động từ', '[{"pos":"Động từ","meaning":"Ghi nhớ","example":"你还记得他的生日吗？","example_pinyin":"/Nǐ hái jìdé tā de shēngrì ma/","example_meaning":"Bạn còn nhớ sinh nhật của anh ấy không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('记住', 'jìzhù', 'Nhớ; ghi nhớ', '请记住这个电话号码。', 'Qǐng jìzhù zhège diànhuà hàomǎ', 'Hãy nhớ số điện thoại này.', 'Động từ', '[{"pos":"Động từ","meaning":"Nhớ; ghi nhớ","example":"请记住这个电话号码。","example_pinyin":"/Qǐng jìzhù zhège diànhuà hàomǎ/","example_meaning":"Hãy nhớ số điện thoại này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('家', 'jiā', 'Nhà', '我家在上海。', 'Wǒ jiā zài Shànghǎi', 'Nhà tôi ở Thượng Hải.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nhà","example":"我家在上海。","example_pinyin":"/Wǒ jiā zài Shànghǎi/","example_meaning":"Nhà tôi ở Thượng Hải.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('家里', 'jiā lǐ', 'Trong nhà', '我家里有很多书。', 'Wǒ jiālǐ yǒu hěn duō shū', 'Trong nhà tôi có rất nhiều sách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trong nhà","example":"我家里有很多书。","example_pinyin":"/Wǒ jiālǐ yǒu hěn duō shū/","example_meaning":"Trong nhà tôi có rất nhiều sách.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('家人', 'jiārén', 'Người nhà', '我家人都喜欢吃中国菜。', 'Wǒ jiārén dōu xǐhuan chī Zhōngguó cài', 'Cả nhà tôi đều thích ăn đồ ăn Trung Quốc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người nhà","example":"我家人都喜欢吃中国菜。","example_pinyin":"/Wǒ jiārén dōu xǐhuan chī Zhōngguó cài/","example_meaning":"Cả nhà tôi đều thích ăn đồ ăn Trung Quốc.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('间', 'jiān', 'Giữa, ở giữa', '他们之间的感情很好。', 'Tāmen zhījiān de gǎnqíng hěn hǎo', 'Tình cảm giữa họ rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Giữa, ở giữa","example":"他们之间的感情很好。","example_pinyin":"/Tāmen zhījiān de gǎnqíng hěn hǎo/","example_meaning":"Tình cảm giữa họ rất tốt.","is_approved":true},{"pos":"Lượng từ","meaning":"Gian, buồng, phòng","example":"我家有三间卧室。","example_pinyin":"/Wǒjiā yǒu sān jiān wòshì/","example_meaning":"Nhà tôi có 3 phòng ngủ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('见', 'jiàn', 'Gặp', '我在公园见到朋友。', 'Wǒ zài gōngyuán jiàn dào péngyǒu', 'Tôi gặp bạn ở công viên.', 'Động từ', '[{"pos":"Động từ","meaning":"Gặp","example":"我在公园见到朋友。","example_pinyin":"/Wǒ zài gōngyuán jiàn dào péngyǒu/","example_meaning":"Tôi gặp bạn ở công viên.","is_approved":true}]', 'HSK1');
