INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('教', 'jiāo', 'Dạy, chỉ dạy', '她教我们英语。', 'Tā jiāo wǒmen Yīngyǔ', 'Cô ấy dạy chúng tôi tiếng Anh.', 'Động từ', '[{"pos":"Động từ","meaning":"Dạy, chỉ dạy","example":"她教我们英语。","example_pinyin":"/Tā jiāo wǒmen Yīngyǔ/","example_meaning":"Cô ấy dạy chúng tôi tiếng Anh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('叫', 'jiào', 'Gọi, kêu', '妈妈叫我回家。', 'Māmā jiào wǒ huí jiā', 'Mẹ gọi tôi về nhà.', 'Động từ', '[{"pos":"Động từ","meaning":"Gọi, kêu","example":"妈妈叫我回家。","example_pinyin":"/Māmā jiào wǒ huí jiā/","example_meaning":"Mẹ gọi tôi về nhà.","is_approved":true}]', 'HSK1');
