INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('姐姐', 'jiějie', 'Chị gái', '她是我的姐姐。', 'Tā shì wǒ de jiějie', 'Cô ấy là chị gái tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chị gái","example":"她是我的姐姐。","example_pinyin":"/Tā shì wǒ de jiějie/","example_meaning":"Cô ấy là chị gái tôi.","is_approved":true}]', 'HSK1');
