INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('今年', 'jīnnián', 'Năm nay', '今年是2025年。', 'Jīnnián shì 2025 nián', 'Năm nay là năm 2025.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Năm nay","example":"今年是2025年。","example_pinyin":"/Jīnnián shì 2025 nián/","example_meaning":"Năm nay là năm 2025.","is_approved":true}]', 'HSK1');
