INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('进', 'jìn', 'Vào, tiến vào, đi vào', '请进！', 'Qǐng jìn', 'Xin mời vào!', 'Động từ', '[{"pos":"Động từ","meaning":"Vào, tiến vào, đi vào","example":"请进！","example_pinyin":"/Qǐng jìn/","example_meaning":"Xin mời vào!","is_approved":true}]', 'HSK1');
