INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('就', 'jiù', 'Thì, liền, ngay lập tức', '他下班后就回家了。', 'Tā xiàbān hòu jiù huíjiā le', 'Anh ấy tan làm liền về nhà.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Thì, liền, ngay lập tức","example":"他下班后就回家了。","example_pinyin":"/Tā xiàbān hòu jiù huíjiā le/","example_meaning":"Anh ấy tan làm liền về nhà.","is_approved":true}]', 'HSK1');
