INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('渴', 'kě', 'Khát', '我口渴了，想喝水。', 'Wǒ kǒu kě le, xiǎng hē shuǐ', 'Tôi khát nước rồi, muốn uống nước.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Khát","example":"我口渴了，想喝水。","example_pinyin":"/Wǒ kǒu kě le, xiǎng hē shuǐ/","example_meaning":"Tôi khát nước rồi, muốn uống nước.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('课', 'kè', 'Tiết học, bài học', '今天的汉语课很有意思。', 'Jīntiān de Hànyǔ kè hěn yǒuyìsi', 'Bài học tiếng Trung hôm nay rất thú vị.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tiết học, bài học","example":"今天的汉语课很有意思。","example_pinyin":"/Jīntiān de Hànyǔ kè hěn yǒuyìsi/","example_meaning":"Bài học tiếng Trung hôm nay rất thú vị.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('课本', 'kèběn', 'Sách giáo khoa', '你带课本了吗？', 'Nǐ dài kèběn le ma', 'Bạn có mang sách giáo khoa không?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sách giáo khoa","example":"你带课本了吗？","example_pinyin":"/Nǐ dài kèběn le ma/","example_meaning":"Bạn có mang sách giáo khoa không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('课文', 'kèwén', 'Bài khóa (trong sách)', '请大家朗读课文。', 'Qǐng dàjiā lǎngdú kèwén', 'Mọi người vui lòng đọc to bài khóa.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bài khóa (trong sách)","example":"请大家朗读课文。","example_pinyin":"/Qǐng dàjiā lǎngdú kèwén/","example_meaning":"Mọi người vui lòng đọc to bài khóa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('口', 'kǒu', 'Miệng, mồm

cửa, cổng', '我用盐水漱口。

出口在左边，不要走错了。', 'Wǒ yòng yánshuǐ shù kǒu

Chūkǒu zài zuǒbiān, bùyào zǒu cuò le', 'Tôi dùng nước muối để súc miệng.

Cửa ra ở bên trái, đừng đi sai nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Miệng, mồm\n\ncửa, cổng","example":"我用盐水漱口。\n\n出口在左边，不要走错了。","example_pinyin":"/Wǒ yòng yánshuǐ shù kǒu/\n\n/Chūkǒu zài zuǒbiān, bùyào zǒu cuò le/","example_meaning":"Tôi dùng nước muối để súc miệng.\n\nCửa ra ở bên trái, đừng đi sai nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('快', 'kuài', 'Nhanh, mau', '火车快要来了。', 'Huǒchē kuài yào lái le', 'Tàu hỏa sắp đến rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nhanh, mau","example":"火车快要来了。","example_pinyin":"/Huǒchē kuài yào lái le/","example_meaning":"Tàu hỏa sắp đến rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('块', 'kuài', 'Viên, thỏi, miếng', '我喜欢吃糖块儿。', 'Wǒ xǐhuan chī táng kuàir', 'Tôi thích ăn kẹo viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Viên, thỏi, miếng","example":"我喜欢吃糖块儿。","example_pinyin":"/Wǒ xǐhuan chī táng kuàir/","example_meaning":"Tôi thích ăn kẹo viên.","is_approved":true},{"pos":"Lượng từ","meaning":"Khối, miếng, chiếc\n\ntờ, đồng (tiền)","example":"他买了三块手表。\n\n这本书卖五块钱。","example_pinyin":"/Tā mǎi le sān kuài shǒubiǎo/\n\n/Zhè běn shū mài wǔ kuài qián/","example_meaning":"Anh ấy đã mua ba chiếc đồng hồ.\n\nQuyển sách này bán năm đồng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('来', 'lái', 'Đến, tới', '你什么时候来我家?', 'Nǐ shénme shíhòu lái wǒ jiā', 'Khi nào bạn đến nhà tôi?', 'Động từ', '[{"pos":"Động từ","meaning":"Đến, tới","example":"你什么时候来我家?","example_pinyin":"/Nǐ shénme shíhòu lái wǒ jiā/","example_meaning":"Khi nào bạn đến nhà tôi?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('来到', 'láidào', 'Đến, đi đến', '他来到公司了。', 'Tā láidào gōngsī le', 'Anh ấy đến công ty rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đến, đi đến","example":"他来到公司了。","example_pinyin":"/Tā láidào gōngsī le/","example_meaning":"Anh ấy đến công ty rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老', 'lǎo', 'Già, cũ', '这辆车太老了。', 'Zhè liàng chē tài lǎo le', 'Chiếc xe này quá cũ rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Già, cũ","example":"这辆车太老了。","example_pinyin":"/Zhè liàng chē tài lǎo le/","example_meaning":"Chiếc xe này quá cũ rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老人', 'lǎorén', 'Người già', '老人喜欢在公园散步。', 'Lǎorén xǐhuan zài gōngyuán sànbù', 'Các cụ già thích đi dạo trong công viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người già","example":"老人喜欢在公园散步。","example_pinyin":"/Lǎorén xǐhuan zài gōngyuán sànbù/","example_meaning":"Các cụ già thích đi dạo trong công viên.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老师', 'lǎoshī', 'Giáo viên, thầy cô', '她是我们的汉语老师。', 'Tā shì wǒmen de Hànyǔ lǎoshī', 'Cô ấy là giáo viên tiếng Trung của chúng tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Giáo viên, thầy cô","example":"她是我们的汉语老师。","example_pinyin":"/Tā shì wǒmen de Hànyǔ lǎoshī/","example_meaning":"Cô ấy là giáo viên tiếng Trung của chúng tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('了', 'le', 'Rồi (biểu thị hành động đã hoàn thành)', '我吃了一个苹果。', 'Wǒ chī le yīgè píngguǒ', 'Tôi đã ăn một quả táo.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Rồi (biểu thị hành động đã hoàn thành)","example":"我吃了一个苹果。","example_pinyin":"/Wǒ chī le yīgè píngguǒ/","example_meaning":"Tôi đã ăn một quả táo.","is_approved":true}]', 'HSK1');
