INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('冷', 'lěng', 'Lạnh', '外面很冷，多穿点衣服。', 'Wàimiàn hěn lěng, duō chuān diǎn yīfu', 'Bên ngoài rất lạnh, mặc thêm áo vào.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Lạnh","example":"外面很冷，多穿点衣服。","example_pinyin":"/Wàimiàn hěn lěng, duō chuān diǎn yīfu/","example_meaning":"Bên ngoài rất lạnh, mặc thêm áo vào.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('里', 'lǐ', 'Trong, bên trong', '房间里有很多书。', 'Fángjiān lǐ yǒu hěn duō shū', 'Trong phòng có rất nhiều sách.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Trong, bên trong","example":"房间里有很多书。","example_pinyin":"/Fángjiān lǐ yǒu hěn duō shū/","example_meaning":"Trong phòng có rất nhiều sách.","is_approved":true}]', 'HSK1');
