INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('路上', 'lùshàng', 'Trên đường', '我在路上，看见了你。', 'Wǒ zài lùshàng, kànjiàn le nǐ', 'Tôi trên đường, nhìn thấy bạn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trên đường","example":"我在路上，看见了你。","example_pinyin":"/Wǒ zài lùshàng, kànjiàn le nǐ/","example_meaning":"Tôi trên đường, nhìn thấy bạn.","is_approved":true}]', 'HSK1');
