INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('忙', 'máng', 'Bận rộn', '他最近很忙。', 'Tā zuìjìn hěn máng', 'Dạo này anh ấy rất bận.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Bận rộn","example":"他最近很忙。","example_pinyin":"/Tā zuìjìn hěn máng/","example_meaning":"Dạo này anh ấy rất bận.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('毛', 'máo', 'Lông, tóc', '小狗的毛很软。', 'Xiǎogǒu de máo hěn ruǎn', 'Lông của chú chó con rất mềm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lông, tóc","example":"小狗的毛很软。","example_pinyin":"/Xiǎogǒu de máo hěn ruǎn/","example_meaning":"Lông của chú chó con rất mềm.","is_approved":true},{"pos":"Lượng từ","meaning":"Hào (đơn vị tiền tệ trung quốc)","example":"我口袋里有一毛钱。","example_pinyin":"/Wǒ kǒudài lǐ yǒuyī máo qián/","example_meaning":"Trong túi tôi có một hào.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('没', 'méi', 'Không có, chưa', '我今天没时间。', 'Wǒ jīntiān méi shíjiān', 'Hôm nay tôi không có thời gian (không rảnh).', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không có, chưa","example":"我今天没时间。","example_pinyin":"/Wǒ jīntiān méi shíjiān/","example_meaning":"Hôm nay tôi không có thời gian (không rảnh).","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('没关系', 'méi guānxi', 'Không sao đâu', '没关系，我没生气。', 'Méiguānxi, wǒ méi shēngqì', 'Không sao, tôi không giận đâu.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Không sao đâu","example":"没关系，我没生气。","example_pinyin":"/Méiguānxi, wǒ méi shēngqì/","example_meaning":"Không sao, tôi không giận đâu.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('没什么', 'méi shénme', 'Không có gì', '没什么好担心的。', 'Méi shénme hǎo dānxīn de', 'Không có gì đáng lo lắng cả.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Không có gì","example":"没什么好担心的。","example_pinyin":"/Méi shénme hǎo dānxīn de/","example_meaning":"Không có gì đáng lo lắng cả.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('没事儿', 'méi shìr', 'Không có chuyện gì, không sao đâu', '没事儿，我帮你。', 'Méi shìr, wǒ bāng nǐ', 'Không sao đâu, tôi giúp bạn.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Không có chuyện gì, không sao đâu","example":"没事儿，我帮你。","example_pinyin":"/Méi shìr, wǒ bāng nǐ/","example_meaning":"Không sao đâu, tôi giúp bạn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('没有', 'méi yǒu', 'Không có', '我没有钱。', 'Wǒ méiyǒu qián', 'Tôi không có tiền.', 'Động từ', '[{"pos":"Động từ","meaning":"Không có","example":"我没有钱。","example_pinyin":"/Wǒ méiyǒu qián/","example_meaning":"Tôi không có tiền.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('妹妹 | 妹', 'mèimei | mèi', 'Em gái', '我有一个妹妹。', 'Wǒ yǒu yīgè mèimei', 'Tôi có một người em gái.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Em gái","example":"我有一个妹妹。","example_pinyin":"/Wǒ yǒu yīgè mèimei/","example_meaning":"Tôi có một người em gái.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('门', 'mén', 'Cửa', '我把门关上了。', 'Wǒ bǎ mén guānshàng le', 'Tôi đã đóng cửa lại.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cửa","example":"我把门关上了。","example_pinyin":"/Wǒ bǎ mén guānshàng le/","example_meaning":"Tôi đã đóng cửa lại.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('门口', 'ménkǒu', 'Cổng, cửa ra vào', '我在门口等你。', 'Wǒ zài ménkǒu děng nǐ', 'Tôi đang đợi bạn ở cửa ra vào.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cổng, cửa ra vào","example":"我在门口等你。","example_pinyin":"/Wǒ zài ménkǒu děng nǐ/","example_meaning":"Tôi đang đợi bạn ở cửa ra vào.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('门票', 'ménpiào', 'Vé vào cửa', '这张门票多少钱？', 'Zhè zhāng ménpiào duōshǎo qián', NULL, 'Danh từ', '[{"pos":"Danh từ","meaning":"Vé vào cửa","example":"这张门票多少钱？","example_pinyin":"/Zhè zhāng ménpiào duōshǎo qián/","example_meaning":"","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('们（朋友们）', 'men (péngyǒumen)', 'Dùng để chỉ số nhiều (các bạn, các anh...)', '我们是好朋友。', 'Wǒmen shì hǎo péngyǒu', 'Chúng tôi là bạn tốt.', 'Hậu tố', '[{"pos":"Hậu tố","meaning":"Dùng để chỉ số nhiều (các bạn, các anh...)","example":"我们是好朋友。","example_pinyin":"/Wǒmen shì hǎo péngyǒu/","example_meaning":"Chúng tôi là bạn tốt.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('米饭', 'mǐfàn', 'Cơm', '我每天都吃米饭。', 'Wǒ měitiān dōu chī mǐfàn', 'Ngày nào tôi cũng ăn cơm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cơm","example":"我每天都吃米饭。","example_pinyin":"/Wǒ měitiān dōu chī mǐfàn/","example_meaning":"Ngày nào tôi cũng ăn cơm.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('面包', 'miànbāo', 'Bánh mì', '你想吃面包吗？', 'Nǐ xiǎng chī miànbāo ma', 'Bạn có muốn ăn bánh mì không?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bánh mì","example":"你想吃面包吗？","example_pinyin":"/Nǐ xiǎng chī miànbāo ma/","example_meaning":"Bạn có muốn ăn bánh mì không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('面条儿', 'miàntiáor', 'Mì sợi', '这碗面条儿很好吃。', 'Zhè wǎn miàntiáor hěn hǎochī', 'Tô mì này rất ngon.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mì sợi","example":"这碗面条儿很好吃。","example_pinyin":"/Zhè wǎn miàntiáor hěn hǎochī/","example_meaning":"Tô mì này rất ngon.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('名字', 'míngzi', 'Tên gọi', '你的名字是什么？', 'Nǐ de míngzi shì shénme', 'Tên của bạn là gì?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tên gọi","example":"你的名字是什么？","example_pinyin":"/Nǐ de míngzi shì shénme/","example_meaning":"Tên của bạn là gì?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('明白', 'míngbai', 'Hiểu rõ', '我明白你的意思。', 'Wǒ míngbai nǐ de yìsi', 'Tôi hiểu ý của bạn.', 'Động từ', '[{"pos":"Động từ","meaning":"Hiểu rõ","example":"我明白你的意思。","example_pinyin":"/Wǒ míngbai nǐ de yìsi/","example_meaning":"Tôi hiểu ý của bạn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('明年', 'míngnián', 'Năm sau', '明年我想去中国。', 'Míngnián wǒ xiǎng qù Zhōngguó', 'Năm sau tôi muốn đi Trung Quốc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Năm sau","example":"明年我想去中国。","example_pinyin":"/Míngnián wǒ xiǎng qù Zhōngguó/","example_meaning":"Năm sau tôi muốn đi Trung Quốc.","is_approved":true}]', 'HSK1');
