INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('哪儿', 'nǎr', 'Đâu, chỗ nào (phương ngữ bắc kinh)', '那部电影是在哪儿拍的？', 'Nà bù diànyǐng shì zài nǎr pāi de', 'Bộ phim đó được quay ở đâu vậy?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Đâu, chỗ nào (phương ngữ bắc kinh)","example":"那部电影是在哪儿拍的？","example_pinyin":"/Nà bù diànyǐng shì zài nǎr pāi de/","example_meaning":"Bộ phim đó được quay ở đâu vậy?","is_approved":true}]', 'HSK1');
