INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('那', 'nà', 'Đó, kia', '那是我的书。', 'Nà shì wǒ de shū', 'Đó là sách của tôi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Đó, kia","example":"那是我的书。","example_pinyin":"/Nà shì wǒ de shū/","example_meaning":"Đó là sách của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('那边', 'nàbiān', 'Bên đó', '你看到那边的猫了吗？', 'Nǐ kàn dào nà bian de māo le ma', 'Bạn có thấy con mèo bên đó không?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Bên đó","example":"你看到那边的猫了吗？","example_pinyin":"/Nǐ kàn dào nà bian de māo le ma/","example_meaning":"Bạn có thấy con mèo bên đó không?","is_approved":true}]', 'HSK1');
