INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('那儿', 'nàr', 'Ở đó (phương ngữ bắc kinh)', '你要去那儿做什么？', 'Nǐ yào qù nàr zuò shénme', 'Bạn muốn đến đó làm gì?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Ở đó (phương ngữ bắc kinh)","example":"你要去那儿做什么？","example_pinyin":"/Nǐ yào qù nàr zuò shénme/","example_meaning":"Bạn muốn đến đó làm gì?","is_approved":true}]', 'HSK1');
