INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('奶奶 | 奶', 'nǎinai | nǎi', 'Bà nội', '我奶奶今年八十岁。', 'Wǒ nǎinai jīnnián bāshí suì', 'Bà nội tôi năm nay 80 tuổi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bà nội","example":"我奶奶今年八十岁。","example_pinyin":"/Wǒ nǎinai jīnnián bāshí suì/","example_meaning":"Bà nội tôi năm nay 80 tuổi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('男', 'nán', 'Nam, con trai', '我们班有很多男同学。', 'Wǒmen bān yǒu hěnduō nán tóngxué', 'Lớp chúng tôi có rất nhiều bạn học sinh nam.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nam, con trai","example":"我们班有很多男同学。","example_pinyin":"/Wǒmen bān yǒu hěnduō nán tóngxué/","example_meaning":"Lớp chúng tôi có rất nhiều bạn học sinh nam.","is_approved":true}]', 'HSK1');
