INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('男生', 'nánshēng', 'Nam sinh, học sinh nam', '这个班的男生比女生多。', 'Zhège bān de nánshēng bǐ nǚshēng duō', 'Nam sinh trong lớp này nhiều hơn nữ sinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nam sinh, học sinh nam","example":"这个班的男生比女生多。","example_pinyin":"/Zhège bān de nánshēng bǐ nǚshēng duō/","example_meaning":"Nam sinh trong lớp này nhiều hơn nữ sinh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('南', 'nán', 'Phía nam', '我喜欢南方的美食。', 'Wǒ xǐhuan nánfāng de měishí', 'Tôi thích ẩm thực miền Nam.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía nam","example":"我喜欢南方的美食。","example_pinyin":"/Wǒ xǐhuan nánfāng de měishí/","example_meaning":"Tôi thích ẩm thực miền Nam.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('南边', 'nánbiān', 'Phía nam', '我家在学校南边。', 'Wǒ jiā zài xuéxiào nánbiān', 'Nhà tôi ở phía nam của trường.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía nam","example":"我家在学校南边。","example_pinyin":"/Wǒ jiā zài xuéxiào nánbiān/","example_meaning":"Nhà tôi ở phía nam của trường.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('难', 'nán', 'Khó', '这个问题很难回答。', 'Zhège wèntí hěn nán huídá', 'Câu hỏi này rất khó trả lời.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Khó","example":"这个问题很难回答。","example_pinyin":"/Zhège wèntí hěn nán huídá/","example_meaning":"Câu hỏi này rất khó trả lời.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('呢', 'ne', 'Thế, nhỉ, ư', '我是学生，你呢？', 'Wǒ shì xuéshēng, nǐ ne', 'Tớ là học sinh, còn cậu thì sao?', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Thế, nhỉ, ư","example":"我是学生，你呢？","example_pinyin":"/Wǒ shì xuéshēng, nǐ ne/","example_meaning":"Tớ là học sinh, còn cậu thì sao?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('能', 'néng', 'Có thể', '咱们一定能完成任务。', 'Zánmen yídìng néng wánchéng rènwù', 'Chúng ta nhất định có thể hoàn thành nhiệm vụ.', 'Động từ năng nguyện', '[{"pos":"Động từ năng nguyện","meaning":"Có thể","example":"咱们一定能完成任务。","example_pinyin":"/Zánmen yídìng néng wánchéng rènwù/","example_meaning":"Chúng ta nhất định có thể hoàn thành nhiệm vụ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('你', 'nǐ', 'Bạn, anh, chị', '你喜欢吃什么？', 'Nǐ xǐhuan chī shénme', 'Bạn thích ăn gì?', 'Đại từ nhân xưng', '[{"pos":"Đại từ nhân xưng","meaning":"Bạn, anh, chị","example":"你喜欢吃什么？","example_pinyin":"/Nǐ xǐhuan chī shénme/","example_meaning":"Bạn thích ăn gì?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('你们', 'nǐmen', 'Các bạn, các anh, các chị', '你们要去哪儿？', 'Nǐmen yào qù nǎr', 'Các bạn muốn đi đâu?', 'Đại từ nhân xưng (số nhiều)', '[{"pos":"Đại từ nhân xưng (số nhiều)","meaning":"Các bạn, các anh, các chị","example":"你们要去哪儿？","example_pinyin":"/Nǐmen yào qù nǎr/","example_meaning":"Các bạn muốn đi đâu?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('年级', 'niánjí', 'Niên khóa, cấp lớp', '你是几年级的学生？', 'Nǐ shì jǐ niánjí de xuéshēng', 'Bạn là học sinh lớp mấy?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Niên khóa, cấp lớp","example":"你是几年级的学生？","example_pinyin":"/Nǐ shì jǐ niánjí de xuéshēng/","example_meaning":"Bạn là học sinh lớp mấy?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('您', 'nín', 'Ngài, ông, bà', '您喜欢喝茶还是喝咖啡？', 'Nín xǐhuan hē chá háishì hē kāfēi', 'Ngài thích uống trà hay cà phê?', 'Đại từ nhân xưng', '[{"pos":"Đại từ nhân xưng","meaning":"Ngài, ông, bà","example":"您喜欢喝茶还是喝咖啡？","example_pinyin":"/Nín xǐhuan hē chá háishì hē kāfēi/","example_meaning":"Ngài thích uống trà hay cà phê?","is_approved":true}]', 'HSK1');
