INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('女', 'nǚ', 'Nữ, con gái', '我的女儿非常可爱。', 'Wǒ de nǚ ér fēicháng kě ài', 'Con gái tôi rất dễ thương.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nữ, con gái","example":"我的女儿非常可爱。","example_pinyin":"/Wǒ de nǚ ér fēicháng kě ài/","example_meaning":"Con gái tôi rất dễ thương.","is_approved":true}]', 'HSK1');
