INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('女人', 'nǚrén', 'Phụ nữ', '女人都喜欢买漂亮的衣服。', 'Nǚrén dōu xǐhuān mǎi piàoliang de yīfu', 'Phụ nữ đều thích mua quần áo đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phụ nữ","example":"女人都喜欢买漂亮的衣服。","example_pinyin":"/Nǚrén dōu xǐhuān mǎi piàoliang de yīfu/","example_meaning":"Phụ nữ đều thích mua quần áo đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('女生', 'nǚshēng', 'Nữ sinh', '这些女生喜欢画画。', 'Zhèxiē nǚshēng xǐhuān huà huà', 'Những nữ sinh này thích vẽ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nữ sinh","example":"这些女生喜欢画画。","example_pinyin":"/Zhèxiē nǚshēng xǐhuān huà huà/","example_meaning":"Những nữ sinh này thích vẽ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('旁边', 'pángbiān', 'Cạnh, bên cạnh', '厨房在客厅的旁边。', 'Chúfáng zài kètīng de pángbiān', 'Nhà bếp ở bên cạnh phòng khách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cạnh, bên cạnh","example":"厨房在客厅的旁边。","example_pinyin":"/Chúfáng zài kètīng de pángbiān/","example_meaning":"Nhà bếp ở bên cạnh phòng khách.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('跑', 'pǎo', 'Chạy', '他每天早上都跑步。', 'Tā měitiān zǎoshang dōu pǎobù', 'Anh ấy chạy bộ mỗi sáng.', 'Động từ', '[{"pos":"Động từ","meaning":"Chạy","example":"他每天早上都跑步。","example_pinyin":"/Tā měitiān zǎoshang dōu pǎobù/","example_meaning":"Anh ấy chạy bộ mỗi sáng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('朋友', 'péngyou', 'Bạn bè', '我有很多朋友。', 'Wǒ yǒu hěn duō péngyou', 'Tôi có rất nhiều bạn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bạn bè","example":"我有很多朋友。","example_pinyin":"/Wǒ yǒu hěn duō péngyou/","example_meaning":"Tôi có rất nhiều bạn.","is_approved":true}]', 'HSK1');
