INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('起', 'qǐ', 'Dậy, thức dậy, đứng dậy', '今天睡到上午10点才起。', 'Jīntiān shuì dào shàngwǔ 10 diǎn cái qǐ', 'Nay ngủ đến 10 giờ mới dậy.', 'Động từ', '[{"pos":"Động từ","meaning":"Dậy, thức dậy, đứng dậy","example":"今天睡到上午10点才起。","example_pinyin":"/Jīntiān shuì dào shàngwǔ 10 diǎn cái qǐ/","example_meaning":"Nay ngủ đến 10 giờ mới dậy.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('起床', 'qǐchuáng', 'Thức dậy (ra khỏi giường)', '我每天六点起床。', 'Wǒ měitiān liù diǎn qǐchuáng', 'Mỗi ngày tôi thức dậy lúc 6 giờ.', 'Động từ', '[{"pos":"Động từ","meaning":"Thức dậy (ra khỏi giường)","example":"我每天六点起床。","example_pinyin":"/Wǒ měitiān liù diǎn qǐchuáng/","example_meaning":"Mỗi ngày tôi thức dậy lúc 6 giờ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('起来', 'qǐlái', 'Đứng dậy, ngồi dậy, thức dậy', '他站起来了。', 'Tā zhàn qǐlái le', 'Anh ấy đứng dậy rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đứng dậy, ngồi dậy, thức dậy","example":"他站起来了。","example_pinyin":"/Tā zhàn qǐlái le/","example_meaning":"Anh ấy đứng dậy rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('汽车', 'qìchē', 'Xe hơi, ô tô', '这辆汽车是我爸爸的。', 'Zhè liàng qìchē shì wǒ bàba de', 'Hai chiếc ô tô này là của bố tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Xe hơi, ô tô","example":"这辆汽车是我爸爸的。","example_pinyin":"/Zhè liàng qìchē shì wǒ bàba de/","example_meaning":"Hai chiếc ô tô này là của bố tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('前', 'qián', 'Trước', '他12号前会回来。', 'Tā 12 hào qián huì huílái', 'Anh ấy sẽ trở lại trước ngày 12.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trước","example":"他12号前会回来。","example_pinyin":"/Tā 12 hào qián huì huílái/","example_meaning":"Anh ấy sẽ trở lại trước ngày 12.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('前边', 'qiánbiān', 'Phía trước', '学校就在前边。', 'Xuéxiào jiù zài qiánbiān', 'Trường học ở ngay phía trước.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía trước","example":"学校就在前边。","example_pinyin":"/Xuéxiào jiù zài qiánbiān/","example_meaning":"Trường học ở ngay phía trước.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('前天', 'qiántiān', 'Hôm kia', '我前天去了上海。', 'Wǒ qiántiān qù le Shànghǎi', 'Hôm kia tôi đã đi Thượng Hải.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Hôm kia","example":"我前天去了上海。","example_pinyin":"/Wǒ qiántiān qù le Shànghǎi/","example_meaning":"Hôm kia tôi đã đi Thượng Hải.","is_approved":true}]', 'HSK1');
