INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('钱包', 'qiánbāo', 'Ví tiền, bóp tiền', '我的钱包不见了。', 'Wǒ de qiánbāo bú jiàn le', 'Ví tiền của tôi bị mất rồi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ví tiền, bóp tiền","example":"我的钱包不见了。","example_pinyin":"/Wǒ de qiánbāo bú jiàn le/","example_meaning":"Ví tiền của tôi bị mất rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('请', 'qǐng', 'Mời, xin vui lòng', '请给我一杯水。', 'Qǐng gěi wǒ yì bēi shuǐ', 'Xin hãy cho tôi một cốc nước.', 'Động từ', '[{"pos":"Động từ","meaning":"Mời, xin vui lòng","example":"请给我一杯水。","example_pinyin":"/Qǐng gěi wǒ yì bēi shuǐ/","example_meaning":"Xin hãy cho tôi một cốc nước.","is_approved":true}]', 'HSK1');
