INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('请问', 'qǐngwèn', 'Xin hỏi', '请问您有空吗？', 'Qǐngwèn nín yǒu kòng ma', 'Xin hỏi anh có rảnh không ạ?', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Xin hỏi","example":"请问您有空吗？","example_pinyin":"/Qǐngwèn nín yǒu kòng ma/","example_meaning":"Xin hỏi anh có rảnh không ạ?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('请坐', 'qǐng zuò', 'Mời ngồi', '欢迎光临，请坐。', 'Huānyíng guānglín, qǐng zuò', 'Chào mừng quý khách, mời ngồi.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Mời ngồi","example":"欢迎光临，请坐。","example_pinyin":"/Huānyíng guānglín, qǐng zuò/","example_meaning":"Chào mừng quý khách, mời ngồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('球', 'qiú', 'Quả bóng', '他喜欢踢足球。', 'Tā xǐhuan tī zúqiú', 'Anh ấy thích đá bóng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Quả bóng","example":"他喜欢踢足球。","example_pinyin":"/Tā xǐhuan tī zúqiú/","example_meaning":"Anh ấy thích đá bóng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('去', 'qù', 'Đi, rời đi, rời khỏi', '他吃完饭就去了。', 'Tā chī wán fàn jiù qù le', 'Anh ấy ăn xong rồi đi ngay.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi, rời đi, rời khỏi","example":"他吃完饭就去了。","example_pinyin":"/Tā chī wán fàn jiù qù le/","example_meaning":"Anh ấy ăn xong rồi đi ngay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('去年', 'qùnián', 'Năm ngoái', '去年我买了一辆新车。', 'Qùnián wǒ mǎi le yī liàng xīnchē', 'Năm ngoái tôi đã mua một chiếc xe mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Năm ngoái","example":"去年我买了一辆新车。","example_pinyin":"/Qùnián wǒ mǎi le yī liàng xīnchē/","example_meaning":"Năm ngoái tôi đã mua một chiếc xe mới.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('热', 'rè', 'Nóng', '今天的天气很热。', 'Jīntiān de tiānqì hěn rè', 'Thời tiết của hôm nay rất nóng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nóng","example":"今天的天气很热。","example_pinyin":"/Jīntiān de tiānqì hěn rè/","example_meaning":"Thời tiết của hôm nay rất nóng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('人', 'rén', 'Người', '这个世界上有很多好人。', 'Zhège shìjiè shàng yǒu hěn duō hǎorén', 'Trên thế giới này có rất nhiều người tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người","example":"这个世界上有很多好人。","example_pinyin":"/Zhège shìjiè shàng yǒu hěn duō hǎorén/","example_meaning":"Trên thế giới này có rất nhiều người tốt.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('认识', 'rènshi', 'Quen biết', '我认识他。', 'Wǒ rènshi tā', 'Tôi quen biết anh ấy.', 'Động từ', '[{"pos":"Động từ","meaning":"Quen biết","example":"我认识他。","example_pinyin":"/Wǒ rènshi tā/","example_meaning":"Tôi quen biết anh ấy.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('认真', 'rènzhēn', 'Chăm chỉ, nghiêm túc', '他学习很认真。', 'Tā xuéxí hěn rènzhēn', 'Anh ấy học rất chăm chỉ.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Chăm chỉ, nghiêm túc","example":"他学习很认真。","example_pinyin":"/Tā xuéxí hěn rènzhēn/","example_meaning":"Anh ấy học rất chăm chỉ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('日', 'rì', 'Ngày, mỗi ngày

mặt trời', '他的生日在六月。

日出的时候很美。', 'Tā de shēngrì zài liù yuè

Rì chū de shíhòu hěn měi', 'Ngày sinh nhật của anh ấy vào tháng sáu.

Lúc mặt trời mọc rất đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ngày, mỗi ngày\n\nmặt trời","example":"他的生日在六月。\n\n日出的时候很美。","example_pinyin":"/Tā de shēngrì zài liù yuè/\n\n/Rì chū de shíhòu hěn měi/","example_meaning":"Ngày sinh nhật của anh ấy vào tháng sáu.\n\nLúc mặt trời mọc rất đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('日期', 'rìqī', 'Ngày tháng, thời gian', '文件的日期写错了。', 'Wénjiàn de rìqí xiě cuò le', 'Ngày tháng trên tài liệu bị sai rồi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ngày tháng, thời gian","example":"文件的日期写错了。","example_pinyin":"/Wénjiàn de rìqí xiě cuò le/","example_meaning":"Ngày tháng trên tài liệu bị sai rồi.","is_approved":true}]', 'HSK1');
