INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('时间', 'shíjiān', 'Thời gian', '时间过得真快。', 'Shíjiān guò dé zhēn kuài', 'Thời gian trôi qua thật nhanh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thời gian","example":"时间过得真快。","example_pinyin":"/Shíjiān guò dé zhēn kuài/","example_meaning":"Thời gian trôi qua thật nhanh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('事', 'shì', 'Việc, sự việc', '这是一件重要的事。', 'Zhè shì yī jiàn zhòngyào de shì', 'Đây là một việc quan trọng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Việc, sự việc","example":"这是一件重要的事。","example_pinyin":"/Zhè shì yī jiàn zhòngyào de shì/","example_meaning":"Đây là một việc quan trọng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('试', 'shì', 'Thử, thử nghiệm', '我可以试一试吗？', 'Wǒ kěyǐ shì yī shì ma?', 'Tôi có thể thử một chút không?', 'Động từ', '[{"pos":"Động từ","meaning":"Thử, thử nghiệm","example":"我可以试一试吗？","example_pinyin":"/Wǒ kěyǐ shì yī shì ma?/","example_meaning":"Tôi có thể thử một chút không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('是', 'shì', 'Là', '他是我的好朋友。', 'Tā shì wǒ de hǎo péngyǒu', 'Anh ấy là bạn tốt của tôi.', 'Động từ', '[{"pos":"Động từ","meaning":"Là","example":"他是我的好朋友。","example_pinyin":"/Tā shì wǒ de hǎo péngyǒu/","example_meaning":"Anh ấy là bạn tốt của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('是不是', 'shì bùshì', 'Có phải không?', '这件事是不是你做的？', 'Zhè jiàn shì shì bùshì nǐ zuò de', 'Việc này có phải cậu làm không?', 'Câu hỏi', '[{"pos":"Câu hỏi","meaning":"Có phải không?","example":"这件事是不是你做的？","example_pinyin":"/Zhè jiàn shì shì bùshì nǐ zuò de/","example_meaning":"Việc này có phải cậu làm không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('手', 'shǒu', 'Tay', '请把手洗干净。', 'Qǐng bǎ shǒu xǐ gānjìng', 'Hãy rửa tay sạch sẽ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tay","example":"请把手洗干净。","example_pinyin":"/Qǐng bǎ shǒu xǐ gānjìng/","example_meaning":"Hãy rửa tay sạch sẽ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('手机', 'shǒujī', 'Điện thoại di động', '我的手机在那里。', 'Wǒ de shǒujī zài nàlǐ', 'Điện thoại của tôi ở đằng kia.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Điện thoại di động","example":"我的手机在那里。","example_pinyin":"/Wǒ de shǒujī zài nàlǐ/","example_meaning":"Điện thoại của tôi ở đằng kia.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('书', 'shū', 'Sách', '我喜欢看书。', 'Wǒ xǐhuan kàn shū', 'Tôi thích đọc sách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sách","example":"我喜欢看书。","example_pinyin":"/Wǒ xǐhuan kàn shū/","example_meaning":"Tôi thích đọc sách.","is_approved":true}]', 'HSK1');
