INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('玩儿', 'wánr', 'Chơi', '孩子们喜欢玩儿游戏。', 'Háizimen xǐhuān wánr yóuxì', 'Bọn trẻ thích chơi trò chơi.', 'Động từ', '[{"pos":"Động từ","meaning":"Chơi","example":"孩子们喜欢玩儿游戏。","example_pinyin":"/Háizimen xǐhuān wánr yóuxì/","example_meaning":"Bọn trẻ thích chơi trò chơi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('晚', 'wǎn', 'Muộn, trễ', '现在太晚了，快睡吧。', 'Xiànzài tài wǎn le, kuài shuì ba', 'Bây giờ quá muộn rồi, mau ngủ đi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Muộn, trễ","example":"现在太晚了，快睡吧。","example_pinyin":"/Xiànzài tài wǎn le, kuài shuì ba/","example_meaning":"Bây giờ quá muộn rồi, mau ngủ đi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('晚饭', 'wǎnfàn', 'Bữa tối', '我们一起吃晚饭吧。', 'Wǒmen yìqǐ chī wǎnfàn ba', 'Chúng ta cùng đi ăn tối nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bữa tối","example":"我们一起吃晚饭吧。","example_pinyin":"/Wǒmen yìqǐ chī wǎnfàn ba/","example_meaning":"Chúng ta cùng đi ăn tối nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('晚上', 'wǎnshàng', 'Buổi tối', '晚上我们一起去看电影吧。', 'Wǎnshàng wǒmen yìqǐ qù kàn diànyǐng ba', 'Buổi tối chúng ta cùng đi xem phim nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Buổi tối","example":"晚上我们一起去看电影吧。","example_pinyin":"/Wǎnshàng wǒmen yìqǐ qù kàn diànyǐng ba/","example_meaning":"Buổi tối chúng ta cùng đi xem phim nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('网上', 'wǎngshàng', 'Trên mạng', '现在很多人喜欢在网上买东西。', 'Xiànzài hěnduō rén xǐhuān zài wǎngshàng mǎi dōngxī', 'Hiện nay nhiều người thích mua đồ trên mạng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trên mạng","example":"现在很多人喜欢在网上买东西。","example_pinyin":"/Xiànzài hěnduō rén xǐhuān zài wǎngshàng mǎi dōngxī/","example_meaning":"Hiện nay nhiều người thích mua đồ trên mạng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('网友', 'wǎngyǒu', 'Bạn trên mạng', '我有很多网友。', 'Wǒ yǒu hěnduō wǎngyǒu', 'Tôi có nhiều bạn trên mạng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bạn trên mạng","example":"我有很多网友。","example_pinyin":"/Wǒ yǒu hěnduō wǎngyǒu/","example_meaning":"Tôi có nhiều bạn trên mạng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('忘', 'wàng', 'Quên', '我忘了带钱包。', 'Wǒ wàng le dài qiánbāo', 'Tôi quên mang ví tiền rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Quên","example":"我忘了带钱包。","example_pinyin":"/Wǒ wàng le dài qiánbāo/","example_meaning":"Tôi quên mang ví tiền rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('忘记', 'wàngjì', 'Quên', '请不要忘记明天的会议。', 'Qǐng bú yào wàngjì míngtiān de huìyì', 'Xin đừng quên cuộc họp ngày mai.', 'Động từ', '[{"pos":"Động từ","meaning":"Quên","example":"请不要忘记明天的会议。","example_pinyin":"/Qǐng bú yào wàngjì míngtiān de huìyì/","example_meaning":"Xin đừng quên cuộc họp ngày mai.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('问', 'wèn', 'Hỏi', '你可以问问老师这个问题。', 'Nǐ kěyǐ wèn wèn lǎoshī zhège wèntí', 'Bạn có thể hỏi giáo viên câu hỏi này.', 'Động từ', '[{"pos":"Động từ","meaning":"Hỏi","example":"你可以问问老师这个问题。","example_pinyin":"/Nǐ kěyǐ wèn wèn lǎoshī zhège wèntí/","example_meaning":"Bạn có thể hỏi giáo viên câu hỏi này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('我', 'wǒ', 'Tôi, mình', '我是学生。', 'Wǒ shì xuéshēng', 'Tôi là học sinh.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Tôi, mình","example":"我是学生。","example_pinyin":"/Wǒ shì xuéshēng/","example_meaning":"Tôi là học sinh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('我们', 'wǒmen', 'Chúng tôi, chúng ta', '我们是好朋友。', 'Wǒmen shì hǎo péngyǒu', 'Chúng tôi là bạn tốt của nhau.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Chúng tôi, chúng ta","example":"我们是好朋友。","example_pinyin":"/Wǒmen shì hǎo péngyǒu/","example_meaning":"Chúng tôi là bạn tốt của nhau.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('五', 'wǔ', 'Số năm', '她今天买了五个苹果。', 'Tā jīntiān mǎi le wǔ gè píngguǒ', 'Hôm nay cô ấy đã mua năm quả táo.', 'Số từ', '[{"pos":"Số từ","meaning":"Số năm","example":"她今天买了五个苹果。","example_pinyin":"/Tā jīntiān mǎi le wǔ gè píngguǒ/","example_meaning":"Hôm nay cô ấy đã mua năm quả táo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('午饭', 'wǔfàn', 'Bữa trưa', '我们一起去吃午饭吧。', 'Wǒmen yīqǐ qù chī wǔfàn ba', 'Chúng ta cùng đi ăn trưa nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bữa trưa","example":"我们一起去吃午饭吧。","example_pinyin":"/Wǒmen yīqǐ qù chī wǔfàn ba/","example_meaning":"Chúng ta cùng đi ăn trưa nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('西', 'xī', 'Phía tây', '我家在学校西边。', 'Wǒ jiā zài xuéxiào xībiān', 'Nhà tôi ở phía tây của trường.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía tây","example":"我家在学校西边。","example_pinyin":"/Wǒ jiā zài xuéxiào xībiān/","example_meaning":"Nhà tôi ở phía tây của trường.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('洗', 'xǐ', 'Giặt, rửa, tắm', '现在我要洗衣服。', 'Xiànzài wǒ yào xǐ yīfu', 'Bây giờ tôi phải giặt quần áo.', 'Động từ', '[{"pos":"Động từ","meaning":"Giặt, rửa, tắm","example":"现在我要洗衣服。","example_pinyin":"/Xiànzài wǒ yào xǐ yīfu/","example_meaning":"Bây giờ tôi phải giặt quần áo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('洗手间', 'xǐshǒujiān', 'Nhà vệ sinh', '请问，洗手间在哪里？', 'Qǐngwèn, xǐshǒujiān zài nǎlǐ', 'Xin hỏi, nhà vệ sinh ở đâu?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nhà vệ sinh","example":"请问，洗手间在哪里？","example_pinyin":"/Qǐngwèn, xǐshǒujiān zài nǎlǐ/","example_meaning":"Xin hỏi, nhà vệ sinh ở đâu?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('喜欢', 'xǐhuan', 'Thích', '我很喜欢吃中国菜。', 'Wǒ hěn xǐhuan chī Zhōngguó cài', 'Tôi rất thích ăn món Trung Quốc.', 'Động từ', '[{"pos":"Động từ","meaning":"Thích","example":"我很喜欢吃中国菜。","example_pinyin":"/Wǒ hěn xǐhuan chī Zhōngguó cài/","example_meaning":"Tôi rất thích ăn món Trung Quốc.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下', 'xià', 'Dưới, phía dưới, bên dưới', '上有父母，下有儿女。', 'Shàng yǒu fùmǔ, xià yǒu érnǚ', 'Trên có cha mẹ, dưới có con cái.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Dưới, phía dưới, bên dưới","example":"上有父母，下有儿女。","example_pinyin":"/Shàng yǒu fùmǔ, xià yǒu érnǚ/","example_meaning":"Trên có cha mẹ, dưới có con cái.","is_approved":true},{"pos":"Động từ","meaning":"Xuống","example":"下课后一起去吃饭吧。","example_pinyin":"/Xiàkè hòu yīqǐ qù chīfàn ba/","example_meaning":"Tan học xong cùng đi ăn nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下班', 'xiàbān', 'Tan làm', '我今晚八点下班。', 'Wǒ jīn wǎn bā diǎn xiàbān', 'Tối nay tôi tan làm lúc 8 giờ.', 'Động từ', '[{"pos":"Động từ","meaning":"Tan làm","example":"我今晚八点下班。","example_pinyin":"/Wǒ jīn wǎn bā diǎn xiàbān/","example_meaning":"Tối nay tôi tan làm lúc 8 giờ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下边', 'xiàbian', 'Bên dưới', '桌子下边有一只猫。', 'Zhuōzi xiàbian yǒu yī zhī māo', 'Dưới bàn có một con mèo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên dưới","example":"桌子下边有一只猫。","example_pinyin":"/Zhuōzi xiàbian yǒu yī zhī māo/","example_meaning":"Dưới bàn có một con mèo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下车', 'xià chē', 'Xuống xe', '我要在这一站下车。', 'Wǒ yào zài zhè yí zhàn xià chē', 'Tôi muốn xuống xe ở trạm này.', 'Động từ', '[{"pos":"Động từ","meaning":"Xuống xe","example":"我要在这一站下车。","example_pinyin":"/Wǒ yào zài zhè yí zhàn xià chē/","example_meaning":"Tôi muốn xuống xe ở trạm này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下次', 'xià cì', 'Lần sau', '下次我们一起去看电影吧。', 'Xià cì wǒmen yīqǐ qù kàn diànyǐng ba', 'Lần sau chúng ta cùng đi xem phim nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lần sau","example":"下次我们一起去看电影吧。","example_pinyin":"/Xià cì wǒmen yīqǐ qù kàn diànyǐng ba/","example_meaning":"Lần sau chúng ta cùng đi xem phim nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下课', 'xiàkè', 'Tan học', '下课后，我们去喝奶茶吧。', 'Xiàkè hòu, wǒmen qù hē nǎichá ba', 'Tan học xong, chúng ta đi uống trà sữa nhé.', 'Động từ', '[{"pos":"Động từ","meaning":"Tan học","example":"下课后，我们去喝奶茶吧。","example_pinyin":"/Xiàkè hòu, wǒmen qù hē nǎichá ba/","example_meaning":"Tan học xong, chúng ta đi uống trà sữa nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下午', 'xiàwǔ', 'Buổi chiều', '我下午三点有个会议。', 'Wǒ xiàwǔ sān diǎn yǒu gè huìyì', 'Tôi có một cuộc họp vào lúc 3 giờ chiều.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Buổi chiều","example":"我下午三点有个会议。","example_pinyin":"/Wǒ xiàwǔ sān diǎn yǒu gè huìyì/","example_meaning":"Tôi có một cuộc họp vào lúc 3 giờ chiều.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('下雨', 'xià yǔ', 'Mưa rơi', '今天会下雨，你带伞了吗？', 'Jīntiān huì xiàyǔ, nǐ dài sǎn le ma', 'Hôm nay trời sẽ mưa, bạn đã mang ô chưa?', 'Động từ', '[{"pos":"Động từ","meaning":"Mưa rơi","example":"今天会下雨，你带伞了吗？","example_pinyin":"/Jīntiān huì xiàyǔ, nǐ dài sǎn le ma/","example_meaning":"Hôm nay trời sẽ mưa, bạn đã mang ô chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('先', 'xiān', 'Trước tiên', '你先去，我等一下再去。', 'Nǐ xiān qù, wǒ děng yīxià zài qù', 'Bạn đi trước đi, tôi sẽ đi sau.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Trước tiên","example":"你先去，我等一下再去。","example_pinyin":"/Nǐ xiān qù, wǒ děng yīxià zài qù/","example_meaning":"Bạn đi trước đi, tôi sẽ đi sau.","is_approved":true}]', 'HSK1');
