INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小姐', 'xiǎojiě', 'Tiểu thư, cô gái', '王小姐是我的同事。', 'Wáng xiǎojiě shì wǒ de tóngshì', 'Cô Vương là đồng nghiệp của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tiểu thư, cô gái","example":"王小姐是我的同事。","example_pinyin":"/Wáng xiǎojiě shì wǒ de tóngshì/","example_meaning":"Cô Vương là đồng nghiệp của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小朋友', 'xiǎopéngyǒu', 'Bạn nhỏ, trẻ em', '小朋友们都喜欢听故事。', 'Xiǎopéngyǒu men dōu xǐhuan tīng gùshì', 'Các bạn nhỏ đều thích nghe kể chuyện.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bạn nhỏ, trẻ em","example":"小朋友们都喜欢听故事。","example_pinyin":"/Xiǎopéngyǒu men dōu xǐhuan tīng gùshì/","example_meaning":"Các bạn nhỏ đều thích nghe kể chuyện.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小时', 'xiǎoshí', 'Giờ (đơn vị thời gian)', '我等了一个小时。', 'Wǒ děng le yí gè xiǎoshí', 'Tôi đã đợi 1 tiếng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Giờ (đơn vị thời gian)","example":"我等了一个小时。","example_pinyin":"/Wǒ děng le yí gè xiǎoshí/","example_meaning":"Tôi đã đợi 1 tiếng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小学', 'xiǎoxué', 'Trường tiểu học', '我弟弟上小学二年级。', 'Wǒ dìdi shàng xiǎoxué èr niánjí', 'Em trai tôi học lớp 2 tiểu học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trường tiểu học","example":"我弟弟上小学二年级。","example_pinyin":"/Wǒ dìdi shàng xiǎoxué èr niánjí/","example_meaning":"Em trai tôi học lớp 2 tiểu học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小学生', 'xiǎoxuéshēng', 'Học sinh tiểu học', '她是个聪明的小学生。', 'Tā shì gè cōngmíng de xiǎoxuéshēng', 'Cô bé ấy là một học sinh tiểu học thông minh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Học sinh tiểu học","example":"她是个聪明的小学生。","example_pinyin":"/Tā shì gè cōngmíng de xiǎoxuéshēng/","example_meaning":"Cô bé ấy là một học sinh tiểu học thông minh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('笑', 'xiào', 'Cười', '她的笑容很美。', 'Tā de xiàoróng hěn měi', 'Nụ cười của cô ấy rất đẹp.', 'Động từ', '[{"pos":"Động từ","meaning":"Cười","example":"她的笑容很美。","example_pinyin":"/Tā de xiàoróng hěn měi/","example_meaning":"Nụ cười của cô ấy rất đẹp.","is_approved":true}]', 'HSK1');
