INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('一点儿', 'yìdiǎnr', 'Một chút, một ít', '我想喝一点儿水。', 'Wǒ xiǎng hē yìdiǎnr shuǐ', 'Tôi muốn uống một chút nước.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Một chút, một ít","example":"我想喝一点儿水。","example_pinyin":"/Wǒ xiǎng hē yìdiǎnr shuǐ/","example_meaning":"Tôi muốn uống một chút nước.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('一起', 'yìqǐ', 'Cùng nhau', '我们一起去看电影吧。', 'Wǒmen yìqǐ qù kàn diànyǐng ba', 'Chúng ta cùng đi xem phim nhé.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Cùng nhau","example":"我们一起去看电影吧。","example_pinyin":"/Wǒmen yìqǐ qù kàn diànyǐng ba/","example_meaning":"Chúng ta cùng đi xem phim nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('一些', 'yìxiē', 'Một số, một ít', '这里有一些苹果。', 'Zhèlǐ yǒu yìxiē píngguǒ', 'Ở đây có một vài quả táo.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Một số, một ít","example":"这里有一些苹果。","example_pinyin":"/Zhèlǐ yǒu yìxiē píngguǒ/","example_meaning":"Ở đây có một vài quả táo.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('用', 'yòng', 'Dùng, sử dụng', '你可以用我的手机。', 'Nǐ kěyǐ yòng wǒ de shǒujī', 'Bạn có thể dùng điện thoại của tôi.', 'Động từ', '[{"pos":"Động từ","meaning":"Dùng, sử dụng","example":"你可以用我的手机。","example_pinyin":"/Nǐ kěyǐ yòng wǒ de shǒujī/","example_meaning":"Bạn có thể dùng điện thoại của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有', 'yǒu', 'Có, tồn tại', '我有一个好朋友。', 'Wǒ yǒu yī gè hǎo péngyǒu', 'Tôi có một người bạn tốt.', 'Động từ', '[{"pos":"Động từ","meaning":"Có, tồn tại","example":"我有一个好朋友。","example_pinyin":"/Wǒ yǒu yī gè hǎo péngyǒu/","example_meaning":"Tôi có một người bạn tốt.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有的', 'yǒude', 'Một số, có cái thì…', '有的人喜欢喝咖啡,有的人喜欢喝茶。', 'Yǒude rén xǐhuan hē kāfēi，yǒude rén xǐhuan hē chá', 'Có người thích uống cà phê, có người thích uống trà.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Một số, có cái thì…","example":"有的人喜欢喝咖啡,有的人喜欢喝茶。","example_pinyin":"/Yǒude rén xǐhuan hē kāfēi，yǒude rén xǐhuan hē chá/","example_meaning":"Có người thích uống cà phê, có người thích uống trà.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有名', 'yǒumíng', 'Nổi tiếng', '这家餐厅很有名。', 'Zhè jiā cāntīng hěn yǒumíng', 'Nhà hàng này rất nổi tiếng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nổi tiếng","example":"这家餐厅很有名。","example_pinyin":"/Zhè jiā cāntīng hěn yǒumíng/","example_meaning":"Nhà hàng này rất nổi tiếng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有时候 | 有时', 'yǒu shíhòu |yǒu shí', 'Đôi khi, có lúc', '我有时候去图书馆学习。', 'Wǒ yǒu shíhòu qù túshūguǎn xuéxí', 'Đôi khi tôi đến thư viện học.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Đôi khi, có lúc","example":"我有时候去图书馆学习。","example_pinyin":"/Wǒ yǒu shíhòu qù túshūguǎn xuéxí/","example_meaning":"Đôi khi tôi đến thư viện học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有（一）些', 'yǒu (yì) xiē', 'Một vài, một số', '这里有一些书。', 'Zhèlǐ yǒu yìxiē shū', 'Ở đây có một vài cuốn sách.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Một vài, một số","example":"这里有一些书。","example_pinyin":"/Zhèlǐ yǒu yìxiē shū/","example_meaning":"Ở đây có một vài cuốn sách.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('有用', 'yǒuyòng', 'Hữu ích, có ích', '这本书很有用。', 'Zhè běn shū hěn yǒuyòng', 'Cuốn sách này rất hữu ích.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Hữu ích, có ích","example":"这本书很有用。","example_pinyin":"/Zhè běn shū hěn yǒuyòng/","example_meaning":"Cuốn sách này rất hữu ích.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('右', 'yòu', 'Bên phải', '商店在银行的右边。', 'Shāngdiàn zài yínháng de yòubian', 'Cửa hàng ở bên phải ngân hàng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên phải","example":"商店在银行的右边。","example_pinyin":"/Shāngdiàn zài yínháng de yòubian/","example_meaning":"Cửa hàng ở bên phải ngân hàng.","is_approved":true}]', 'HSK1');
