INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('元', 'yuán', 'Đồng (đơn vị tiền tệ)', '这本书五十元。', 'Zhè běn shū wǔshí yuán', 'Cuốn sách này giá 50 tệ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đồng (đơn vị tiền tệ)","example":"这本书五十元。","example_pinyin":"/Zhè běn shū wǔshí yuán/","example_meaning":"Cuốn sách này giá 50 tệ.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('远', 'yuǎn', 'Xa', '我家离学校很远。', 'Wǒ jiā lí xuéxiào hěn yuǎn', 'Nhà tôi cách trường học rất xa.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Xa","example":"我家离学校很远。","example_pinyin":"/Wǒ jiā lí xuéxiào hěn yuǎn/","example_meaning":"Nhà tôi cách trường học rất xa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('月', 'yuè', 'Tháng

 mặt trăng', '今年的二月有二十九天。

