Mặt trăng hôm nay rất đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tháng\n\n mặt trăng","example":"今年的二月有二十九天。\n\n今天的月亮很漂亮。","example_pinyin":"/Jīnnián de èryuè yǒu èrshíjiǔ tiān/\n\n/Jīntiān de yuèliàng hěn piàoliang/","example_meaning":"Tháng Hai năm nay có 29 ngày.\n\nMặt trăng hôm nay rất đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('再', 'zài', 'Lại, lần nữa', '请再说一遍。', 'Qǐng zài shuō yí biàn', 'Xin hãy nói lại một lần nữa.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Lại, lần nữa","example":"请再说一遍。","example_pinyin":"/Qǐng zài shuō yí biàn/","example_meaning":"Xin hãy nói lại một lần nữa.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('再见', 'zàijiàn', 'Tạm biệt', 'A: 明天见！
