INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('在', 'zài', 'Ở, tại', '我在家看电视。', 'Wǒ zài jiā kàn diànshì', 'Tôi ở nhà xem tivi.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Ở, tại","example":"我在家看电视。","example_pinyin":"/Wǒ zài jiā kàn diànshì/","example_meaning":"Tôi ở nhà xem tivi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('在家', 'zàijiā', 'Ở nhà', '周末我一般在家休息。', 'Zhōumò wǒ yībān zàijiā xiūxi', 'Cuối tuần tôi thường ở nhà nghỉ ngơi.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Ở nhà","example":"周末我一般在家休息。","example_pinyin":"/Zhōumò wǒ yībān zàijiā xiūxi/","example_meaning":"Cuối tuần tôi thường ở nhà nghỉ ngơi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('早', 'zǎo', 'Sớm', '今天你起得很早。', 'Jīntiān nǐ qǐ de hěn zǎo', 'Hôm nay bạn dậy rất sớm.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Sớm","example":"今天你起得很早。","example_pinyin":"/Jīntiān nǐ qǐ de hěn zǎo/","example_meaning":"Hôm nay bạn dậy rất sớm.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('早饭', 'zǎofàn', 'Bữa sáng', '你今天吃早饭了吗？', 'Nǐ jīntiān chī zǎofàn le ma', 'Hôm nay bạn đã ăn sáng chưa?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bữa sáng","example":"你今天吃早饭了吗？","example_pinyin":"/Nǐ jīntiān chī zǎofàn le ma/","example_meaning":"Hôm nay bạn đã ăn sáng chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('早上', 'zǎoshang', 'Buổi sáng', '早上空气很好。', 'Zǎoshang kōngqì hěn hǎo', 'Không khí buổi sáng rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Buổi sáng","example":"早上空气很好。","example_pinyin":"/Zǎoshang kōngqì hěn hǎo/","example_meaning":"Không khí buổi sáng rất tốt.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('怎么', 'zěnme', 'Như thế nào', '你怎么来学校的？', 'Nǐ zěnme lái xuéxiào de', 'Bạn đến trường bằng cách nào?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Như thế nào","example":"你怎么来学校的？","example_pinyin":"/Nǐ zěnme lái xuéxiào de/","example_meaning":"Bạn đến trường bằng cách nào?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('站', 'zhàn', 'Đứng', '请站在这儿。', 'Qǐng zhàn zài zhèr', 'Xin hãy đứng ở đây.', 'Động từ', '[{"pos":"Động từ","meaning":"Đứng","example":"请站在这儿。","example_pinyin":"/Qǐng zhàn zài zhèr/","example_meaning":"Xin hãy đứng ở đây.","is_approved":true},{"pos":"Danh từ","meaning":"Trạm, ga","example":"我要去北京站。","example_pinyin":"/Wǒ yào qù Běijīng zhàn/","example_meaning":"Tôi muốn đi đến Ga Bắc Kinh.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('找', 'zhǎo', 'Tìm kiếm', '我在找我的手机。', 'Wǒ zài zhǎo wǒ de shǒujī', 'Tôi đang tìm điện thoại của tôi.', 'Động từ', '[{"pos":"Động từ","meaning":"Tìm kiếm","example":"我在找我的手机。","example_pinyin":"/Wǒ zài zhǎo wǒ de shǒujī/","example_meaning":"Tôi đang tìm điện thoại của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('找到', 'zhǎodào', 'Tìm thấy', '我找到钥匙了。', 'Wǒ zhǎodào yàoshi le', 'Tôi tìm thấy chìa khóa rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Tìm thấy","example":"我找到钥匙了。","example_pinyin":"/Wǒ zhǎodào yàoshi le/","example_meaning":"Tôi tìm thấy chìa khóa rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('这', 'zhè', 'Này, đây', '这是我的书。', 'Zhè shì wǒ de shū', 'Đây là sách của tôi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Này, đây","example":"这是我的书。","example_pinyin":"/Zhè shì wǒ de shū/","example_meaning":"Đây là sách của tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('这边', 'zhèbiān', 'Bên này, phía này', '你坐这边吧。', 'Nǐ zuò zhèbiān ba', 'Bạn ngồi bên này đi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Bên này, phía này","example":"你坐这边吧。","example_pinyin":"/Nǐ zuò zhèbiān ba/","example_meaning":"Bạn ngồi bên này đi.","is_approved":true}]', 'HSK1');
