INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('这儿', 'zhèr', 'Ở đây', '你来这儿看看吧。', 'Nǐ lái zhèr kànkan ba', 'Bạn đến chỗ này xem thử đi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Ở đây","example":"你来这儿看看吧。","example_pinyin":"/Nǐ lái zhèr kànkan ba/","example_meaning":"Bạn đến chỗ này xem thử đi.","is_approved":true}]', 'HSK1');
