INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('着', 'zhe', 'Đang (dùng để chỉ trạng thái tiếp diễn)', '他笑着说话。', 'Tā xiào zhe shuōhuà', 'Anh ấy vừa cười vừa nói.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Đang (dùng để chỉ trạng thái tiếp diễn)","example":"他笑着说话。","example_pinyin":"/Tā xiào zhe shuōhuà/","example_meaning":"Anh ấy vừa cười vừa nói.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('真', 'zhēn', 'Thật, rất', '这个地方真美。', 'Zhège dìfāng zhēn měi', 'Nơi này thật đẹp!', 'Phó từ', '[{"pos":"Phó từ","meaning":"Thật, rất","example":"这个地方真美。","example_pinyin":"/Zhège dìfāng zhēn měi/","example_meaning":"Nơi này thật đẹp!","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('真的', 'zhēn de', 'Thật sự, thực sự', '你真的要去吗？', 'Nǐ zhēnde yào qù ma', 'Bạn thật sự muốn đi à?', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Thật sự, thực sự","example":"你真的要去吗？","example_pinyin":"/Nǐ zhēnde yào qù ma/","example_meaning":"Bạn thật sự muốn đi à?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('正', 'zhèng', 'vừa hay, đúng lúc', '我正好要去找你。', 'Wǒ zhènghǎo yào qù zhǎo nǐ', 'Tôi vừa hay định đi tìm bạn.', 'Phó từ', '[{"pos":"Phó từ","meaning":"vừa hay, đúng lúc","example":"我正好要去找你。","example_pinyin":"/Wǒ zhènghǎo yào qù zhǎo nǐ/","example_meaning":"Tôi vừa hay định đi tìm bạn.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('正在', 'zhèngzài', 'Đang (chỉ hành động xảy ra trong hiện tại)', '我正在写作业。', 'Wǒ zhèngzài xiě zuòyè', 'Tôi đang làm bài tập.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Đang (chỉ hành động xảy ra trong hiện tại)","example":"我正在写作业。","example_pinyin":"/Wǒ zhèngzài xiě zuòyè/","example_meaning":"Tôi đang làm bài tập.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('知道', 'zhī dào', 'Biết, hiểu biết', '你知道他的名字吗？', 'Nǐ zhīdào tā de míngzi ma?', 'Bạn có biết tên của anh ấy không?', 'Động từ', '[{"pos":"Động từ","meaning":"Biết, hiểu biết","example":"你知道他的名字吗？","example_pinyin":"/Nǐ zhīdào tā de míngzi ma?/","example_meaning":"Bạn có biết tên của anh ấy không?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('知识', 'zhīshi', 'Kiến thức', '学习知识很重要。', 'Xuéxí zhīshi hěn zhòngyào', 'Việc học rất quan trọng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Kiến thức","example":"学习知识很重要。","example_pinyin":"/Xuéxí zhīshi hěn zhòngyào/","example_meaning":"Việc học rất quan trọng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中', 'zhōng', 'Ở giữa, trung tâm', '她站在房间中间。', 'Tā zhàn zài fángjiān de zhōngjiān', 'Cô ấy đứng ở giữa phòng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ở giữa, trung tâm","example":"她站在房间中间。","example_pinyin":"/Tā zhàn zài fángjiān de zhōngjiān/","example_meaning":"Cô ấy đứng ở giữa phòng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中国', 'Zhōngguó', 'Trung quốc', '中国是一个美丽的国家。', 'Zhōngguó shì yī gè měilì de guójiā', 'Trung Quốc là một đất nước xinh đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trung quốc","example":"中国是一个美丽的国家。","example_pinyin":"/Zhōngguó shì yī gè měilì de guójiā/","example_meaning":"Trung Quốc là một đất nước xinh đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中间', 'zhōngjiān', 'Ở giữa, trung gian', '我家在学校和公司中间。', 'Wǒ jiā zài xuéxiào hé gōngsī zhōngjiān', 'Nhà tôi nằm giữa trường học và công ty.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ở giữa, trung gian","example":"我家在学校和公司中间。","example_pinyin":"/Wǒ jiā zài xuéxiào hé gōngsī zhōngjiān/","example_meaning":"Nhà tôi nằm giữa trường học và công ty.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中文', 'Zhōngwén', 'Tiếng trung quốc', '你的中文很好。', 'Nǐ de Zhōngwén hěn hǎo', 'Tiếng Trung của bạn rất tốt', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tiếng trung quốc","example":"你的中文很好。","example_pinyin":"/Nǐ de Zhōngwén hěn hǎo/","example_meaning":"Tiếng Trung của bạn rất tốt","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中午', 'zhōngwǔ', 'Buổi trưa', '我们中午去吃饭吧。', 'Wǒmen zhōngwǔ qù chīfàn ba', 'Chúng ta đi ăn trưa nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Buổi trưa","example":"我们中午去吃饭吧。","example_pinyin":"/Wǒmen zhōngwǔ qù chīfàn ba/","example_meaning":"Chúng ta đi ăn trưa nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中学', 'zhōngxué', 'Trường trung học', '他是我中学同学。', 'Tā shì wǒ zhōngxué tóngxué', 'Anh ấy là bạn học của tôi ở trường trung học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trường trung học","example":"他是我中学同学。","example_pinyin":"/Tā shì wǒ zhōngxué tóngxué/","example_meaning":"Anh ấy là bạn học của tôi ở trường trung học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('中学生', 'zhōngxuéshēng', 'Học sinh trung học', '他是一个中学生。', 'Tā shì yí gè zhōngxuéshēng', 'Cậu ấy là một học sinh trung học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Học sinh trung học","example":"他是一个中学生。","example_pinyin":"/Tā shì yí gè zhōngxuéshēng/","example_meaning":"Cậu ấy là một học sinh trung học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('重', 'zhòng', 'Nặng

trọng yếu, quan trọng', '这个箱子很重。

这是个重大决定。', 'Zhège xiāngzi hěn zhòng

Zhè shìgè zhòngdà juédìng', 'Chiếc hộp này rất nặng.

Đây là một quyết định quan trọng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nặng\n\ntrọng yếu, quan trọng","example":"这个箱子很重。\n\n这是个重大决定。","example_pinyin":"/Zhège xiāngzi hěn zhòng/\n\n/Zhè shìgè zhòngdà juédìng/","example_meaning":"Chiếc hộp này rất nặng.\n\nĐây là một quyết định quan trọng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('重要', 'zhòngyào', 'Quan trọng', '学习汉语对我来说很重要。', 'Xuéxí Hànyǔ duì wǒ lái shuō hěn zhòngyào', 'Học tiếng Trung rất quan trọng đối với tôi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Quan trọng","example":"学习汉语对我来说很重要。","example_pinyin":"/Xuéxí Hànyǔ duì wǒ lái shuō hěn zhòngyào/","example_meaning":"Học tiếng Trung rất quan trọng đối với tôi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('住', 'zhù', 'Ở, cư trú, sống', '你住在哪个城市？', 'Nǐ zhù zài nǎge chéngshì', 'Bạn sống ở thành phố nào?', 'Động từ', '[{"pos":"Động từ","meaning":"Ở, cư trú, sống","example":"你住在哪个城市？","example_pinyin":"/Nǐ zhù zài nǎge chéngshì/","example_meaning":"Bạn sống ở thành phố nào?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('准备', 'zhǔnbèi', 'Chuẩn bị', 'A: 你准备好了吗？
B: 我们要出发了。', 'A: Nǐ zhǔnbèi hǎo le ma
B: Wǒmen yào chūfā le', 'A: Bạn chuẩn bị xong chưa? 
B: Chúng ta sắp xuất phát rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Chuẩn bị","example":"A: 你准备好了吗？\nB: 我们要出发了。","example_pinyin":"A: /Nǐ zhǔnbèi hǎo le ma/\nB: /Wǒmen yào chūfā le/","example_meaning":"A: Bạn chuẩn bị xong chưa? \nB: Chúng ta sắp xuất phát rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('桌子', 'zhuōzi', 'Cái bàn', '书在桌子上，你看见了吗？', 'Shū zài zhuōzi shàng, nǐ kànjiàn le ma', 'Quyển sách ở trên bàn, bạn thấy chưa?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cái bàn","example":"书在桌子上，你看见了吗？","example_pinyin":"/Shū zài zhuōzi shàng, nǐ kànjiàn le ma/","example_meaning":"Quyển sách ở trên bàn, bạn thấy chưa?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('字', 'zì', 'Chữ, từ', '我不认识这个字。', 'Wǒ bù rènshi zhège zì', 'Tôi không biết chữ này.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chữ, từ","example":"我不认识这个字。","example_pinyin":"/Wǒ bù rènshi zhège zì/","example_meaning":"Tôi không biết chữ này.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('子（桌子）', 'zi (zhuōzi)', 'Hậu tố dùng trong danh từ', '你的桌子很大，很好看。', 'Nǐ de zhuōzi hěn dà, hěn hǎokàn', 'Cái bàn của bạn rất lớn, rất đẹp.', 'Hậu tố', '[{"pos":"Hậu tố","meaning":"Hậu tố dùng trong danh từ","example":"你的桌子很大，很好看。","example_pinyin":"/Nǐ de zhuōzi hěn dà, hěn hǎokàn/","example_meaning":"Cái bàn của bạn rất lớn, rất đẹp.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('走', 'zǒu', 'Đi, rời đi', '我们一起走吧，太晚了。', 'Wǒmen yīqǐ zǒu ba, tài wǎn le', 'Chúng ta cùng đi thôi, trễ quá rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi, rời đi","example":"我们一起走吧，太晚了。","example_pinyin":"/Wǒmen yīqǐ zǒu ba, tài wǎn le/","example_meaning":"Chúng ta cùng đi thôi, trễ quá rồi.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('走路', 'zǒu lù', 'Đi bộ', '他每天早上都走路去学校。', 'Tā měitiān zǎoshang dōu zǒulù qù xuéxiào', 'Mỗi sáng anh ấy đều đi bộ đến trường.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi bộ","example":"他每天早上都走路去学校。","example_pinyin":"/Tā měitiān zǎoshang dōu zǒulù qù xuéxiào/","example_meaning":"Mỗi sáng anh ấy đều đi bộ đến trường.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('最', 'zuì', 'Nhất (chỉ mức độ cao nhất)', '你最喜欢吃什么水果？', 'Nǐ zuì xǐhuan chī shénme shuǐguǒ', 'Bạn thích ăn loại trái cây nào nhất?', 'Phó từ', '[{"pos":"Phó từ","meaning":"Nhất (chỉ mức độ cao nhất)","example":"你最喜欢吃什么水果？","example_pinyin":"/Nǐ zuì xǐhuan chī shénme shuǐguǒ/","example_meaning":"Bạn thích ăn loại trái cây nào nhất?","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('最好', 'zuìhǎo', 'Tốt nhất', '下雨了，你最好带伞。', 'Xiàyǔ le, nǐ zuìhǎo dài sǎn', 'Trời mưa rồi, tốt nhất bạn nên mang ô.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Tốt nhất","example":"下雨了，你最好带伞。","example_pinyin":"/Xiàyǔ le, nǐ zuìhǎo dài sǎn/","example_meaning":"Trời mưa rồi, tốt nhất bạn nên mang ô.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('最后', 'zuìhòu', 'Cuối cùng', '最后一个问题，你听好了。', 'Zuìhòu yī gè wèntí, nǐ tīng hǎo le', 'Câu hỏi cuối cùng, bạn nghe kỹ nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cuối cùng","example":"最后一个问题，你听好了。","example_pinyin":"/Zuìhòu yī gè wèntí, nǐ tīng hǎo le/","example_meaning":"Câu hỏi cuối cùng, bạn nghe kỹ nhé.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('昨天', 'zuótiān', 'Hôm qua', '昨天天气很好，我们去公园了。', 'Zuótiān tiānqì hěn hǎo, wǒmen qù gōngyuán le', 'Hôm qua thời tiết rất đẹp, chúng tôi đã đi công viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Hôm qua","example":"昨天天气很好，我们去公园了。","example_pinyin":"/Zuótiān tiānqì hěn hǎo, wǒmen qù gōngyuán le/","example_meaning":"Hôm qua thời tiết rất đẹp, chúng tôi đã đi công viên.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('左', 'zuǒ', 'Bên trái', '请往左走，那边有商店。', 'Qǐng wǎng zuǒ zǒu, nàbiān yǒu shāngdiàn', 'Hãy đi về bên trái, bên đó có cửa hàng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên trái","example":"请往左走，那边有商店。","example_pinyin":"/Qǐng wǎng zuǒ zǒu, nàbiān yǒu shāngdiàn/","example_meaning":"Hãy đi về bên trái, bên đó có cửa hàng.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('左边', 'zuǒbian', 'Phía bên trái', '我家在学校左边。', 'Wǒ jiā zài xuéxiào zuǒbian', 'Nhà tôi ở bên trái trường học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phía bên trái","example":"我家在学校左边。","example_pinyin":"/Wǒ jiā zài xuéxiào zuǒbian/","example_meaning":"Nhà tôi ở bên trái trường học.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('坐', 'zuò', 'Ngồi', '请坐这里，老师马上来。', 'Qǐng zuò zhèlǐ, lǎoshī mǎshàng lái', 'Mời ngồi đây, thầy giáo sẽ đến ngay.', 'Động từ', '[{"pos":"Động từ","meaning":"Ngồi","example":"请坐这里，老师马上来。","example_pinyin":"/Qǐng zuò zhèlǐ, lǎoshī mǎshàng lái/","example_meaning":"Mời ngồi đây, thầy giáo sẽ đến ngay.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('坐下', 'zuòxia', 'Ngồi xuống', '咱们坐下谈吧。', 'Zánmen zuòxia tán ba', 'Chúng ta ngồi xuống nói chuyện.', 'Động từ', '[{"pos":"Động từ","meaning":"Ngồi xuống","example":"咱们坐下谈吧。","example_pinyin":"/Zánmen zuòxia tán ba/","example_meaning":"Chúng ta ngồi xuống nói chuyện.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('做', 'zuò', 'Làm, thực hiện', '我妈做中国菜非常好吃。', 'Wǒ mā zuò Zhōngguó cài fēicháng hǎochī', 'Mẹ tôi làm đồ ăn Trung Quốc rất ngon.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm, thực hiện","example":"我妈做中国菜非常好吃。","example_pinyin":"/Wǒ mā zuò Zhōngguó cài fēicháng hǎochī/","example_meaning":"Mẹ tôi làm đồ ăn Trung Quốc rất ngon.","is_approved":true}]', 'HSK1');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('啊', 'a', 'A, à', '你来了啊！', 'Nǐ lái le ā', 'Bạn đến rồi à!', 'Thán từ', '[{"pos":"Thán từ","meaning":"A, à","example":"你来了啊！","example_pinyin":"/Nǐ lái le ā/","example_meaning":"Bạn đến rồi à!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爱情', 'àiqíng', 'Tình yêu, tình cảm', '他们的爱情很美好。', 'Tāmen de àiqíng hěn měihǎo', 'Tình yêu của họ rất đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tình yêu, tình cảm","example":"他们的爱情很美好。","example_pinyin":"/Tāmen de àiqíng hěn měihǎo/","example_meaning":"Tình yêu của họ rất đẹp.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爱人', 'àirén', 'Người yêu', '他的爱人是医生。', 'Tā de àirén shì yīshēng', 'Người yêu của anh ấy là bác sĩ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người yêu","example":"他的爱人是医生。","example_pinyin":"/Tā de àirén shì yīshēng/","example_meaning":"Người yêu của anh ấy là bác sĩ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('安静', 'ānjìng', 'Yên tĩnh', '请安静一点儿！', 'Qǐng ānjìng yìdiǎnr', 'Xin hãy yên lặng một chút!', 'Tính từ', '[{"pos":"Tính từ","meaning":"Yên tĩnh","example":"请安静一点儿！","example_pinyin":"/Qǐng ānjìng yìdiǎnr/","example_meaning":"Xin hãy yên lặng một chút!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('安全', 'ānquán', 'An toàn', '晚上一个人走路不太安全。', 'Wǎnshàng yígè rén zǒulù bú tài ānquán', 'Đi bộ một mình vào buổi tối sẽ không an toàn lắm.', 'Tính từ', '[{"pos":"Tính từ","meaning":"An toàn","example":"晚上一个人走路不太安全。","example_pinyin":"/Wǎnshàng yígè rén zǒulù bú tài ānquán/","example_meaning":"Đi bộ một mình vào buổi tối sẽ không an toàn lắm.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('白色', 'báisè', 'Màu trắng', '我喜欢白色的衣服。', 'Wǒ xǐhuan báisè de yīfu', 'Tôi thích quần áo màu trắng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Màu trắng","example":"我喜欢白色的衣服。","example_pinyin":"/Wǒ xǐhuan báisè de yīfu/","example_meaning":"Tôi thích quần áo màu trắng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('班长', 'bānzhǎng', 'Lớp trưởng', '我们班的班长很聪明。', 'Wǒmen bān de bānzhǎng hěn cōngmíng', 'Lớp trưởng của lớp chúng tôi rất thông minh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lớp trưởng","example":"我们班的班长很聪明。","example_pinyin":"/Wǒmen bān de bānzhǎng hěn cōngmíng/","example_meaning":"Lớp trưởng của lớp chúng tôi rất thông minh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('办', 'bàn', 'Làm, xử lý', '我去办签证。', 'Wǒ qù bàn qiānzhèng', 'Tôi đi làm visa.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm, xử lý","example":"我去办签证。","example_pinyin":"/Wǒ qù bàn qiānzhèng/","example_meaning":"Tôi đi làm visa.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('办法', 'bànfǎ', 'Cách làm, biện pháp', '你有办法吗？', 'Nǐ yǒu bànfǎ ma', 'Bạn có cách nào không?', 'Phó từ', '[{"pos":"Phó từ","meaning":"Cách làm, biện pháp","example":"你有办法吗？","example_pinyin":"/Nǐ yǒu bànfǎ ma/","example_meaning":"Bạn có cách nào không?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('办公室', 'bàngōngshì', 'Phòng làm việc', '老师在办公室工作。', 'Lǎoshī zài bàngōngshì gōngzuò', 'Giáo viên đang làm việc ở văn phòng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phòng làm việc","example":"老师在办公室工作。","example_pinyin":"/Lǎoshī zài bàngōngshì gōngzuò/","example_meaning":"Giáo viên đang làm việc ở văn phòng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('半夜', 'bànyè', 'Nửa đêm', '他半夜还在看书。', 'Tā bànyè hái zài kàn shū', 'Nửa đêm rồi mà anh ấy vẫn đang đọc sách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nửa đêm","example":"他半夜还在看书。","example_pinyin":"/Tā bànyè hái zài kàn shū/","example_meaning":"Nửa đêm rồi mà anh ấy vẫn đang đọc sách.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('帮助', 'bāngzhù', 'Giúp đỡ', '我需要你的(tô đỏ帮助)。', 'Wǒ xūyào nǐ de bāngzhù', 'Tôi cần sự giúp đỡ của bạn', 'Động từ', '[{"pos":"Động từ","meaning":"Giúp đỡ","example":"我需要你的(tô đỏ帮助)。","example_pinyin":"/Wǒ xūyào nǐ de bāngzhù/","example_meaning":"Tôi cần sự giúp đỡ của bạn","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('饱', 'bǎo', 'No', '我吃饱了。', 'Wǒ chī bǎo le', 'Tôi ăn no rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"No","example":"我吃饱了。","example_pinyin":"/Wǒ chī bǎo le/","example_meaning":"Tôi ăn no rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('报名', 'bàomíng', 'Đăng ký', '你报名参加比赛了吗？', 'Nǐ bàomíng cānjiā bǐsài le ma', 'Bạn đã đăng ký tham gia cuộc thi chưa?', 'Động từ', '[{"pos":"Động từ","meaning":"Đăng ký","example":"你报名参加比赛了吗？","example_pinyin":"/Nǐ bàomíng cānjiā bǐsài le ma/","example_meaning":"Bạn đã đăng ký tham gia cuộc thi chưa?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('报纸', 'bàozhǐ', 'Báo, tờ báo', '我爸爸每天早上都看报纸。', 'Wǒ bàba měitiān zǎoshang dōu kàn bàozhǐ', 'Mỗi buổi sáng ba tôi đều đọc báo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Báo, tờ báo","example":"我爸爸每天早上都看报纸。","example_pinyin":"/Wǒ bàba měitiān zǎoshang dōu kàn bàozhǐ/","example_meaning":"Mỗi buổi sáng ba tôi đều đọc báo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('北方', 'běifāng', 'Phương bắc', '中国北方的冬天很冷。', 'Zhōngguó běifāng de dōngtiān hěn lěng', 'Mùa đông ở miền Bắc Trung Quốc rất lạnh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phương bắc","example":"中国北方的冬天很冷。","example_pinyin":"/Zhōngguó běifāng de dōngtiān hěn lěng/","example_meaning":"Mùa đông ở miền Bắc Trung Quốc rất lạnh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('背', 'bèi', 'Cõng, mang vác

bó', '他背小孩走过山坡。

一背柴火足够用了。', 'Tā bēi xiǎohái zǒuguò shānpō

