Lượng từ', '[{"pos":"Động từ\n\nLượng từ","meaning":"Cõng, mang vác\n\nbó","example":"他背小孩走过山坡。\n\n一背柴火足够用了。","example_pinyin":"/Tā bēi xiǎohái zǒuguò shānpō/\n\n/Yī bēi cháihuǒ zúgòu yòng le/","example_meaning":"Anh ấy cõng đứa bé đi qua sườn núi.\n\nMột bó củi là đủ dùng rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('比如', 'bǐrú', 'Ví dụ', '我喜欢运动，比如跑步和游泳。', 'Wǒ xǐhuan yùndòng, bǐrú pǎobù hé yóuyǒng', 'Tôi thích thể thao, ví dụ như chạy bộ và bơi lội.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Ví dụ","example":"我喜欢运动，比如跑步和游泳。","example_pinyin":"/Wǒ xǐhuan yùndòng, bǐrú pǎobù hé yóuyǒng/","example_meaning":"Tôi thích thể thao, ví dụ như chạy bộ và bơi lội.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('比如说', 'bǐrú shuō', 'Ví dụ, chẳng hạn như', '这里有很多好吃的，比如说北京烤鸭和饺子。', 'Zhèlǐ yǒu hěn duō hǎochī de, bǐrú shuō Běijīng kǎoyā hé jiǎozi', 'Ở đây có nhiều món ngon, ví dụ như vịt quay Bắc Kinh và sủi cảo.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Ví dụ, chẳng hạn như","example":"这里有很多好吃的，比如说北京烤鸭和饺子。","example_pinyin":"/Zhèlǐ yǒu hěn duō hǎochī de, bǐrú shuō Běijīng kǎoyā hé jiǎozi/","example_meaning":"Ở đây có nhiều món ngon, ví dụ như vịt quay Bắc Kinh và sủi cảo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('笔', 'bǐ', 'Bút', '我的笔呢？', 'Wǒ de bǐ ne?', 'Cây bút của tôi đâu rồi?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bút","example":"我的笔呢？","example_pinyin":"/Wǒ de bǐ ne?/","example_meaning":"Cây bút của tôi đâu rồi?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('笔记', 'bǐjì', 'Ghi', '上课时要认真做笔记。', 'Shàngkè shí yào rènzhēn zuò bǐjì', 'Trong lớp học phải ghi chép cẩn thận.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ghi","example":"上课时要认真做笔记。","example_pinyin":"/Shàngkè shí yào rènzhēn zuò bǐjì/","example_meaning":"Trong lớp học phải ghi chép cẩn thận.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('笔记本', 'bǐjìběn', 'Sổ ghi chép', '我买了一个新的笔记本。', 'Wǒ mǎi le yí gè xīn de bǐjìběn', 'Tôi đã mua một quyển sổ ghi chép mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sổ ghi chép","example":"我买了一个新的笔记本。","example_pinyin":"/Wǒ mǎi le yí gè xīn de bǐjìběn/","example_meaning":"Tôi đã mua một quyển sổ ghi chép mới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('必须', 'bìxū', 'Cần, phải', '你必须每天练习说汉语。', 'Nǐ bìxū měitiān liànxí shuō Hànyǔ', 'Bạn cần phải luyện tập nói tiếng Trung mỗi ngày.', 'Động từ', '[{"pos":"Động từ","meaning":"Cần, phải","example":"你必须每天练习说汉语。","example_pinyin":"/Nǐ bìxū měitiān liànxí shuō Hànyǔ/","example_meaning":"Bạn cần phải luyện tập nói tiếng Trung mỗi ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('边', 'biān', 'Bên, bên cạnh', '他坐在窗边看书。', 'Tā zuò zài chuāng biān kàn shū', 'Anh ấy ngồi bên cửa sổ đọc sách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên, bên cạnh","example":"他坐在窗边看书。","example_pinyin":"/Tā zuò zài chuāng biān kàn shū/","example_meaning":"Anh ấy ngồi bên cửa sổ đọc sách.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('变', 'biàn', 'Biến đổi, thay đổi', '天气变冷了。', 'Tiānqì biàn lěng le', 'Thời tiết trở lạnh rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Biến đổi, thay đổi","example":"天气变冷了。","example_pinyin":"/Tiānqì biàn lěng le/","example_meaning":"Thời tiết trở lạnh rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('变成', 'biànchéng', 'Trở thành, biến thành', '这些种子都变成花了。', 'Zhèxiē zhǒngzǐ dōu biàn chéng huā le', 'Những hạt giống này đều biến thành hoa.', 'Động từ', '[{"pos":"Động từ","meaning":"Trở thành, biến thành","example":"这些种子都变成花了。","example_pinyin":"/Zhèxiē zhǒngzǐ dōu biàn chéng huā le/","example_meaning":"Những hạt giống này đều biến thành hoa.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('遍', 'biàn', 'Lần', '这本书我看了三遍。', 'Zhè běn shū wǒ kàn le sān biàn', 'Quyển sách này tôi đã đọc ba lần.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Lần","example":"这本书我看了三遍。","example_pinyin":"/Zhè běn shū wǒ kàn le sān biàn/","example_meaning":"Quyển sách này tôi đã đọc ba lần.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('表', 'biǎo', 'Bảng, đồng hồ', '我的手表坏了。', 'Wǒ de shǒubiǎo huài le', 'Đồng hồ của tôi bị hỏng rồi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bảng, đồng hồ","example":"我的手表坏了。","example_pinyin":"/Wǒ de shǒubiǎo huài le/","example_meaning":"Đồng hồ của tôi bị hỏng rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('表示', 'biǎoshì', 'Biểu thị, bày tỏ', '他点头表示同意。', 'Tā diǎntóu biǎoshì tóngyì', 'Anh ấy gật đầu để bày tỏ sự đồng ý.', 'Động từ', '[{"pos":"Động từ","meaning":"Biểu thị, bày tỏ","example":"他点头表示同意。","example_pinyin":"/Tā diǎntóu biǎoshì tóngyì/","example_meaning":"Anh ấy gật đầu để bày tỏ sự đồng ý.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不错', 'búcuò', 'Không tệ, khá tốt', '人家待你可真不错。', 'Rénjiā dài nǐ kě zhēnbùcuò', 'Mọi người đối xử với anh khá tốt.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Không tệ, khá tốt","example":"人家待你可真不错。","example_pinyin":"/Rénjiā dài nǐ kě zhēnbùcuò/","example_meaning":"Mọi người đối xử với anh khá tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不但', 'búdàn', 'Không những, không chỉ', '她不但会唱歌，还会跳舞。', 'Tā búdàn huì chànggē, hái huì tiàowǔ', 'Cô ấy không chỉ biết hát, mà còn biết nhảy.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Không những, không chỉ","example":"她不但会唱歌，还会跳舞。","example_pinyin":"/Tā búdàn huì chànggē, hái huì tiàowǔ/","example_meaning":"Cô ấy không chỉ biết hát, mà còn biết nhảy.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不够', 'búgòu', 'Không đủ', '他的态度不够认真。', 'Tā de tàidù bùgòu rènzhēn', 'Thái độ của anh ấy chưa đủ nghiêm túc.', 'Động từ', '[{"pos":"Động từ","meaning":"Không đủ","example":"他的态度不够认真。","example_pinyin":"/Tā de tàidù bùgòu rènzhēn/","example_meaning":"Thái độ của anh ấy chưa đủ nghiêm túc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不过', 'búguò', 'Nhưng, tuy nhiên', '这件衣服很好看，不过太贵了。', 'Zhè jiàn yīfu hěn hǎokàn, búguò tài guì le', 'Bộ quần áo này rất đẹp, nhưng mà nó mắc quá.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Nhưng, tuy nhiên","example":"这件衣服很好看，不过太贵了。","example_pinyin":"/Zhè jiàn yīfu hěn hǎokàn, búguò tài guì le/","example_meaning":"Bộ quần áo này rất đẹp, nhưng mà nó mắc quá.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不太', 'bú tài', 'Không quá,  không lắm', '我的英语不太好。', 'Wǒ de yīngyǔ bù tài hǎo', 'Tiếng Anh của tôi không tốt lắm.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không quá,  không lắm","example":"我的英语不太好。","example_pinyin":"/Wǒ de yīngyǔ bù tài hǎo/","example_meaning":"Tiếng Anh của tôi không tốt lắm.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不要', 'búyào', 'Đừng, không được', '不要在教室里大声说话。', 'Búyào zài jiàoshì lǐ dàshēng shuōhuà', 'Đừng nói chuyện lớn tiếng trong lớp học.', 'Động từ/ Trợ động từ', '[{"pos":"Động từ/ Trợ động từ","meaning":"Đừng, không được","example":"不要在教室里大声说话。","example_pinyin":"/Búyào zài jiàoshì lǐ dàshēng shuōhuà/","example_meaning":"Đừng nói chuyện lớn tiếng trong lớp học.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不好意思', 'bù hǎoyìsi', 'Ngại, xấu hổ', '我迟到了，真不好意思。', 'Wǒ chídào le, zhēn bù hǎoyìsi', 'Tôi đến muộn rồi, thật ngại quá.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Ngại, xấu hổ","example":"我迟到了，真不好意思。","example_pinyin":"/Wǒ chídào le, zhēn bù hǎoyìsi/","example_meaning":"Tôi đến muộn rồi, thật ngại quá.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不久', 'bùjiǔ', 'Không lâu, chẳng bao lâu', '我们不久就会再见面。', 'Wǒmen bùjiǔ jiù huì zài jiànmiàn', 'Chúng ta sẽ sớm gặp lại nhau.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Không lâu, chẳng bao lâu","example":"我们不久就会再见面。","example_pinyin":"/Wǒmen bùjiǔ jiù huì zài jiànmiàn/","example_meaning":"Chúng ta sẽ sớm gặp lại nhau.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不满', 'bùmǎn', 'Bất mãn, không hài lòng', '她对服务态度不满。', 'Tā duì fúwù tàidù bùmǎn', 'Cô ấy không hài lòng với thái độ phục vụ.', 'Động từ', '[{"pos":"Động từ","meaning":"Bất mãn, không hài lòng","example":"她对服务态度不满。","example_pinyin":"/Tā duì fúwù tàidù bùmǎn/","example_meaning":"Cô ấy không hài lòng với thái độ phục vụ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不如', 'bùrú', 'Không bằng

chi bằng, thà rằng', '我的中文不如他的好。

与其看电视，不如读一本好书。', 'Tā de zhōngwén bùrú wǒ de hǎo

Yǔqí kàn diànshì, bùrú dú yī běn hǎo shū', 'Tiếng Trung của anh ấy không giỏi bằng tôi.

Thay vì xem tivi, chi bằng đọc một quyển sách hay.', 'Động từ  

Liên từ', '[{"pos":"Động từ  \n\nLiên từ","meaning":"Không bằng\n\nchi bằng, thà rằng","example":"我的中文不如他的好。\n\n与其看电视，不如读一本好书。","example_pinyin":"/Tā de zhōngwén bùrú wǒ de hǎo/\n\n/Yǔqí kàn diànshì, bùrú dú yī běn hǎo shū/","example_meaning":"Tiếng Trung của anh ấy không giỏi bằng tôi.\n\nThay vì xem tivi, chi bằng đọc một quyển sách hay.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不少', 'bù shǎo', 'Không ít', '他有不少中国朋友。', 'Tā yǒu bù shǎo Zhōngguó péngyǒu', 'Anh ấy có khá nhiều bạn người Trung Quốc.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Không ít","example":"他有不少中国朋友。","example_pinyin":"/Tā yǒu bù shǎo Zhōngguó péngyǒu/","example_meaning":"Anh ấy có khá nhiều bạn người Trung Quốc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不同', 'bù tóng', 'Không giống, khác nhau', '我们的想法不同。', 'Wǒmen de xiǎngfǎ bù tóng', 'Suy nghĩ của chúng tôi không giống nhau.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Không giống, khác nhau","example":"我们的想法不同。","example_pinyin":"/Wǒmen de xiǎngfǎ bù tóng/","example_meaning":"Suy nghĩ của chúng tôi không giống nhau.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不行', 'bùxíng', 'Không được, không ổn', '这样做不行。', 'Zhèyàng zuò bùxíng', 'Làm như vậy không được đâu.', 'Động từ', '[{"pos":"Động từ","meaning":"Không được, không ổn","example":"这样做不行。","example_pinyin":"/Zhèyàng zuò bùxíng/","example_meaning":"Làm như vậy không được đâu.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不一定', 'bùyídìng', 'Không nhất định, chưa chắc', '他不一定会来。', 'Tā bù yīdìng huìlái', 'Anh ấy chưa chắc sẽ đến.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Không nhất định, chưa chắc","example":"他不一定会来。","example_pinyin":"/Tā bù yīdìng huìlái/","example_meaning":"Anh ấy chưa chắc sẽ đến.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('不一会儿', 'bù yíhuìr', 'Chẳng bao lâu, không lâu sau', '我刚给他发短信，不一会儿他就回复了。', 'Wǒ gāng gěi tā fā duǎnxìn, bù yíhuìr tā jiù huífù le', 'Tôi vừa nhắn tin cho anh ấy, chẳng bao lâu sau anh ấy đã trả lời.', 'Cụm từ', '[{"pos":"Cụm từ","meaning":"Chẳng bao lâu, không lâu sau","example":"我刚给他发短信，不一会儿他就回复了。","example_pinyin":"/Wǒ gāng gěi tā fā duǎnxìn, bù yíhuìr tā jiù huífù le/","example_meaning":"Tôi vừa nhắn tin cho anh ấy, chẳng bao lâu sau anh ấy đã trả lời.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('部分', 'bùfen', 'Phần, bộ phận', '这本书的第一部分很有趣。', 'Zhè běn shū de dì yī bùfèn hěn yǒuqù', 'Phần đầu của quyển sách này rất thú vị.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phần, bộ phận","example":"这本书的第一部分很有趣。","example_pinyin":"/Zhè běn shū de dì yī bùfèn hěn yǒuqù/","example_meaning":"Phần đầu của quyển sách này rất thú vị.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('才', 'cái', 'Mới, vừa mới', '他昨天才回来。', 'Tā zuótiān cái huílái', 'Anh ấy mới về hôm qua.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Mới, vừa mới","example":"他昨天才回来。","example_pinyin":"/Tā zuótiān cái huílái/","example_meaning":"Anh ấy mới về hôm qua.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('菜单', 'càidān', 'Thực đơn', '请给我菜单。', 'Qǐng gěi wǒ càidān', 'Xin vui lòng đưa cho tôi thực đơn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thực đơn","example":"请给我菜单。","example_pinyin":"/Qǐng gěi wǒ càidān/","example_meaning":"Xin vui lòng đưa cho tôi thực đơn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('参观', 'cānguān', 'Tham quan', '我们明天去参观博物馆。', 'Wǒmen míngtiān qù cānguān bówùguǎn', 'Ngày mai chúng tôi sẽ đi tham quan bảo tàng.', 'Động từ', '[{"pos":"Động từ","meaning":"Tham quan","example":"我们明天去参观博物馆。","example_pinyin":"/Wǒmen míngtiān qù cānguān bówùguǎn/","example_meaning":"Ngày mai chúng tôi sẽ đi tham quan bảo tàng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('参加', 'cānjiā', 'Tham gia', '今天我们一起参加游泳比赛。', 'Jīntiān wǒmen yīqǐ cānjiā yóuyǒng bǐsài', 'Hôm nay chúng tôi cùng nhau tham gia một cuộc thi bơi lội.', 'Động từ', '[{"pos":"Động từ","meaning":"Tham gia","example":"今天我们一起参加游泳比赛。","example_pinyin":"/Jīntiān wǒmen yīqǐ cānjiā yóuyǒng bǐsài/","example_meaning":"Hôm nay chúng tôi cùng nhau tham gia một cuộc thi bơi lội.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('草', 'cǎo', 'Cỏ', '牛牛喜欢吃草。', 'Niúniú xǐhuān chī cǎo', 'Con bò thích ăn cỏ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cỏ","example":"牛牛喜欢吃草。","example_pinyin":"/Niúniú xǐhuān chī cǎo/","example_meaning":"Con bò thích ăn cỏ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('草地', 'cǎodì', 'Bãi cỏ', '孩子们在草地上玩耍。', 'Háizimen zài cǎodì shàng wánshuǎ', 'Bọn trẻ đang chơi trên bãi cỏ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bãi cỏ","example":"孩子们在草地上玩耍。","example_pinyin":"/Háizimen zài cǎodì shàng wánshuǎ/","example_meaning":"Bọn trẻ đang chơi trên bãi cỏ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('层', 'céng', 'Tầng (lầu)', '我住在第五层。', 'Wǒ zhù zài dì wǔ céng', 'Tôi sống ở tầng năm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tầng (lầu)","example":"我住在第五层。","example_pinyin":"/Wǒ zhù zài dì wǔ céng/","example_meaning":"Tôi sống ở tầng năm.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('查', 'chá', 'Tra cứu, kiểm tra', '请查一下这个单词的意思。', 'Qǐng chá yīxià zhège dāncí de yìsi', 'Hãy tra nghĩa của từ này.', 'Động từ', '[{"pos":"Động từ","meaning":"Tra cứu, kiểm tra","example":"请查一下这个单词的意思。","example_pinyin":"/Qǐng chá yīxià zhège dāncí de yìsi/","example_meaning":"Hãy tra nghĩa của từ này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('差不多', 'chàbuduō', 'Gần như, xấp xỉ', '这两个城市的天气差不多。', 'Zhè liǎng gè chéngshì de tiānqì chàbuduō', 'Thời tiết của hai thành phố này gần như giống nhau.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Gần như, xấp xỉ","example":"这两个城市的天气差不多。","example_pinyin":"/Zhè liǎng gè chéngshì de tiānqì chàbuduō/","example_meaning":"Thời tiết của hai thành phố này gần như giống nhau.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('长', 'cháng', 'Dài', '这条裤子很长。', 'Zhè tiáo kùzi hěn cháng', 'Cái quần này rất dài.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Dài","example":"这条裤子很长。","example_pinyin":"/Zhè tiáo kùzi hěn cháng/","example_meaning":"Cái quần này rất dài.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('常见', 'chángjiàn', 'Thường thấy', '这种花在公园里很常见。', 'Zhè zhǒng huā zài gōngyuán lǐ hěn chángjiàn', 'Loài hoa này rất thường thấy trong công viên.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Thường thấy","example":"这种花在公园里很常见。","example_pinyin":"/Zhè zhǒng huā zài gōngyuán lǐ hěn chángjiàn/","example_meaning":"Loài hoa này rất thường thấy trong công viên.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('常用', 'chángyòng', 'Thường dùng', '这是一本常用的词典。', 'Zhè shì yī běn chángyòng de cídiǎn', 'Đây là một cuốn từ điển thông dụng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Thường dùng","example":"这是一本常用的词典。","example_pinyin":"/Zhè shì yī běn chángyòng de cídiǎn/","example_meaning":"Đây là một cuốn từ điển thông dụng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('场', 'chǎng', 'Sân, bãi', '我们在体育场看比赛。', 'Wǒmen zài tǐyùchǎng kàn bǐsài', 'Chúng tôi xem trận đấu ở sân vận động.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sân, bãi","example":"我们在体育场看比赛。","example_pinyin":"/Wǒmen zài tǐyùchǎng kàn bǐsài/","example_meaning":"Chúng tôi xem trận đấu ở sân vận động.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('超过', 'chāoguò', 'Vượt qua', '他的身高超过了一米八。', 'Tā de shēngāo chāoguò le yī mǐ bā', 'Chiều cao của anh ấy vượt quá 1m8.', 'Động từ', '[{"pos":"Động từ","meaning":"Vượt qua","example":"他的身高超过了一米八。","example_pinyin":"/Tā de shēngāo chāoguò le yī mǐ bā/","example_meaning":"Chiều cao của anh ấy vượt quá 1m8.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('超市', 'chāoshì', 'Siêu thị', '我去超市买点水果。', 'Wǒ qù chāoshì mǎi diǎn shuǐguǒ', 'Tôi đi siêu thị mua ít trái cây.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Siêu thị","example":"我去超市买点水果。","example_pinyin":"/Wǒ qù chāoshì mǎi diǎn shuǐguǒ/","example_meaning":"Tôi đi siêu thị mua ít trái cây.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('车辆', 'chēliàng', 'Xe cộ', '这条路上的车辆很多。', 'Zhè tiáo lù shàng de chēliàng hěn duō', 'Có rất nhiều xe cộ trên con đường này.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Xe cộ","example":"这条路上的车辆很多。","example_pinyin":"/Zhè tiáo lù shàng de chēliàng hěn duō/","example_meaning":"Có rất nhiều xe cộ trên con đường này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('称（动）', 'chēng', 'Gọi là, xưng là', '他被称为最优秀的医生。', 'Tā bèi chēng wèi zuì yōuxiù de yīshēng', 'Anh ấy được gọi là bác sĩ xuất sắc nhất.', 'Động từ', '[{"pos":"Động từ","meaning":"Gọi là, xưng là","example":"他被称为最优秀的医生。","example_pinyin":"/Tā bèi chēng wèi zuì yōuxiù de yīshēng/","example_meaning":"Anh ấy được gọi là bác sĩ xuất sắc nhất.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('成（动）', 'chéng', 'Trở thành', '他希望将来能成为一名医生。', 'Tā xīwàng jiānglái néng chéngwéi yī míng yīshēng', 'Anh ấy hy vọng tương lai có thể trở thành bác sĩ.', 'Động từ', '[{"pos":"Động từ","meaning":"Trở thành","example":"他希望将来能成为一名医生。","example_pinyin":"/Tā xīwàng jiānglái néng chéngwéi yī míng yīshēng/","example_meaning":"Anh ấy hy vọng tương lai có thể trở thành bác sĩ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('成绩', 'chéngjì', 'Thành tích', '他这次考试成绩很好。', 'Tā zhè cì kǎoshì chéngjì hěn hǎo', 'Thành tích kỳ thi lần này của anh ấy rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thành tích","example":"他这次考试成绩很好。","example_pinyin":"/Tā zhè cì kǎoshì chéngjì hěn hǎo/","example_meaning":"Thành tích kỳ thi lần này của anh ấy rất tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('成为', 'chéngwéi', 'Trở thành', '她已经成为了一名老师。', 'Tā yǐjīng chéngwéile yī míng lǎoshī', 'Cô ấy đã trở thành một giáo viên.', 'Động từ', '[{"pos":"Động từ","meaning":"Trở thành","example":"她已经成为了一名老师。","example_pinyin":"/Tā yǐjīng chéngwéile yī míng lǎoshī/","example_meaning":"Cô ấy đã trở thành một giáo viên.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('重复', 'chóngfù', 'Lặp lại', '请不要重复你的问题。', 'Qǐng bùyào chóngfù nǐ de wèntí', 'Vui lòng đừng lặp lại câu hỏi của bạn.', 'Động từ', '[{"pos":"Động từ","meaning":"Lặp lại","example":"请不要重复你的问题。","example_pinyin":"/Qǐng bùyào chóngfù nǐ de wèntí/","example_meaning":"Vui lòng đừng lặp lại câu hỏi của bạn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('重新', 'chóngxīn', 'Làm lại từ đầu', '他决定重新开始。', 'Tā juédìng chóngxīn kāishǐ', 'Anh ấy quyết định bắt đầu lại từ đầu.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Làm lại từ đầu","example":"他决定重新开始。","example_pinyin":"/Tā juédìng chóngxīn kāishǐ/","example_meaning":"Anh ấy quyết định bắt đầu lại từ đầu.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出发', 'chūfā', 'Xuất phát', '我们早上八点出发。', 'Wǒmen zǎoshang bā diǎn chūfā', 'Chúng tôi xuất phát lúc 8 giờ sáng.', 'Động từ', '[{"pos":"Động từ","meaning":"Xuất phát","example":"我们早上八点出发。","example_pinyin":"/Wǒmen zǎoshang bā diǎn chūfā/","example_meaning":"Chúng tôi xuất phát lúc 8 giờ sáng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出国', 'chūguó', 'Ra nước ngoài', '他明年要出国留学。', 'Tā míngnián yào chūguó liúxué', 'Năm sau anh ấy sẽ đi du học nước ngoài.', 'Động từ', '[{"pos":"Động từ","meaning":"Ra nước ngoài","example":"他明年要出国留学。","example_pinyin":"/Tā míngnián yào chūguó liúxué/","example_meaning":"Năm sau anh ấy sẽ đi du học nước ngoài.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出口', 'chūkǒu', 'Lối ra', '这个商场的出口在哪里？', 'Zhège shāngchǎng de chūkǒu zài nǎlǐ?', 'Lối ra của trung tâm thương mại này ở đâu?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lối ra","example":"这个商场的出口在哪里？","example_pinyin":"/Zhège shāngchǎng de chūkǒu zài nǎlǐ?/","example_meaning":"Lối ra của trung tâm thương mại này ở đâu?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出门', 'chūmén', 'Ra ngoài', '我今天早上七点出门。', 'Wǒ jīntiān zǎoshang qī diǎn chūmén', 'Sáng nay tôi ra ngoài lúc 7 giờ.', 'Động từ', '[{"pos":"Động từ","meaning":"Ra ngoài","example":"我今天早上七点出门。","example_pinyin":"/Wǒ jīntiān zǎoshang qī diǎn chūmén/","example_meaning":"Sáng nay tôi ra ngoài lúc 7 giờ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出生', 'chūshēng', 'Sinh ra', '他出生于北京。', 'Tā chūshēng yú Běijīng', 'Anh ấy sinh ra ở Bắc Kinh.', 'Động từ', '[{"pos":"Động từ","meaning":"Sinh ra","example":"他出生于北京。","example_pinyin":"/Tā chūshēng yú Běijīng/","example_meaning":"Anh ấy sinh ra ở Bắc Kinh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出现', 'chūxiàn', 'Xuất hiện', '天空中出现了一道彩虹。', 'Tiānkōng zhōng chūxiànle yī dào cǎihóng', 'Trên bầu trời xuất hiện một cầu vồng.', 'Động từ', '[{"pos":"Động từ","meaning":"Xuất hiện","example":"天空中出现了一道彩虹。","example_pinyin":"/Tiānkōng zhōng chūxiànle yī dào cǎihóng/","example_meaning":"Trên bầu trời xuất hiện một cầu vồng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出院', 'chūyuàn', 'Xuất viện', '奶奶明天就能出院了。', 'Nǎinai míngtiān jiù néng chūyuàn le.', 'Ngày mai bà có thể xuất viện rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Xuất viện","example":"奶奶明天就能出院了。","example_pinyin":"/Nǎinai míngtiān jiù néng chūyuàn le./","example_meaning":"Ngày mai bà có thể xuất viện rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出租', 'chūzū', 'Cho thuê', '这套房子正在出租。', 'Zhè tào fángzi zhèngzài chūzū', 'Căn nhà này đang cho thuê.', 'Động từ', '[{"pos":"Động từ","meaning":"Cho thuê","example":"这套房子正在出租。","example_pinyin":"/Zhè tào fángzi zhèngzài chūzū/","example_meaning":"Căn nhà này đang cho thuê.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('出租车', 'chūzūchē', 'Xe taxi', '他坐出租车去机场。', 'Tā zuò chūzūchē qù jīchǎng', 'Anh ấy ngồi taxi đến sân bay.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Xe taxi","example":"他坐出租车去机场。","example_pinyin":"/Tā zuò chūzūchē qù jīchǎng/","example_meaning":"Anh ấy ngồi taxi đến sân bay.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('船', 'chuán', 'Thuyền', '我喜欢坐船。', 'Wǒ xǐhuān zuò chuán', 'Tôi thích ngồi thuyền.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thuyền","example":"我喜欢坐船。","example_pinyin":"/Wǒ xǐhuān zuò chuán/","example_meaning":"Tôi thích ngồi thuyền.","is_approved":true}]', 'HSK2');
