INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('春节', 'Chūnjié', 'Tết nguyên đán', '春节是中国最重要的节日。', 'Chūnjié shì Zhōngguó zuì zhòngyào de jiérì.', 'Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tết nguyên đán","example":"春节是中国最重要的节日。","example_pinyin":"/Chūnjié shì Zhōngguó zuì zhòngyào de jiérì./","example_meaning":"Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('春天', 'chūntiān', 'Mùa xuân', '春天来了，花都开了。', 'Chūntiān lái le, huā dōu kāi le', 'Mùa xuân đến rồi, hoa đều nở.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mùa xuân","example":"春天来了，花都开了。","example_pinyin":"/Chūntiān lái le, huā dōu kāi le/","example_meaning":"Mùa xuân đến rồi, hoa đều nở.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('词', 'cí', 'Từ, lời, lời văn', '这个词是什么意思？', 'Zhège cí shì shénme yìsi?', 'Từ này có nghĩa gì?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Từ, lời, lời văn","example":"这个词是什么意思？","example_pinyin":"/Zhège cí shì shénme yìsi?/","example_meaning":"Từ này có nghĩa gì?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('词典', 'cídiǎn', 'Từ điển', '这是一本汉越词典。', 'Zhè shì yī běn hàn yuè cídiǎn', 'Đây là quyển từ điển Hán - Việt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Từ điển","example":"这是一本汉越词典。","example_pinyin":"/Zhè shì yī běn hàn yuè cídiǎn/","example_meaning":"Đây là quyển từ điển Hán - Việt.","is_approved":true}]', 'HSK2');
