INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('从小', 'cóngxiǎo', 'Từ nhỏ', '我从小就喜欢画画。', 'Wǒ cóngxiǎo jiù xǐhuān huàhuà', 'Tôi thích vẽ tranh từ nhỏ.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Từ nhỏ","example":"我从小就喜欢画画。","example_pinyin":"/Wǒ cóngxiǎo jiù xǐhuān huàhuà/","example_meaning":"Tôi thích vẽ tranh từ nhỏ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('答应', 'dāyìng', 'Đồng ý, hứa', '他答应了。', 'Tā dāyìng le', 'Anh ấy đã đồng ý rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đồng ý, hứa","example":"他答应了。","example_pinyin":"/Tā dāyìng le/","example_meaning":"Anh ấy đã đồng ý rồi.","is_approved":true}]', 'HSK2');
