INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打算', 'dǎsuàn', 'Dự định, kế hoạch', '你打算什么时候去中国？', 'Nǐ dǎsuàn shénme shíhòu qù Zhōngguó', 'Bạn dự định khi nào đi Trung Quốc?', 'Động từ', '[{"pos":"Động từ","meaning":"Dự định, kế hoạch","example":"你打算什么时候去中国？","example_pinyin":"/Nǐ dǎsuàn shénme shíhòu qù Zhōngguó/","example_meaning":"Bạn dự định khi nào đi Trung Quốc?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('打印', 'dǎyìn', 'In ấn', '请帮我打印这份文件。', 'Qǐng bāng wǒ dǎyìn zhè fèn wénjiàn', 'Xin hãy giúp tôi in tài liệu này.', 'Động từ', '[{"pos":"Động từ","meaning":"In ấn","example":"请帮我打印这份文件。","example_pinyin":"/Qǐng bāng wǒ dǎyìn zhè fèn wénjiàn/","example_meaning":"Xin hãy giúp tôi in tài liệu này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大部分', 'dà bù fèn', 'Phần lớn, đa số', '大部分学生都完成了作业。', 'Dà bù fèn xuéshēng dōu wánchéng le zuòyè', 'Phần lớn học sinh đã hoàn thành bài tập về nhà.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phần lớn, đa số","example":"大部分学生都完成了作业。","example_pinyin":"/Dà bù fèn xuéshēng dōu wánchéng le zuòyè/","example_meaning":"Phần lớn học sinh đã hoàn thành bài tập về nhà.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大大', 'dà dà', 'Rất, cực kỳ', '她有一双大大的眼睛，很可爱。', 'Tā de jìnbù dàdà', 'Bé có đôi mắt to và rất dễ thương.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Rất, cực kỳ","example":"她有一双大大的眼睛，很可爱。","example_pinyin":"/Tā de jìnbù dàdà/","example_meaning":"Bé có đôi mắt to và rất dễ thương.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大海', 'dàhǎi', 'Đại dương, biển lớn', '这片大海真美。', 'Zhè piàn dàhǎi zhēn měi', 'Biển này đẹp thật.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đại dương, biển lớn","example":"这片大海真美。","example_pinyin":"/Zhè piàn dàhǎi zhēn měi/","example_meaning":"Biển này đẹp thật.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大多数', 'dàduōshù', 'Đại đa số, phần lớn', '大多数人都喜欢吃甜食。', 'Dàduōshù rén dōu xǐhuān chī tiánshí', 'Phần lớn mọi người đều thích ăn đồ ngọt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đại đa số, phần lớn","example":"大多数人都喜欢吃甜食。","example_pinyin":"/Dàduōshù rén dōu xǐhuān chī tiánshí/","example_meaning":"Phần lớn mọi người đều thích ăn đồ ngọt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大家', 'dàjiā', 'Mọi người', '大家好！欢迎来到我们的学校。', 'Dàjiā hǎo! Huānyíng lái dào wǒmen de xuéxiào', 'Xin chào mọi người! Chào mừng đến với trường của chúng tôi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Mọi người","example":"大家好！欢迎来到我们的学校。","example_pinyin":"/Dàjiā hǎo! Huānyíng lái dào wǒmen de xuéxiào/","example_meaning":"Xin chào mọi người! Chào mừng đến với trường của chúng tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大量', 'dàliàng', 'Số lượng lớn', '这家工厂需要大量的工人。', 'Zhè jiā gōngchǎng xūyào dàliàng de gōngrén', 'Nhà máy này cần một số lượng lớn công nhân.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Số lượng lớn","example":"这家工厂需要大量的工人。","example_pinyin":"/Zhè jiā gōngchǎng xūyào dàliàng de gōngrén/","example_meaning":"Nhà máy này cần một số lượng lớn công nhân.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大门', 'dàmén', 'Cổng lớn', '学校的大门每天七点开门。', 'Xuéxiào de dàmén měitiān qī diǎn kāimén', 'Cổng trường mở lúc 7 giờ mỗi ngày.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cổng lớn","example":"学校的大门每天七点开门。","example_pinyin":"/Xuéxiào de dàmén měitiān qī diǎn kāimén/","example_meaning":"Cổng trường mở lúc 7 giờ mỗi ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大人', 'dàrén', 'Người lớn', '小孩子应该听大人的话。', 'Xiǎo háizi yīnggāi tīng dàrén de huà', 'Trẻ con nên nghe lời người lớn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Người lớn","example":"小孩子应该听大人的话。","example_pinyin":"/Xiǎo háizi yīnggāi tīng dàrén de huà/","example_meaning":"Trẻ con nên nghe lời người lớn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大声', 'dàshēng', 'Nói to, giọng to', '请不要大声说话。', 'Qǐng bùyào dàshēng shuōhuà', 'Xin đừng nói chuyện lớn tiếng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nói to, giọng to","example":"请不要大声说话。","example_pinyin":"/Qǐng bùyào dàshēng shuōhuà/","example_meaning":"Xin đừng nói chuyện lớn tiếng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大小', 'dàxiǎo', 'Kích thước, lớn nhỏ', '这双鞋的大小正合适。', 'Zhè shuāng xié de dàxiǎo zhèng héshì', 'Đôi giày này có kích thước vừa vặn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Kích thước, lớn nhỏ","example":"这双鞋的大小正合适。","example_pinyin":"/Zhè shuāng xié de dàxiǎo zhèng héshì/","example_meaning":"Đôi giày này có kích thước vừa vặn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大衣', 'dàyī', 'Áo khoác dài', '冬天我会穿厚大衣。', 'Dōngtiān wǒ huì chuān hòu dàyī', 'Mùa đông tôi sẽ mặc áo khoác dày.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Áo khoác dài","example":"冬天我会穿厚大衣。","example_pinyin":"/Dōngtiān wǒ huì chuān hòu dàyī/","example_meaning":"Mùa đông tôi sẽ mặc áo khoác dày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('大自然', 'dàzìrán', 'Thiên nhiên', '我们要保护大自然。', 'Wǒmen yào bǎohù dàzìrán', 'Chúng ta cần bảo vệ thiên nhiên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thiên nhiên","example":"我们要保护大自然。","example_pinyin":"/Wǒmen yào bǎohù dàzìrán/","example_meaning":"Chúng ta cần bảo vệ thiên nhiên.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('带', 'dài', 'Mang, đem theo', '请记得带雨伞。', 'Qǐng jìdé dài yǔsǎn', 'Xin nhớ mang theo ô.', 'Động từ', '[{"pos":"Động từ","meaning":"Mang, đem theo","example":"请记得带雨伞。","example_pinyin":"/Qǐng jìdé dài yǔsǎn/","example_meaning":"Xin nhớ mang theo ô.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('带来', 'dàilái', 'Mang đến', '汉语给我带来了很多工作机会。', 'Hànyǔ gěi wǒ dài lái le hěnduō gōngzuò jīhuì', 'Tiếng Trung mang lại cho tôi rất nhiều cơ hội việc làm.', 'Động từ', '[{"pos":"Động từ","meaning":"Mang đến","example":"汉语给我带来了很多工作机会。","example_pinyin":"/Hànyǔ gěi wǒ dài lái le hěnduō gōngzuò jīhuì/","example_meaning":"Tiếng Trung mang lại cho tôi rất nhiều cơ hội việc làm.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('单位', 'dānwèi', 'Đơn vị (công tác)', '他的工作单位在市中心。', 'Tā de gōngzuò dānwèi zài shì zhōngxīn', 'Đơn vị công tác của anh ấy ở trung tâm thành phố.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đơn vị (công tác)","example":"他的工作单位在市中心。","example_pinyin":"/Tā de gōngzuò dānwèi zài shì zhōngxīn/","example_meaning":"Đơn vị công tác của anh ấy ở trung tâm thành phố.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('但', 'dàn', 'Nhưng', '我想去旅行，但是没有时间。', 'Wǒ xiǎng qù lǚxíng, dànshì méiyǒu shíjiān', 'Tôi muốn đi du lịch, nhưng không có thời gian.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Nhưng","example":"我想去旅行，但是没有时间。","example_pinyin":"/Wǒ xiǎng qù lǚxíng, dànshì méiyǒu shíjiān/","example_meaning":"Tôi muốn đi du lịch, nhưng không có thời gian.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('但是', 'dànshì', 'Nhưng mà', NULL, NULL, NULL, 'Liên từ', '[{"pos":"Liên từ","meaning":"Nhưng mà","example":"","example_pinyin":"","example_meaning":"","is_approved":false}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('蛋', 'dàn', 'Trứng', '我喜欢吃鸡蛋。', 'Wǒ xǐhuan chī jīdàn', 'Tôi thích ăn trứng gà.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trứng","example":"我喜欢吃鸡蛋。","example_pinyin":"/Wǒ xǐhuan chī jīdàn/","example_meaning":"Tôi thích ăn trứng gà.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('当', 'dāng', 'Làm', '他长大后想当医生。', 'Tā zhǎng dà hòu xiǎng dāng yīshēng', 'Lớn lên anh ấy muốn trở thành bác sĩ.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm","example":"他长大后想当医生。","example_pinyin":"/Tā zhǎng dà hòu xiǎng dāng yīshēng/","example_meaning":"Lớn lên anh ấy muốn trở thành bác sĩ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('当时', 'dāngshí', 'Lúc đó, thời điểm đó', '当时我也没想那么多。', 'Dāngshí wǒ yě méi xiǎng nàme duō', 'Lức đó, tôi cũng không có nghĩ nhiều đến vậy.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Lúc đó, thời điểm đó","example":"当时我也没想那么多。","example_pinyin":"/Dāngshí wǒ yě méi xiǎng nàme duō/","example_meaning":"Lức đó, tôi cũng không có nghĩ nhiều đến vậy.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('倒', 'dǎo', 'Ngã, đổ', '风太大，把树都吹倒了。', 'Fēng tài dà, bǎ shù dōu chuī dǎo le', 'Gió quá mạnh, làm cây đổ hết.', 'Động từ', '[{"pos":"Động từ","meaning":"Ngã, đổ","example":"风太大，把树都吹倒了。","example_pinyin":"/Fēng tài dà, bǎ shù dōu chuī dǎo le/","example_meaning":"Gió quá mạnh, làm cây đổ hết.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('到处', 'dàochù', 'Khắp nơi', '公园里到处都是花。', 'Gōngyuán lǐ dàochù dōu shì huā', 'Trong công viên, hoa ở khắp nơi.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Khắp nơi","example":"公园里到处都是花。","example_pinyin":"/Gōngyuán lǐ dàochù dōu shì huā/","example_meaning":"Trong công viên, hoa ở khắp nơi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('倒', 'dào', 'Ngã, đổ, lật đổ', '火车到回去了。', 'Huǒchē dào huíqù le', 'Chuyến tàu đã quay trở lại.', 'Động từ', '[{"pos":"Động từ","meaning":"Ngã, đổ, lật đổ","example":"火车到回去了。","example_pinyin":"/Huǒchē dào huíqù le/","example_meaning":"Chuyến tàu đã quay trở lại.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('道', 'dào', 'Con đường, lối đi', '这条道路很宽。', 'Zhè tiáo dàolù hěn kuān', 'Con đường này rất rộng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Con đường, lối đi","example":"这条道路很宽。","example_pinyin":"/Zhè tiáo dàolù hěn kuān/","example_meaning":"Con đường này rất rộng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('道理', 'dàolǐ', 'Đạo lý, lý lẽ', '他说的话很有道理。', 'Tā shuō de huà hěn yǒu dàolǐ', 'Những lời anh ấy nói rất có lý.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đạo lý, lý lẽ","example":"他说的话很有道理。","example_pinyin":"/Tā shuō de huà hěn yǒu dàolǐ/","example_meaning":"Những lời anh ấy nói rất có lý.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('得', 'dé', 'Được, đạt được', '他得了第一名。', 'Tā dé le dì yī míng', 'Anh ấy đạt giải nhất.', 'Động từ', '[{"pos":"Động từ","meaning":"Được, đạt được","example":"他得了第一名。","example_pinyin":"/Tā dé le dì yī míng/","example_meaning":"Anh ấy đạt giải nhất.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('得出', 'déchū', 'Rút ra (kết luận)', '我们可以从实验中得出结论。', 'Wǒmen kěyǐ cóng shíyàn zhōng déchū jiélùn', 'Chúng ta có thể rút ra kết luận từ thí nghiệm.', 'Động từ', '[{"pos":"Động từ","meaning":"Rút ra (kết luận)","example":"我们可以从实验中得出结论。","example_pinyin":"/Wǒmen kěyǐ cóng shíyàn zhōng déchū jiélùn/","example_meaning":"Chúng ta có thể rút ra kết luận từ thí nghiệm.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('的话', 'dehuà', 'Nếu', '如果有问题的话，请联系我。', 'Rúguǒ yǒu wèntí dehuà, qǐng liánxì wǒ.', 'Nếu có vấn đề, xin hãy liên hệ với tôi.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Nếu","example":"如果有问题的话，请联系我。","example_pinyin":"/Rúguǒ yǒu wèntí dehuà, qǐng liánxì wǒ./","example_meaning":"Nếu có vấn đề, xin hãy liên hệ với tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('得', 'de', 'Được, có thể, đến', '他跑得很快。', 'Tā pǎo de hěn kuài', 'Anh ấy chạy rất nhanh.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Được, có thể, đến","example":"他跑得很快。","example_pinyin":"/Tā pǎo de hěn kuài/","example_meaning":"Anh ấy chạy rất nhanh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('灯', 'dēng', 'Đèn', '教室里的灯开着呢。', 'Jiàoshì lǐ de dēng kāi zhe ne', 'Đèn trong lớp vẫn còn bật.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đèn","example":"教室里的灯开着呢。","example_pinyin":"/Jiàoshì lǐ de dēng kāi zhe ne/","example_meaning":"Đèn trong lớp vẫn còn bật.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('等', 'děng', 'Vân vân; v.v (liệt kê)', '我喜欢吃苹果、香蕉、橘子等等。', 'Wǒ xǐhuān chī píngguǒ, xiāngjiāo, júzi děng děng', 'Tôi thích ăn táo, chuối, cam, v.v.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Vân vân; v.v (liệt kê)","example":"我喜欢吃苹果、香蕉、橘子等等。","example_pinyin":"/Wǒ xǐhuān chī píngguǒ, xiāngjiāo, júzi děng děng/","example_meaning":"Tôi thích ăn táo, chuối, cam, v.v.","is_approved":true},{"pos":"Danh từ","meaning":"Bậc, hạng, cấp, thứ tự","example":"他喜欢坐一等座。","example_pinyin":"/Tā xǐhuān zuò yī děng zuò/","example_meaning":"Anh ấy thích ngồi khoang hạng nhất.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('等到', 'děngdào', 'Đợi đến lúc', '等到明天，我们再决定吧。', 'Děngdào míngtiān, wǒmen zài juédìng ba', 'Đợi đến ngày mai, chúng ta hãy quyết định.', 'Động từ', '[{"pos":"Động từ","meaning":"Đợi đến lúc","example":"等到明天，我们再决定吧。","example_pinyin":"/Děngdào míngtiān, wǒmen zài juédìng ba/","example_meaning":"Đợi đến ngày mai, chúng ta hãy quyết định.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('等于', 'děngyú', 'Bằng với, tương đương', '二加二等于四。', 'Èr jiā èr děngyú sì', 'Hai cộng hai bằng bốn.', 'Động từ', '[{"pos":"Động từ","meaning":"Bằng với, tương đương","example":"二加二等于四。","example_pinyin":"/Èr jiā èr děngyú sì/","example_meaning":"Hai cộng hai bằng bốn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('低', 'dī', 'Thấp', '这里的温度很低。', 'Zhèlǐ de wēndù hěn dī', 'Nhiệt độ ở đây rất thấp.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Thấp","example":"这里的温度很低。","example_pinyin":"/Zhèlǐ de wēndù hěn dī/","example_meaning":"Nhiệt độ ở đây rất thấp.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地球', 'dìqiú', 'Trái đất', '地球是我们的家园。', 'Dìqiú shì wǒmen de jiāyuán', 'Trái đất là ngôi nhà của chúng ta.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trái đất","example":"地球是我们的家园。","example_pinyin":"/Dìqiú shì wǒmen de jiāyuán/","example_meaning":"Trái đất là ngôi nhà của chúng ta.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地铁', 'dìtiě', 'Tàu điện ngầm', '我每天坐地铁上班。', 'Wǒ měitiān zuò dìtiě shàngbān', 'Tôi đi làm bằng tàu điện ngầm mỗi ngày.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tàu điện ngầm","example":"我每天坐地铁上班。","example_pinyin":"/Wǒ měitiān zuò dìtiě shàngbān/","example_meaning":"Tôi đi làm bằng tàu điện ngầm mỗi ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('地铁站', 'dìtiězhàn', 'Ga tàu điện ngầm', '最近的地铁站在哪里？', 'Zuìjìn de dìtiězhàn zài nǎlǐ', 'Ga tàu điện ngầm gần nhất ở đâu?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ga tàu điện ngầm","example":"最近的地铁站在哪里？","example_pinyin":"/Zuìjìn de dìtiězhàn zài nǎlǐ/","example_meaning":"Ga tàu điện ngầm gần nhất ở đâu?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('点头', 'diǎn tóu', 'Gật đầu', '她微笑着点头。', 'Tā wēixiào zhe diǎn tóu', 'Cô ấy mỉm cười và gật đầu.', 'Động từ', '[{"pos":"Động từ","meaning":"Gật đầu","example":"她微笑着点头。","example_pinyin":"/Tā wēixiào zhe diǎn tóu/","example_meaning":"Cô ấy mỉm cười và gật đầu.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('店', 'diàn', 'Cửa hàng', '这家店很有名。', 'Zhè jiā diàn hěn yǒumíng', 'Cửa hàng này rất nổi tiếng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cửa hàng","example":"这家店很有名。","example_pinyin":"/Zhè jiā diàn hěn yǒumíng/","example_meaning":"Cửa hàng này rất nổi tiếng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('掉', 'diào', 'Rơi, rớt', '我的手机掉了。', 'Wǒ de shǒujī diào le', 'Điện thoại của tôi bị rơi mất rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Rơi, rớt","example":"我的手机掉了。","example_pinyin":"/Wǒ de shǒujī diào le/","example_meaning":"Điện thoại của tôi bị rơi mất rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('东北', 'dōngběi', 'Đông bắc', '他们都是东北人。', 'Tāmen dōu shì dōngběi rén', 'Họ đều người Đông Bắc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đông bắc","example":"他们都是东北人。","example_pinyin":"/Tāmen dōu shì dōngběi rén/","example_meaning":"Họ đều người Đông Bắc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('东方', 'dōngfāng', 'Phương đông, hướng đông', '太阳从东方升起。', 'Tàiyáng cóng dōngfāng shēngqǐ', 'Mặt trời mọc từ hướng Đông.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phương đông, hướng đông","example":"太阳从东方升起。","example_pinyin":"/Tàiyáng cóng dōngfāng shēngqǐ/","example_meaning":"Mặt trời mọc từ hướng Đông.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('东南', 'dōngnán', 'Đông nam', '我家在东南方向。', 'Wǒ jiā zài dōngnán fāngxiàng', 'Nhà tôi ở hướng Đông Nam.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đông nam","example":"我家在东南方向。","example_pinyin":"/Wǒ jiā zài dōngnán fāngxiàng/","example_meaning":"Nhà tôi ở hướng Đông Nam.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('冬天', 'dōngtiān', 'Mùa đông', '冬天很冷，你多穿点衣服。', 'Dōngtiān hěn lěng, nǐ duō chuān diǎn yīfu', 'Mùa đông rất lạnh, bạn nên mặc nhiều quần áo vào.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mùa đông","example":"冬天很冷，你多穿点衣服。","example_pinyin":"/Dōngtiān hěn lěng, nǐ duō chuān diǎn yīfu/","example_meaning":"Mùa đông rất lạnh, bạn nên mặc nhiều quần áo vào.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('懂', 'dǒng', 'Hiểu', '我不懂这是什么意思。', 'Wǒ bù dǒng zhè shì shénme yìsi', 'Tôi không hiểu cái này có ý nghĩa gì.', 'Động từ', '[{"pos":"Động từ","meaning":"Hiểu","example":"我不懂这是什么意思。","example_pinyin":"/Wǒ bù dǒng zhè shì shénme yìsi/","example_meaning":"Tôi không hiểu cái này có ý nghĩa gì.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('懂得', 'dǒngdé', 'Hiểu rõ, biết', '她终于懂得怎么去珍惜时间。', 'Tā zhōngyú dǒngdé zěnme qù zhēnxī shíjiān', 'Cuối cùng cô ấy đã học được cách trân trọng thời gian.', 'Động từ', '[{"pos":"Động từ","meaning":"Hiểu rõ, biết","example":"她终于懂得怎么去珍惜时间。","example_pinyin":"/Tā zhōngyú dǒngdé zěnme qù zhēnxī shíjiān/","example_meaning":"Cuối cùng cô ấy đã học được cách trân trọng thời gian.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('动物', 'dòngwù', 'Động vật', '你喜欢什么动物？', 'Nǐ xǐhuān shénme dòng wù', 'Bạn thích động vật nào?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Động vật","example":"你喜欢什么动物？","example_pinyin":"/Nǐ xǐhuān shénme dòng wù/","example_meaning":"Bạn thích động vật nào?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('动物园', 'dòngwùyuán', 'Sở thú', '周末我们去动物园吧。', 'Zhōumò wǒmen qù dòngwùyuán ba', 'Cuối tuần chúng ta đi sở thú nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sở thú","example":"周末我们去动物园吧。","example_pinyin":"/Zhōumò wǒmen qù dòngwùyuán ba/","example_meaning":"Cuối tuần chúng ta đi sở thú nhé.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('读音', 'dúyīn', 'Cách phát âm', '这个字的读音是什么？', 'Zhège zì de dúyīn shì shénme', 'Cách phát âm của chữ này là gì?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cách phát âm","example":"这个字的读音是什么？","example_pinyin":"/Zhège zì de dúyīn shì shénme/","example_meaning":"Cách phát âm của chữ này là gì?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('度', 'dù', 'Độ, mức độ', '今天气温三十度。', 'Jīntiān qìwēn sānshí dù', 'Hôm nay nhiệt độ là 30 độ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Độ, mức độ","example":"今天气温三十度。","example_pinyin":"/Jīntiān qìwēn sānshí dù/","example_meaning":"Hôm nay nhiệt độ là 30 độ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('短', 'duǎn', 'Ngắn', '这条裤子太短了。', 'Zhè tiáo kùzi tài duǎn le', 'Chiếc quần này quá ngắn.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Ngắn","example":"这条裤子太短了。","example_pinyin":"/Zhè tiáo kùzi tài duǎn le/","example_meaning":"Chiếc quần này quá ngắn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('短信', 'duǎnxìn', 'Tin nhắn', '你可以给我发短信。', 'Nǐ kěyǐ gěi wǒ fā duǎnxìn', 'Bạn có thể gửi tin nhắn cho tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tin nhắn","example":"你可以给我发短信。","example_pinyin":"/Nǐ kěyǐ gěi wǒ fā duǎnxìn/","example_meaning":"Bạn có thể gửi tin nhắn cho tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('段', 'duàn', 'Đoạn, khúc', '请读这段话。', 'Qǐng dú zhè duàn huà', 'Vui lòng đọc đoạn văn này.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đoạn, khúc","example":"请读这段话。","example_pinyin":"/Qǐng dú zhè duàn huà/","example_meaning":"Vui lòng đọc đoạn văn này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('队', 'duì', 'Đội, nhóm', '他是我们队的成员。', 'Tā shì wǒmen duì de chéngyuán', 'Anh ấy là thành viên trong nhóm của chúng tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đội, nhóm","example":"他是我们队的成员。","example_pinyin":"/Tā shì wǒmen duì de chéngyuán/","example_meaning":"Anh ấy là thành viên trong nhóm của chúng tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('队长', 'duìzhǎng', 'Đội trưởng', '他是足球队的队长。', 'Tā shì zúqiú duì de duìzhǎng', 'Anh ấy là đội trưởng đội bóng đá.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đội trưởng","example":"他是足球队的队长。","example_pinyin":"/Tā shì zúqiú duì de duìzhǎng/","example_meaning":"Anh ấy là đội trưởng đội bóng đá.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('对', 'duì', 'Về, đối với', '他对这个工作很有信心。', 'Tā duì zhège gōngzuò hěn yǒu xìnxīn', 'Anh ấy đối với công việc này rất có tự tin.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Về, đối với","example":"他对这个工作很有信心。","example_pinyin":"/Tā duì zhège gōngzuò hěn yǒu xìnxīn/","example_meaning":"Anh ấy đối với công việc này rất có tự tin.","is_approved":true},{"pos":"Động từ","meaning":"Đối xử, đối đãi","example":"老师对学生很好。","example_pinyin":"/Lǎoshī duì xuéshēng hěn hǎo/","example_meaning":"Giáo viên rất tốt với học sinh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('对话', 'duìhuà', 'Đối thoại', '这些句子都是日常的对话。', 'Zhèxiē jùzǐ dōu shì rìcháng de duìhuà', 'Những câu này được lấy từ các cuộc trò chuyện hàng ngày.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đối thoại","example":"这些句子都是日常的对话。","example_pinyin":"/Zhèxiē jùzǐ dōu shì rìcháng de duìhuà/","example_meaning":"Những câu này được lấy từ các cuộc trò chuyện hàng ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('对面', 'duìmiàn', 'Đối diện', '银行在学校对面。', 'Yínháng zài xuéxiào duìmiàn', 'Ngân hàng ở đối diện trường học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đối diện","example":"银行在学校对面。","example_pinyin":"/Yínháng zài xuéxiào duìmiàn/","example_meaning":"Ngân hàng ở đối diện trường học.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多', 'duō', 'Nhiều, nhiều hơn', '今天比昨天多了几个人。', 'Jīntiān bǐ zuótiān duō le jǐ gèrén', 'Hôm nay có nhiều người hơn hôm qua một chút.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Nhiều, nhiều hơn","example":"今天比昨天多了几个人。","example_pinyin":"/Jīntiān bǐ zuótiān duō le jǐ gèrén/","example_meaning":"Hôm nay có nhiều người hơn hôm qua một chút.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多久', 'duōjiǔ', 'Bao lâu', '你学汉语学了多久了？', 'Nǐ xué hànyǔ xué le duōjiǔ le', 'Bạn học tiếng Trung bao lâu rồi?', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Bao lâu","example":"你学汉语学了多久了？","example_pinyin":"/Nǐ xué hànyǔ xué le duōjiǔ le/","example_meaning":"Bạn học tiếng Trung bao lâu rồi?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多么', 'duōme', 'Biết bao, bao nhiêu', '这个地方多么漂亮啊！', 'Zhè ge dìfāng duōme piàoliang a', 'Nơi đây đẹp biết bao!', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Biết bao, bao nhiêu","example":"这个地方多么漂亮啊！","example_pinyin":"/Zhè ge dìfāng duōme piàoliang a/","example_meaning":"Nơi đây đẹp biết bao!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多数', 'duōshù', 'Đa số, số đông', '大多数人都喜欢去旅行。', 'Dà duōshù rén dōu xǐhuān qù lǚxíng', 'Đa số mọi người đều thích đi du lịch.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đa số, số đông","example":"大多数人都喜欢去旅行。","example_pinyin":"/Dà duōshù rén dōu xǐhuān qù lǚxíng/","example_meaning":"Đa số mọi người đều thích đi du lịch.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('多云', 'duōyún', 'Nhiều mây', '我喜欢多云的天空。', 'Wǒ xǐhuan duōyún de tiānkōng', 'Tôi thích bầu trời nhiều mây.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nhiều mây","example":"我喜欢多云的天空。","example_pinyin":"/Wǒ xǐhuan duōyún de tiānkōng/","example_meaning":"Tôi thích bầu trời nhiều mây.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('而且', 'érqiě', 'Hơn nữa, mà còn', '她不仅聪明，而且很努力。', 'Tā bùjǐn cōngmíng, érqiě hěn nǔlì', 'Cô ấy không chỉ thông minh, hơn nữa còn rất chăm chỉ.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Hơn nữa, mà còn","example":"她不仅聪明，而且很努力。","example_pinyin":"/Tā bùjǐn cōngmíng, érqiě hěn nǔlì/","example_meaning":"Cô ấy không chỉ thông minh, hơn nữa còn rất chăm chỉ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('发', 'fā', 'Phát ra, gửi đi', '今天发货，明天送达。', 'Jīntiān fā huò, míngtiān sòng dá', 'Gửi hàng hôm nay, giao hàng ngày mai.', 'Động từ', '[{"pos":"Động từ","meaning":"Phát ra, gửi đi","example":"今天发货，明天送达。","example_pinyin":"/Jīntiān fā huò, míngtiān sòng dá/","example_meaning":"Gửi hàng hôm nay, giao hàng ngày mai.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('发现', 'fāxiàn', 'Phát hiện', '我发现了一个很美的地方。', 'Wǒ fāxiàn le yīgè hěn měi dì dìfāng', 'Tôi phát hiện anh ấy không có ở nhà.', 'Động từ', '[{"pos":"Động từ","meaning":"Phát hiện","example":"我发现了一个很美的地方。","example_pinyin":"/Wǒ fāxiàn le yīgè hěn měi dì dìfāng/","example_meaning":"Tôi phát hiện anh ấy không có ở nhà.","is_approved":true}]', 'HSK2');
