INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('方法', 'fāngfǎ', 'Phương pháp', '这个方法很好。', 'Zhège fāngfǎ hěn hǎo', 'Phương pháp này rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phương pháp","example":"这个方法很好。","example_pinyin":"/Zhège fāngfǎ hěn hǎo/","example_meaning":"Phương pháp này rất tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('方面', 'fāngmiàn', 'Phương diện, khía cạnh', '他在数学方面很有天赋。', 'Tā zài shùxué fāngmiàn hěn yǒu tiānfù', 'Anh ấy có năng khiếu về toán học.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phương diện, khía cạnh","example":"他在数学方面很有天赋。","example_pinyin":"/Tā zài shùxué fāngmiàn hěn yǒu tiānfù/","example_meaning":"Anh ấy có năng khiếu về toán học.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('方向', 'fāngxiàng', 'Phương hướng', '你走错方向了。', 'Nǐ zǒu cuò fāngxiàng le', 'Bạn đi sai hướng rồi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phương hướng","example":"你走错方向了。","example_pinyin":"/Nǐ zǒu cuò fāngxiàng le/","example_meaning":"Bạn đi sai hướng rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('放下', 'fàngxià', 'Đặt xuống', '请放下手中的笔。', 'Qǐng fàngxià shǒuzhōng de bǐ', 'Hãy đặt bút xuống.', 'Động từ', '[{"pos":"Động từ","meaning":"Đặt xuống","example":"请放下手中的笔。","example_pinyin":"/Qǐng fàngxià shǒuzhōng de bǐ/","example_meaning":"Hãy đặt bút xuống.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('放心', 'fàngxīn', 'Yên tâm', '放心吧，我会帮你的。', 'Fàngxīn ba, wǒ huì bāng nǐ de', 'Hãy yên tâm, tôi sẽ giúp bạn.', 'Động từ', '[{"pos":"Động từ","meaning":"Yên tâm","example":"放心吧，我会帮你的。","example_pinyin":"/Fàngxīn ba, wǒ huì bāng nǐ de/","example_meaning":"Hãy yên tâm, tôi sẽ giúp bạn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('分开', 'fēnkāi', 'Tách ra, phân ly', '我们俩不会分开的。', 'Wǒmen liǎ bù huì fēnkāi de', 'Hai chúng ta sẽ không xa nhau đâu.', 'Động từ', '[{"pos":"Động từ","meaning":"Tách ra, phân ly","example":"我们俩不会分开的。","example_pinyin":"/Wǒmen liǎ bù huì fēnkāi de/","example_meaning":"Hai chúng ta sẽ không xa nhau đâu.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('分数', 'fēnshù', 'Điểm số', '这次考试的分数很高。', 'Zhè cì kǎoshì de fēnshù hěn gāo', 'Điểm kỳ thi lần này rất cao.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Điểm số","example":"这次考试的分数很高。","example_pinyin":"/Zhè cì kǎoshì de fēnshù hěn gāo/","example_meaning":"Điểm kỳ thi lần này rất cao.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('分钟', 'fēnzhōng', 'Phút', '休息五分钟吧。', 'Xiūxí wǔ fēnzhōng ba', 'Nghỉ ngơi năm phút đi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Phút","example":"休息五分钟吧。","example_pinyin":"/Xiūxí wǔ fēnzhōng ba/","example_meaning":"Nghỉ ngơi năm phút đi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('份', 'fèn', 'Phần, suất', '我点了一份炒饭。', 'Wǒ diǎnle yī fèn chǎofàn', 'Tôi đã gọi một phần cơm rang.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Phần, suất","example":"我点了一份炒饭。","example_pinyin":"/Wǒ diǎnle yī fèn chǎofàn/","example_meaning":"Tôi đã gọi một phần cơm rang.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('封', 'fēng', 'Bức, phong (thư)', '他给我写了一封信。', 'Tā gěi wǒ xiěle yī fēng xìn', 'Anh ấy đã viết cho tôi một bức thư.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Bức, phong (thư)","example":"他给我写了一封信。","example_pinyin":"/Tā gěi wǒ xiěle yī fēng xìn/","example_meaning":"Anh ấy đã viết cho tôi một bức thư.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('服务', 'fúwù', 'Sự phục vụ, dịch vụ', '这家餐厅的服务很好。', 'Zhè jiā cāntīng de fúwù hěn hǎo', 'Dịch vụ của nhà hàng này rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sự phục vụ, dịch vụ","example":"这家餐厅的服务很好。","example_pinyin":"/Zhè jiā cāntīng de fúwù hěn hǎo/","example_meaning":"Dịch vụ của nhà hàng này rất tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('复习', 'fùxí', 'Ôn tập', '考试前要认真复习。', 'Kǎoshì qián yào rènzhēn fùxí', 'Trước kỳ thi phải ôn tập chăm chỉ.', 'Động từ', '[{"pos":"Động từ","meaning":"Ôn tập","example":"考试前要认真复习。","example_pinyin":"/Kǎoshì qián yào rènzhēn fùxí/","example_meaning":"Trước kỳ thi phải ôn tập chăm chỉ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('该', 'gāi', 'Nên, cần', '你该去休息了。', 'Nǐ gāi qù xiūxi le', 'Bạn nên đi nghỉ ngơi rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Nên, cần","example":"你该去休息了。","example_pinyin":"/Nǐ gāi qù xiūxi le/","example_meaning":"Bạn nên đi nghỉ ngơi rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('改', 'gǎi', 'Sửa, thay đổi', '他决定改掉这个坏习惯。', 'Tā juédìng gǎi diào zhè gè huài xíguàn', 'Anh ấy quyết định sửa thói quen xấu này.', 'Động từ', '[{"pos":"Động từ","meaning":"Sửa, thay đổi","example":"他决定改掉这个坏习惯。","example_pinyin":"/Tā juédìng gǎi diào zhè gè huài xíguàn/","example_meaning":"Anh ấy quyết định sửa thói quen xấu này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('改变', 'gǎibiàn', 'Thay đổi', '他有了很大的改变。', 'Tā yǒule hěn dà de gǎibiàn', 'Anh ấy đã thay đổi rất nhiều.', 'Động từ', '[{"pos":"Động từ","meaning":"Thay đổi","example":"他有了很大的改变。","example_pinyin":"/Tā yǒule hěn dà de gǎibiàn/","example_meaning":"Anh ấy đã thay đổi rất nhiều.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干杯', 'gānbēi', 'Cạn ly', '为我们的友谊干杯！', 'Wèi wǒmen de yǒuyì gānbēi', 'Cạn ly vì tình bạn của chúng ta!', 'Động từ', '[{"pos":"Động từ","meaning":"Cạn ly","example":"为我们的友谊干杯！","example_pinyin":"/Wèi wǒmen de yǒuyì gānbēi/","example_meaning":"Cạn ly vì tình bạn của chúng ta!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('感到', 'gǎndào', 'Cảm thấy', '我感到很高兴。', 'Wǒ gǎndào hěn gāoxìng', 'Tôi cảm thấy rất vui.', 'Động từ', '[{"pos":"Động từ","meaning":"Cảm thấy","example":"我感到很高兴。","example_pinyin":"/Wǒ gǎndào hěn gāoxìng/","example_meaning":"Tôi cảm thấy rất vui.","is_approved":true}]', 'HSK2');
