INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('感觉', 'gǎnjué', 'Cảm giác, cảm thấy', '我感觉有点儿冷。', 'Wǒ gǎnjué yǒudiǎnr lěng', 'Tôi cảm thấy có chút lạnh.', 'Động từ', '[{"pos":"Động từ","meaning":"Cảm giác, cảm thấy","example":"我感觉有点儿冷。","example_pinyin":"/Wǒ gǎnjué yǒudiǎnr lěng/","example_meaning":"Tôi cảm thấy có chút lạnh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('感谢', 'gǎnxiè', 'Cảm ơn', '非常感谢你的帮助。', 'Fēicháng gǎnxiè nǐ de bāngzhù', 'Rất cảm ơn sự giúp đỡ của bạn.', 'Động từ', '[{"pos":"Động từ","meaning":"Cảm ơn","example":"非常感谢你的帮助。","example_pinyin":"/Fēicháng gǎnxiè nǐ de bāngzhù/","example_meaning":"Rất cảm ơn sự giúp đỡ của bạn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('干活儿', 'gànhuór', 'Làm việc', '他们正在干活儿。', 'Tāmen zhèngzài gàn huór', 'Họ đang làm việc.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm việc","example":"他们正在干活儿。","example_pinyin":"/Tāmen zhèngzài gàn huór/","example_meaning":"Họ đang làm việc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('刚', 'gāng', 'Vừa mới', '我刚到家。', 'Wǒ gāng dào jiā', 'Tôi vừa về đến nhà.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Vừa mới","example":"我刚到家。","example_pinyin":"/Wǒ gāng dào jiā/","example_meaning":"Tôi vừa về đến nhà.","is_approved":true}]', 'HSK2');
