INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('个子', 'gèzi', 'Vóc dáng, chiều cao', '他个子很高。', 'Tā gèzi hěn gāo', 'Anh ấy có dáng người cao ráo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Vóc dáng, chiều cao","example":"他个子很高。","example_pinyin":"/Tā gèzi hěn gāo/","example_meaning":"Anh ấy có dáng người cao ráo.","is_approved":true}]', 'HSK2');
