INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('狗', 'gǒu', 'Chó', '这只小狗很可爱。', 'Zhè zhī xiăo gǒu hěn kě’ài', 'Con chó này rất đáng yêu.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chó","example":"这只小狗很可爱。","example_pinyin":"/Zhè zhī xiăo gǒu hěn kě’ài/","example_meaning":"Con chó này rất đáng yêu.","is_approved":true}]', 'HSK2');
