INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('过去', 'guòqù', 'Quá khứ, đã qua', '过去的事情不要再想了。', 'Guòqù de shìqíng bú yào zài xiǎng le', 'Những chuyện đã qua đừng nghĩ nữa.', 'Động từ', '[{"pos":"Động từ","meaning":"Quá khứ, đã qua","example":"过去的事情不要再想了。","example_pinyin":"/Guòqù de shìqíng bú yào zài xiǎng le/","example_meaning":"Những chuyện đã qua đừng nghĩ nữa.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('过', 'guo', 'Qua, đi qua', '我们昨天去过那个地方。', 'Wǒmen zuótiān qù guo nàge dìfāng', 'Hôm qua chúng tôi đã từng đến nơi đó.', 'Trợ từ', '[{"pos":"Trợ từ","meaning":"Qua, đi qua","example":"我们昨天去过那个地方。","example_pinyin":"/Wǒmen zuótiān qù guo nàge dìfāng/","example_meaning":"Hôm qua chúng tôi đã từng đến nơi đó.","is_approved":true}]', 'HSK2');
