INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('讲', 'jiǎng', 'Nói, giảng', '老师讲得很清楚。', 'Lǎoshī jiǎng de hěn qīngchǔ', 'Thầy giáo giảng rất rõ ràng.', 'Động từ', '[{"pos":"Động từ","meaning":"Nói, giảng","example":"老师讲得很清楚。","example_pinyin":"/Lǎoshī jiǎng de hěn qīngchǔ/","example_meaning":"Thầy giáo giảng rất rõ ràng.","is_approved":true}]', 'HSK2');
