INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('节日', 'jiérì', 'Ngày lễ, ngày hội', '春节是中国的重要节日。', 'Chūnjié shì zhōngguó de zhòngyào jiérì', 'Tết Nguyên đán là một lễ hội quan trọng ở Trung Quốc.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ngày lễ, ngày hội","example":"春节是中国的重要节日。","example_pinyin":"/Chūnjié shì zhōngguó de zhòngyào jiérì/","example_meaning":"Tết Nguyên đán là một lễ hội quan trọng ở Trung Quốc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('结果', 'jiéguǒ', 'Kết quả', '我们等了很久，结果还没出来。', 'Wǒmen děng le hěn jiǔ, jiéguǒ hái méi chūlái', 'Chúng tôi đợi rất lâu, kết quả vẫn chưa có.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Kết quả","example":"我们等了很久，结果还没出来。","example_pinyin":"/Wǒmen děng le hěn jiǔ, jiéguǒ hái méi chūlái/","example_meaning":"Chúng tôi đợi rất lâu, kết quả vẫn chưa có.","is_approved":true}]', 'HSK2');
