INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('斤', 'jìn', 'Cân', '我买了两斤苹果。', 'Wǒ mǎi le liǎng jīn píngguǒ', 'Tôi mua một cân táo.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Cân","example":"我买了两斤苹果。","example_pinyin":"/Wǒ mǎi le liǎng jīn píngguǒ/","example_meaning":"Tôi mua một cân táo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('今后', 'jīnhòu', 'Từ nay về sau', '今后我要努力学汉语。', 'Jīnhòu wǒ yào nǔlì xué hànyǔ', 'Từ nay về sau tôi sẽ cố gắng học tiếng Trung.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Từ nay về sau","example":"今后我要努力学汉语。","example_pinyin":"/Jīnhòu wǒ yào nǔlì xué hànyǔ/","example_meaning":"Từ nay về sau tôi sẽ cố gắng học tiếng Trung.","is_approved":true}]', 'HSK2');
