INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('经过', 'jīngguò', 'Đi qua, trải qua', '经过商店时，他买了一些水果。', 'Jīngguò shāngdiàn shí tā mǎi le yīxiē shuǐguǒ', 'Khi đi qua cửa hàng, anh ấy mua một ít trái cây.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi qua, trải qua","example":"经过商店时，他买了一些水果。","example_pinyin":"/Jīngguò shāngdiàn shí tā mǎi le yīxiē shuǐguǒ/","example_meaning":"Khi đi qua cửa hàng, anh ấy mua một ít trái cây.","is_approved":true}]', 'HSK2');
