INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('酒', 'jiǔ', 'Rượu', '我不喝酒。', 'Wǒ bù hē jiǔ', 'Tôi không uống rượu.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Rượu","example":"我不喝酒。","example_pinyin":"/Wǒ bù hē jiǔ/","example_meaning":"Tôi không uống rượu.","is_approved":true}]', 'HSK2');
