INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('来自', 'láizì', 'Đến từ, xuất phát từ', '他来自中国。', 'Tā láizì Zhōngguó', 'Anh ấy đến từ Trung Quốc.', 'Động từ', '[{"pos":"Động từ","meaning":"Đến từ, xuất phát từ","example":"他来自中国。","example_pinyin":"/Tā láizì Zhōngguó/","example_meaning":"Anh ấy đến từ Trung Quốc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('蓝', 'lán', 'Xanh', '今天的天空很蓝。', 'Jīntiān de tiānkōng hěn lán', 'Bầu trời hôm nay rất xanh.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Xanh","example":"今天的天空很蓝。","example_pinyin":"/Jīntiān de tiānkōng hěn lán/","example_meaning":"Bầu trời hôm nay rất xanh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('蓝色', 'lánsè', 'Màu xanh lam', '我喜欢蓝色的衣服。', 'Wǒ xǐhuān lánsè de yīfu', 'Tôi thích quần áo màu xanh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Màu xanh lam","example":"我喜欢蓝色的衣服。","example_pinyin":"/Wǒ xǐhuān lánsè de yīfu/","example_meaning":"Tôi thích quần áo màu xanh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('篮球', 'lánqiú', 'Bóng rổ', '他的篮球打得很好。', 'Tā de lánqiú dǎ de hěn hǎo', 'Anh ấy chơi bóng rổ rất giỏi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bóng rổ","example":"他的篮球打得很好。","example_pinyin":"/Tā de lánqiú dǎ de hěn hǎo/","example_meaning":"Anh ấy chơi bóng rổ rất giỏi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老', 'lǎo', 'Cũ, già', '我奶奶老了。', 'Wǒ nǎinai lǎo le', 'Bà tôi già rồi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Cũ, già","example":"我奶奶老了。","example_pinyin":"/Wǒ nǎinai lǎo le/","example_meaning":"Bà tôi già rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老 ( 老王 )', 'lǎo (Lǎo Wáng)', 'Ông (dùng trước họ người để gọi người lớn tuổi)', '老王是我的大学同学。', 'Lǎo wáng shì wǒ de dàxué tóngxué', 'Lão Vương là bạn cùng lớp đại học của tôi.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Ông (dùng trước họ người để gọi người lớn tuổi)","example":"老王是我的大学同学。","example_pinyin":"/Lǎo wáng shì wǒ de dàxué tóngxué/","example_meaning":"Lão Vương là bạn cùng lớp đại học của tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老年', 'lǎonián', 'Tuổi già, người già', '老年人喜欢喝茶。', 'Lǎonián rén xǐhuān hē chá', 'Người già thích uống trà.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tuổi già, người già","example":"老年人喜欢喝茶。","example_pinyin":"/Lǎonián rén xǐhuān hē chá/","example_meaning":"Người già thích uống trà.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老朋友', 'lǎo péngyou', 'Bạn cũ', '他是我的老朋友。', 'Tā shì wǒ de lǎo péngyou', 'Anh ấy là bạn cũ của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bạn cũ","example":"他是我的老朋友。","example_pinyin":"/Tā shì wǒ de lǎo péngyou/","example_meaning":"Anh ấy là bạn cũ của tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('老是', 'lǎoshì', 'Luôn luôn, lúc nào cũng', '他老是迟到。', 'Tā lǎoshì chídào', 'Anh ấy lúc nào cũng đến muộn.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Luôn luôn, lúc nào cũng","example":"他老是迟到。","example_pinyin":"/Tā lǎoshì chídào/","example_meaning":"Anh ấy lúc nào cũng đến muộn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('离', 'lí', 'Cách', '我家离学校很近。', 'Wǒ jiā lí xuéxiào hěn jìn', 'Nhà tôi cách trường rất gần.', 'Động từ', '[{"pos":"Động từ","meaning":"Cách","example":"我家离学校很近。","example_pinyin":"/Wǒ jiā lí xuéxiào hěn jìn/","example_meaning":"Nhà tôi cách trường rất gần.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('离开', 'líkāi', 'Rời khỏi, rời xa', '我明天要离开北京了。', 'Wǒ míngtiān yào líkāi Běijīng le', 'Ngày mai tôi sẽ phải rời khỏi Bắc Kinh rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Rời khỏi, rời xa","example":"我明天要离开北京了。","example_pinyin":"/Wǒ míngtiān yào líkāi Běijīng le/","example_meaning":"Ngày mai tôi sẽ phải rời khỏi Bắc Kinh rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('礼物', 'lǐwù', 'Quà, quà tặng', '这是送给你的礼物。', 'Zhè shì sòng gěi nǐ de lǐwù', 'Đây là món quà dành tặng bạn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Quà, quà tặng","example":"这是送给你的礼物。","example_pinyin":"/Zhè shì sòng gěi nǐ de lǐwù/","example_meaning":"Đây là món quà dành tặng bạn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('里头', 'lǐtou', 'Bên trong', '书在书柜里头。', 'Shū zài shūguì lǐtou', 'Quyển sách ở bên trong tủ sách.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên trong","example":"书在书柜里头。","example_pinyin":"/Shū zài shūguì lǐtou/","example_meaning":"Quyển sách ở bên trong tủ sách.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('理想', 'lǐxiǎng', 'Lý tưởng', '他是我的理想型。', 'Tā shì wǒ de lǐxiǎng xíng', 'Anh ấy là mẫu người lý tưởng của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Lý tưởng","example":"他是我的理想型。","example_pinyin":"/Tā shì wǒ de lǐxiǎng xíng/","example_meaning":"Anh ấy là mẫu người lý tưởng của tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('例如', 'lìrú', 'Ví dụ như', '我喜欢很多花,例如荷花、菊花、和玫瑰花。', 'Wǒ xǐhuān hěnduō huā, lìrú héhuā, júhuā, hé méiguī huā', 'Tôi thích nhiều loại hoa như hoa sen, hoa cúc và hoa hồng.', 'Động từ', '[{"pos":"Động từ","meaning":"Ví dụ như","example":"我喜欢很多花,例如荷花、菊花、和玫瑰花。","example_pinyin":"/Wǒ xǐhuān hěnduō huā, lìrú héhuā, júhuā, hé méiguī huā/","example_meaning":"Tôi thích nhiều loại hoa như hoa sen, hoa cúc và hoa hồng.","is_approved":true}]', 'HSK2');
