INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('练', 'liàn', 'Luyện tập', '他每天都练习写汉字。', 'Tā měitiān dū liànxí xiě hànzì', 'Anh ấy luyện viết chữ Hán mỗi ngày.', 'Động từ', '[{"pos":"Động từ","meaning":"Luyện tập","example":"他每天都练习写汉字。","example_pinyin":"/Tā měitiān dū liànxí xiě hànzì/","example_meaning":"Anh ấy luyện viết chữ Hán mỗi ngày.","is_approved":true}]', 'HSK2');
