INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('两', 'liǎng', 'Lạng (đơn vị đo trọng lượng)', '他买了五两花生米。', 'Tā mǎi le wǔ liǎng huāshēng mǐ', 'Anh ấy mua năm lạng đậu phộng.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Lạng (đơn vị đo trọng lượng)","example":"他买了五两花生米。","example_pinyin":"/Tā mǎi le wǔ liǎng huāshēng mǐ/","example_meaning":"Anh ấy mua năm lạng đậu phộng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('亮', 'liàng', 'Sáng', '这个房间很亮。', 'Zhège fángjiān hěn liàng', 'Căn phòng này rất sáng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Sáng","example":"这个房间很亮。","example_pinyin":"/Zhège fángjiān hěn liàng/","example_meaning":"Căn phòng này rất sáng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('辆', 'liàng', 'Chiếc (dùng cho xe cộ)', '他买了一辆新车。', 'Tā mǎile yí liàng xīn chē', 'Anh ấy đã mua một chiếc xe mới.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Chiếc (dùng cho xe cộ)","example":"他买了一辆新车。","example_pinyin":"/Tā mǎile yí liàng xīn chē/","example_meaning":"Anh ấy đã mua một chiếc xe mới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('零下', 'líng xià', 'Dưới không độ', '今天的气温降到了零下十度。', 'Jīntiān de qìwēn jiàng dàole língxià shí dù', 'Nhiệt độ hôm nay giảm xuống còn âm 10 độ C.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Dưới không độ","example":"今天的气温降到了零下十度。","example_pinyin":"/Jīntiān de qìwēn jiàng dàole língxià shí dù/","example_meaning":"Nhiệt độ hôm nay giảm xuống còn âm 10 độ C.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('留', 'liú', 'Lưu lại, ở lại', '他留在农村工作了。', 'Tā liúzài nóngcūn gōngzuò le', 'Anh ấy ở lại nông thôn làm việc.', 'Động từ', '[{"pos":"Động từ","meaning":"Lưu lại, ở lại","example":"他留在农村工作了。","example_pinyin":"/Tā liúzài nóngcūn gōngzuò le/","example_meaning":"Anh ấy ở lại nông thôn làm việc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('留下', 'liúxia', 'Để lại, lưu lại', '她留下了一封信。', 'Tā liúxià le yì fēng xìn', 'Cô ấy đã để lại một bức thư.', 'Động từ', '[{"pos":"Động từ","meaning":"Để lại, lưu lại","example":"她留下了一封信。","example_pinyin":"/Tā liúxià le yì fēng xìn/","example_meaning":"Cô ấy đã để lại một bức thư.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('留学生', 'liúxuéshēng', 'Du học sinh', '我是留学生。', 'Wǒ shì liúxuéshēng', 'Tôi là du học sinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Du học sinh","example":"我是留学生。","example_pinyin":"/Wǒ shì liúxuéshēng/","example_meaning":"Tôi là du học sinh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('流', 'liú', 'Chảy, đổ', '他的手指流血了。', 'Tā de shǒuzhǐ liúxiě le', 'Ngón tay của anh ấy bị chảy máu.', 'Động từ', '[{"pos":"Động từ","meaning":"Chảy, đổ","example":"他的手指流血了。","example_pinyin":"/Tā de shǒuzhǐ liúxiě le/","example_meaning":"Ngón tay của anh ấy bị chảy máu.","is_approved":true},{"pos":"Danh từ","meaning":"Dòng, luồng (chỉ người hoặc đồ vật)","example":"电流可以产生磁场。","example_pinyin":"/Diànliú kěyǐ chǎnshēng cíchǎng/","example_meaning":"Dòng điện có thể tạo ra từ trường.","is_approved":true},{"pos":"Lượng từ","meaning":"Lumen, quang thông (đơn vị của ánh sáng)","example":"这灯泡五百流。","example_pinyin":"/Zhè dēngpào wǔbǎi liú/","example_meaning":"Đây là bóng đèn năm mươi lumen.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('流利', 'liúlì', 'Lưu loát, trôi chảy', '他中文说得很流利。', 'Tā Zhōngwén shuō de hěn liúlì', 'Anh ấy nói tiếng Trung rất lưu loát.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Lưu loát, trôi chảy","example":"他中文说得很流利。","example_pinyin":"/Tā Zhōngwén shuō de hěn liúlì/","example_meaning":"Anh ấy nói tiếng Trung rất lưu loát.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('流行', 'liúxíng', 'Thịnh hành, phổ biến', '这部电影在流行全球。', 'Zhè bù diànyǐng zài liúxíng quánqiú', 'Bộ phim này đang phổ biến trên toàn cầu.', 'Động từ', '[{"pos":"Động từ","meaning":"Thịnh hành, phổ biến","example":"这部电影在流行全球。","example_pinyin":"/Zhè bù diànyǐng zài liúxíng quánqiú/","example_meaning":"Bộ phim này đang phổ biến trên toàn cầu.","is_approved":true},{"pos":"Tính từ","meaning":"Thịnh hành, phổ biến","example":"这种音乐现在很流行。","example_pinyin":"/Zhè zhǒng yīnyuè xiànzài hěn liúxíng/","example_meaning":"Thể loại âm nhạc này đang rất thịnh hành.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('路边', 'lù biān', 'Ven đường', '路边有很多商店。', 'Lù biān yǒu hěn duō shāngdiàn', 'Ven đường có rất nhiều cửa hàng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ven đường","example":"路边有很多商店。","example_pinyin":"/Lù biān yǒu hěn duō shāngdiàn/","example_meaning":"Ven đường có rất nhiều cửa hàng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('旅客', 'lǚkè', 'Khách du lịch', '旅客们正在上车。', 'Lǚkèmen zhèngzài shàng chē', 'Các hành khách đang lên xe.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Khách du lịch","example":"旅客们正在上车。","example_pinyin":"/Lǚkèmen zhèngzài shàng chē/","example_meaning":"Các hành khách đang lên xe.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('旅行', 'lǚxíng', 'Du lịch', '我们一起去旅行吧！', 'Wǒmen yìqǐ qù lǚxíng ba', 'Chúng ta cùng đi du lịch nhé!', 'Động từ', '[{"pos":"Động từ","meaning":"Du lịch","example":"我们一起去旅行吧！","example_pinyin":"/Wǒmen yìqǐ qù lǚxíng ba/","example_meaning":"Chúng ta cùng đi du lịch nhé!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('旅游', 'lǚyóu', 'Du lịch, du ngoạn', '他很喜欢去旅游。', 'Tā hěn xǐhuān qù lǚyóu', 'Anh ấy rất thích đi du lịch.', 'Động từ', '[{"pos":"Động từ","meaning":"Du lịch, du ngoạn","example":"他很喜欢去旅游。","example_pinyin":"/Tā hěn xǐhuān qù lǚyóu/","example_meaning":"Anh ấy rất thích đi du lịch.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('绿', 'lǜ', 'Màu xanh lá cây', '草地上长满了绿草。', 'Cǎodì shàng zhǎng mǎnle lǜ cǎo', 'Cỏ xanh mọc đầy trên cánh đồng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Màu xanh lá cây","example":"草地上长满了绿草。","example_pinyin":"/Cǎodì shàng zhǎng mǎnle lǜ cǎo/","example_meaning":"Cỏ xanh mọc đầy trên cánh đồng.","is_approved":true},{"pos":"Động từ","meaning":"Chuyển xanh","example":"叶子在阳光下变绿了。","example_pinyin":"/Yèzǐ zài yángguāng xià biàn lǜ le/","example_meaning":"Lá cây dưới ánh nắng đã chuyển sang màu xanh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('绿色', 'lǜsè', 'Màu xanh lá cây', '我喜欢绿色。', 'Wǒ xǐhuān lǜsè', 'Tôi thích màu xanh lá cây.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Màu xanh lá cây","example":"我喜欢绿色。","example_pinyin":"/Wǒ xǐhuān lǜsè/","example_meaning":"Tôi thích màu xanh lá cây.","is_approved":true},{"pos":"Tính từ","meaning":"Xanh, sạch","example":"绿色能源对未来很重要。","example_pinyin":"/Lǜsè néngyuán duì wèilái hěn zhòngyào/","example_meaning":"Năng lượng xanh rất quan trọng cho tương lai.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('卖', 'mài', 'Bán', '他在市场卖水果。', 'Tā zài shìchǎng mài shuǐguǒ', 'Anh ấy bán trái cây ở chợ.', 'Động từ', '[{"pos":"Động từ","meaning":"Bán","example":"他在市场卖水果。","example_pinyin":"/Tā zài shìchǎng mài shuǐguǒ/","example_meaning":"Anh ấy bán trái cây ở chợ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('满', 'mǎn', 'Đầy, tràn đầy', '我的房间里满都是书。', 'Wǒ de fángjiān lǐ mǎn dōu shì shū', 'Trong phòng tôi đều là sách.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Đầy, tràn đầy","example":"我的房间里满都是书。","example_pinyin":"/Wǒ de fángjiān lǐ mǎn dōu shì shū/","example_meaning":"Trong phòng tôi đều là sách.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('满意', 'mǎnyì', 'Hài lòng, thỏa mãn', '你对我们的服务满意吗？', 'Nǐ duì wǒmen de fúwù mǎnyì ma', 'Bạn có hài lòng với dịch vụ của chúng tôi không?', 'Tính từ', '[{"pos":"Tính từ","meaning":"Hài lòng, thỏa mãn","example":"你对我们的服务满意吗？","example_pinyin":"/Nǐ duì wǒmen de fúwù mǎnyì ma/","example_meaning":"Bạn có hài lòng với dịch vụ của chúng tôi không?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('猫', 'māo', 'Mèo', '我家有一只猫。', 'Wǒ jiā yǒu yì zhī māo', 'Nhà tôi có một con mèo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mèo","example":"我家有一只猫。","example_pinyin":"/Wǒ jiā yǒu yì zhī māo/","example_meaning":"Nhà tôi có một con mèo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('米', 'mǐ', 'Gạo

mét', '我想买一公斤米。

