INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('面', 'miàn', 'Chiếc, tấm, bức', '她有一面镜子。', 'Tā yǒu yīmiàn jìngzi', 'Anh ấy có một cái gương.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Chiếc, tấm, bức","example":"她有一面镜子。","example_pinyin":"/Tā yǒu yīmiàn jìngzi/","example_meaning":"Anh ấy có một cái gương.","is_approved":true},{"pos":"Danh từ","meaning":"Mì, sợi mì","example":"我吃了一碗面。","example_pinyin":"/Wǒ chī le yī wǎn miàn/","example_meaning":"Tôi đã ăn một bát mì.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('面', 'miàn', 'mặt', '桌面(tô đỏ)很干净。', 'Zhuōmiàn hěn gānjìng', 'Mặt bàn rất sạch sẽ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"mặt","example":"桌面(tô đỏ)很干净。","example_pinyin":"/Zhuōmiàn hěn gānjìng/","example_meaning":"Mặt bàn rất sạch sẽ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('面前', 'miànqián', 'Trước mặt', '他站在我面前。', 'Tā zhàn zài wǒ miànqián', 'Anh ấy đứng trước tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trước mặt","example":"他站在我面前。","example_pinyin":"/Tā zhàn zài wǒ miànqián/","example_meaning":"Anh ấy đứng trước tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('名', 'míng', 'Tên, danh tiếng', '你的名字是什么？', 'Nǐ de míngzì shì shénme', 'Tên của bạn là gì?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tên, danh tiếng","example":"你的名字是什么？","example_pinyin":"/Nǐ de míngzì shì shénme/","example_meaning":"Tên của bạn là gì?","is_approved":true}]', 'HSK2');
