INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('名单', 'míngdān', 'Danh sách', '我们需要一个新的名单。', 'Wǒmen xūyào yīgè xīn de míngdān', 'Chúng tôi cần một danh sách mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Danh sách","example":"我们需要一个新的名单。","example_pinyin":"/Wǒmen xūyào yīgè xīn de míngdān/","example_meaning":"Chúng tôi cần một danh sách mới.","is_approved":true}]', 'HSK2');
