INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('拿出', 'náchū', 'Lấy ra', '他拿出(tô đỏ)一个苹果。', 'Tā ná chū yí gè píngguǒ', 'Anh ấy lấy ra một quả táo.', 'Động từ', '[{"pos":"Động từ","meaning":"Lấy ra","example":"他拿出(tô đỏ)一个苹果。","example_pinyin":"/Tā ná chū yí gè píngguǒ/","example_meaning":"Anh ấy lấy ra một quả táo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('拿到', 'ná dào', 'Lấy được', '我拿到了考试成绩。', 'Wǒ ná dàole kǎoshì chéngjì', 'Tôi đã nhận được kết quả thi.', 'Động từ', '[{"pos":"Động từ","meaning":"Lấy được","example":"我拿到了考试成绩。","example_pinyin":"/Wǒ ná dàole kǎoshì chéngjì/","example_meaning":"Tôi đã nhận được kết quả thi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('那', 'nà', 'Kia, đó', '那是我的手机。', 'Nà shì wǒ de shǒujī', 'Đó là điện thoại của tôi.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Kia, đó","example":"那是我的手机。","example_pinyin":"/Nà shì wǒ de shǒujī/","example_meaning":"Đó là điện thoại của tôi.","is_approved":true}]', 'HSK2');
