INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('那么', 'nàme', 'Như vậy, thế thì', '他那么高啊。', 'Tā nàme gāo a', 'Anh ấy cao thế!', 'Phó từ', '[{"pos":"Phó từ","meaning":"Như vậy, thế thì","example":"他那么高啊。","example_pinyin":"/Tā nàme gāo a/","example_meaning":"Anh ấy cao thế!","is_approved":true}]', 'HSK2');
