INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('难过', 'nánguò', 'Buồn, khó chịu', '她听到坏消息就很难过。', 'Tā tīngdào huài xiāoxi jiù hěn nánguò', 'Cô ấy rất buồn khi nghe tin xấu.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Buồn, khó chịu","example":"她听到坏消息就很难过。","example_pinyin":"/Tā tīngdào huài xiāoxi jiù hěn nánguò/","example_meaning":"Cô ấy rất buồn khi nghe tin xấu.","is_approved":true}]', 'HSK2');
