INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('鸟', 'niǎo', 'Con chim', '树上有一只小鸟。', 'Shù shàng yǒu yī zhī xiǎo niǎo', 'Trên cây có một con chim nhỏ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Con chim","example":"树上有一只小鸟。","example_pinyin":"/Shù shàng yǒu yī zhī xiǎo niǎo/","example_meaning":"Trên cây có một con chim nhỏ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('弄', 'nòng', 'Làm, gây ra', '你把衣服弄脏了。', 'Nǐ bǎ yīfu nòng zāng le', 'Bạn làm bẩn quần áo rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm, gây ra","example":"你把衣服弄脏了。","example_pinyin":"/Nǐ bǎ yīfu nòng zāng le/","example_meaning":"Bạn làm bẩn quần áo rồi.","is_approved":true}]', 'HSK2');
