INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爬', 'pá', 'Leo, bò', '孩子会爬了。', 'Háizi huì pá le', 'Đứa bé đã biết bò.', 'Động từ', '[{"pos":"Động từ","meaning":"Leo, bò","example":"孩子会爬了。","example_pinyin":"/Háizi huì pá le/","example_meaning":"Đứa bé đã biết bò.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('爬山', 'páshān', 'Leo núi', '周末我们去爬山。', 'Zhōumò wǒmen qù páshān', 'Cuối tuần chúng tôi đi leo núi.', 'Động từ', '[{"pos":"Động từ","meaning":"Leo núi","example":"周末我们去爬山。","example_pinyin":"/Zhōumò wǒmen qù páshān/","example_meaning":"Cuối tuần chúng tôi đi leo núi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('怕', 'pà', 'Sợ', '我怕黑，不敢出门。', 'Wǒ pà hēi, bù gǎn chūmén', 'Tôi sợ bóng tối, không dám ra ngoài.', 'Động từ', '[{"pos":"Động từ","meaning":"Sợ","example":"我怕黑，不敢出门。","example_pinyin":"/Wǒ pà hēi, bù gǎn chūmén/","example_meaning":"Tôi sợ bóng tối, không dám ra ngoài.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('排', 'pái', 'Xếp hàng, sắp xếp', '请大家排好队。', 'Qǐng dàjiā pái hǎo duì', 'Mọi người vui lòng xếp hàng ngay ngắn.', 'Động từ', '[{"pos":"Động từ","meaning":"Xếp hàng, sắp xếp","example":"请大家排好队。","example_pinyin":"/Qǐng dàjiā pái hǎo duì/","example_meaning":"Mọi người vui lòng xếp hàng ngay ngắn.","is_approved":true},{"pos":"Lượng từ","meaning":"Hàng, dãy, băng","example":"我们家门前种了两排树。","example_pinyin":"/Wǒmen jiā mén qián zhòngle liǎng pái shù/","example_meaning":"Trước nhà chúng tôi trồng hai hàng cây.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('排队', 'páiduì', 'Xếp hàng', '我们要排队买票。', 'Wǒmen yào páiduì mǎipiào', 'Chúng tôi phải xếp hàng mua vé.', 'Động từ', '[{"pos":"Động từ","meaning":"Xếp hàng","example":"我们要排队买票。","example_pinyin":"/Wǒmen yào páiduì mǎipiào/","example_meaning":"Chúng tôi phải xếp hàng mua vé.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('排球', 'páiqiú', 'Bóng chuyền', '他喜欢打排球。', 'Tā xǐhuān dǎ páiqiú', 'Anh ấy thích chơi bóng chuyền.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bóng chuyền","example":"他喜欢打排球。","example_pinyin":"/Tā xǐhuān dǎ páiqiú/","example_meaning":"Anh ấy thích chơi bóng chuyền.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('碰', 'pèng', 'Va chạm', '他不小心碰到了桌子。', 'Tā bù xiǎoxīn pèng dào le zhuōzi', 'Anh ấy vô tình đụng vào bàn.', 'Động từ', '[{"pos":"Động từ","meaning":"Va chạm","example":"他不小心碰到了桌子。","example_pinyin":"/Tā bù xiǎoxīn pèng dào le zhuōzi/","example_meaning":"Anh ấy vô tình đụng vào bàn.","is_approved":true}]', 'HSK2');
