INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('其他', 'qítā', 'Khác, những cái khác', '你还有其他问题吗？', 'Nǐ hái yǒu qítā wèntí ma', 'Bạn còn câu hỏi nào khác không?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Khác, những cái khác","example":"你还有其他问题吗？","example_pinyin":"/Nǐ hái yǒu qítā wèntí ma/","example_meaning":"Bạn còn câu hỏi nào khác không?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('其中', 'qízhōng', 'Trong đó', '其中一个是我的朋友。', 'Qízhōng yí gè shì wǒ de péngyǒu', 'Trong đó có một người là bạn tôi.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Trong đó","example":"其中一个是我的朋友。","example_pinyin":"/Qízhōng yí gè shì wǒ de péngyǒu/","example_meaning":"Trong đó có một người là bạn tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('骑', 'qí', 'Cưỡi (xe, ngựa)', '我会骑自行车。', 'Wǒ huì qí zìxíngchē', 'Tôi biết đi xe đạp.', 'Động từ', '[{"pos":"Động từ","meaning":"Cưỡi (xe, ngựa)","example":"我会骑自行车。","example_pinyin":"/Wǒ huì qí zìxíngchē/","example_meaning":"Tôi biết đi xe đạp.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('骑车', 'qí chē', 'Đi xe (đạp, máy)', '我每天骑车上班。', 'Wǒ měitiān qí chē shàngbān', 'Tôi đi xe đi làm mỗi ngày.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi xe (đạp, máy)","example":"我每天骑车上班。","example_pinyin":"/Wǒ měitiān qí chē shàngbān/","example_meaning":"Tôi đi xe đi làm mỗi ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('起飞', 'qǐfēi', 'Cất cánh', '飞机马上起飞了。', 'Fēijī mǎshàng qǐfēi le', 'Máy bay sắp cất cánh rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Cất cánh","example":"飞机马上起飞了。","example_pinyin":"/Fēijī mǎshàng qǐfēi le/","example_meaning":"Máy bay sắp cất cánh rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('气', 'qī', 'Thời tiết, khí hậu

khí thế, trạng thái tinh thần', '今天的天气非常热。

你今天气色不错。', 'Jīntiān de tiānqì fēicháng rè

Nǐ jīntiān qì sè bùcuò', 'Thời tiết hôm nay rất nóng.

Tinh thần của bạn hôm nay không tệ.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thời tiết, khí hậu\n\nkhí thế, trạng thái tinh thần","example":"今天的天气非常热。\n\n你今天气色不错。","example_pinyin":"/Jīntiān de tiānqì fēicháng rè/\n\n/Nǐ jīntiān qì sè bùcuò/","example_meaning":"Thời tiết hôm nay rất nóng.\n\nTinh thần của bạn hôm nay không tệ.","is_approved":true}]', 'HSK2');
