INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('千', 'qiān', 'Một nghìn', '这个手机两千块。', 'Zhège shǒujī liǎng qiān kuài', 'Chiếc điện thoại này hai nghìn tệ.', 'Số từ', '[{"pos":"Số từ","meaning":"Một nghìn","example":"这个手机两千块。","example_pinyin":"/Zhège shǒujī liǎng qiān kuài/","example_meaning":"Chiếc điện thoại này hai nghìn tệ.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('千克', 'qiānkè', 'Kilogram (kg)', '这个箱子十千克。', 'Zhège xiāngzi shí qiānkè', 'Chiếc vali này nặng 10 kg.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Kilogram (kg)","example":"这个箱子十千克。","example_pinyin":"/Zhège xiāngzi shí qiānkè/","example_meaning":"Chiếc vali này nặng 10 kg.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('前年', 'qiánnián', 'Năm kia', '我前年去了北京。', 'Wǒ qiánnián qùle Běijīng', 'Năm kia tôi đã đi Bắc Kinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Năm kia","example":"我前年去了北京。","example_pinyin":"/Wǒ qiánnián qùle Běijīng/","example_meaning":"Năm kia tôi đã đi Bắc Kinh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('墙', 'qiáng', 'Bức tường', '墙上有一幅画。', 'Qiáng shàng yǒu yì fú huà', 'Trên tường có một bức tranh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bức tường","example":"墙上有一幅画。","example_pinyin":"/Qiáng shàng yǒu yì fú huà/","example_meaning":"Trên tường có một bức tranh.","is_approved":true}]', 'HSK2');
