INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('青少年', 'qīng-shàonián', 'Thanh thiếu niên', '他们是青少年。', 'Tāmen shì qīng shàonián', 'Họ là thanh thiếu niên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thanh thiếu niên","example":"他们是青少年。","example_pinyin":"/Tāmen shì qīng shàonián/","example_meaning":"Họ là thanh thiếu niên.","is_approved":true}]', 'HSK2');
