INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('全', 'quán', 'Toàn bộ', '全(tô đỏ)世界都在关注这件事。', 'Quán shìjiè dōu zài guānzhù zhè jiàn shì', 'Cả thế giới đều đang chú ý đến việc này.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Toàn bộ","example":"全(tô đỏ)世界都在关注这件事。","example_pinyin":"/Quán shìjiè dōu zài guānzhù zhè jiàn shì/","example_meaning":"Cả thế giới đều đang chú ý đến việc này.","is_approved":true}]', 'HSK2');
