INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('全家', 'quánjiā', 'Cả nhà, cả gia đình', '我们全家去公园散步了。', 'Wǒmen quánjiā qù gōngyuán sànbù le', 'Cả nhà chúng tôi đã đi dạo công viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cả nhà, cả gia đình","example":"我们全家去公园散步了。","example_pinyin":"/Wǒmen quánjiā qù gōngyuán sànbù le/","example_meaning":"Cả nhà chúng tôi đã đi dạo công viên.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('全年', 'quánnián', 'Cả năm', '这里的天气全年都很好。', 'Zhèlǐ de tiānqì quánnián dōu hěn hǎo', 'Thời tiết ở đây rất tốt cả năm.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cả năm","example":"这里的天气全年都很好。","example_pinyin":"/Zhèlǐ de tiānqì quánnián dōu hěn hǎo/","example_meaning":"Thời tiết ở đây rất tốt cả năm.","is_approved":true}]', 'HSK2');
