INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('全体', 'quántǐ', 'Toàn thể', '全体学生都参加了活动。', 'Quántǐ xuéshēng dōu cānjiā le huódòng', 'Toàn thể học sinh đều tham gia hoạt động.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Toàn thể","example":"全体学生都参加了活动。","example_pinyin":"/Quántǐ xuéshēng dōu cānjiā le huódòng/","example_meaning":"Toàn thể học sinh đều tham gia hoạt động.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('让', 'ràng', 'Làm cho, khiến cho', '这件事让我很高兴。', 'Zhè jiàn shì ràng wǒ hěn gāoxìng', 'Chuyện này khiến tôi rất vui.', 'Động từ', '[{"pos":"Động từ","meaning":"Làm cho, khiến cho","example":"这件事让我很高兴。","example_pinyin":"/Zhè jiàn shì ràng wǒ hěn gāoxìng/","example_meaning":"Chuyện này khiến tôi rất vui.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('然后', 'ránhòu', 'Sau đó', '我先吃饭，然后去学校学习。', 'Wǒ xiān chīfàn, ránhòu qù xuéxiào xuéxí', 'Tôi ăn cơm, sau đó đến trường học.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Sau đó","example":"我先吃饭，然后去学校学习。","example_pinyin":"/Wǒ xiān chīfàn, ránhòu qù xuéxiào xuéxí/","example_meaning":"Tôi ăn cơm, sau đó đến trường học.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('热情', 'rèqíng', 'Nhiệt tình', '她对客人非常热情。', 'Tā duì kèrén fēicháng rèqíng', 'Cô ấy rất nhiệt tình với khách.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Nhiệt tình","example":"她对客人非常热情。","example_pinyin":"/Tā duì kèrén fēicháng rèqíng/","example_meaning":"Cô ấy rất nhiệt tình với khách.","is_approved":true}]', 'HSK2');
