INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('人们', 'rénmen', 'Mọi người', '人们喜欢去公园散步。', 'Rénmen xǐhuan qù gōngyuán sànbù', 'Mọi người thích đi dạo trong công viên.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mọi người","example":"人们喜欢去公园散步。","example_pinyin":"/Rénmen xǐhuan qù gōngyuán sànbù/","example_meaning":"Mọi người thích đi dạo trong công viên.","is_approved":true}]', 'HSK2');
