INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('日子', 'rìzi', 'Ngày, cuộc sống', '这些日子很开心。', 'Zhèxiē rìzi hěn kāixīn', 'Những ngày này rất vui.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Ngày, cuộc sống","example":"这些日子很开心。","example_pinyin":"/Zhèxiē rìzi hěn kāixīn/","example_meaning":"Những ngày này rất vui.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('如果', 'rúguǒ', 'Nếu như', '如果下雨，我不去公园。', 'Rúguǒ xiàyǔ, wǒ bù qù gōngyuán', 'Nếu trời mưa, tôi không đi công viên.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Nếu như","example":"如果下雨，我不去公园。","example_pinyin":"/Rúguǒ xiàyǔ, wǒ bù qù gōngyuán/","example_meaning":"Nếu trời mưa, tôi không đi công viên.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('人口', 'rénkǒu', 'Dân số', '这个城市的人口很多。', 'Zhège chéngshì de rénkǒu hěn duō', 'Thành phố này có dân số rất đông.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Dân số","example":"这个城市的人口很多。","example_pinyin":"/Zhège chéngshì de rénkǒu hěn duō/","example_meaning":"Thành phố này có dân số rất đông.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('商量', 'shāngliáng', 'Thương lượng, bàn bạc', '他们在商量这件事。', 'Tāmen zài shāngliáng zhè jiàn shì', 'Họ đang bàn bạc về việc này.', 'Động từ', '[{"pos":"Động từ","meaning":"Thương lượng, bàn bạc","example":"他们在商量这件事。","example_pinyin":"/Tāmen zài shāngliáng zhè jiàn shì/","example_meaning":"Họ đang bàn bạc về việc này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('商人', 'shāngrén', 'Thương nhân, doanh nhân', '他是一个成功的商人。', 'Tā shì yí gè chénggōng de shāngrén', 'Anh ấy là một doanh nhân thành công.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thương nhân, doanh nhân","example":"他是一个成功的商人。","example_pinyin":"/Tā shì yí gè chénggōng de shāngrén/","example_meaning":"Anh ấy là một doanh nhân thành công.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('上周', 'shàng zhōu', 'Tuần trước', '上周我们去了北京。', 'Shàng zhōu wǒmen qù le Běijīng', 'Tuần trước chúng tôi đã đi Bắc Kinh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tuần trước","example":"上周我们去了北京。","example_pinyin":"/Shàng zhōu wǒmen qù le Běijīng/","example_meaning":"Tuần trước chúng tôi đã đi Bắc Kinh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('少数', 'shǎoshù', 'Số ít, thiểu số', '只有少数人知道这件事。', 'Zhǐ yǒu shǎoshù rén zhīdào zhè jiàn shì', 'Chỉ có số ít người biết chuyện này.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Số ít, thiểu số","example":"只有少数人知道这件事。","example_pinyin":"/Zhǐ yǒu shǎoshù rén zhīdào zhè jiàn shì/","example_meaning":"Chỉ có số ít người biết chuyện này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('少年', 'shàonián', 'Thiếu niên, thanh thiếu niên', '这些少年很有活力。', 'Zhèxiē shàonián hěn yǒu huólì', 'Những thiếu niên này rất năng động.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thiếu niên, thanh thiếu niên","example":"这些少年很有活力。","example_pinyin":"/Zhèxiē shàonián hěn yǒu huólì/","example_meaning":"Những thiếu niên này rất năng động.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('身边', 'shēnbiān', 'Bên cạnh, bên người', '我身边有很多朋友。', 'Wǒ shēnbiān yǒu hěn duō péngyǒu', 'Bên cạnh tôi có rất nhiều bạn bè.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bên cạnh, bên người","example":"我身边有很多朋友。","example_pinyin":"/Wǒ shēnbiān yǒu hěn duō péngyǒu/","example_meaning":"Bên cạnh tôi có rất nhiều bạn bè.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('什么样', 'shénmeyàng', 'Như thế nào, loại nào', '你喜欢什么样的电影？', 'Nǐ xǐhuān shénmeyàng de diànyǐng?', 'Bạn thích loại phim nào?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Như thế nào, loại nào","example":"你喜欢什么样的电影？","example_pinyin":"/Nǐ xǐhuān shénmeyàng de diànyǐng?/","example_meaning":"Bạn thích loại phim nào?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('生（动）', 'shēng', 'Sinh, sinh ra', '她去年生了一个女儿。', 'Tā qùnián shēng le yí gè nǚ''ér', 'Cô ấy sinh một bé gái vào năm ngoái.', 'Động từ', '[{"pos":"Động từ","meaning":"Sinh, sinh ra","example":"她去年生了一个女儿。","example_pinyin":"/Tā qùnián shēng le yí gè nǚ''ér/","example_meaning":"Cô ấy sinh một bé gái vào năm ngoái.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('生词', 'shēngcí', 'Từ mới', '我今天学了十个生词。', 'Wǒ jīntiān xué le shí gè shēngcí', 'Hôm nay tôi đã học mười từ mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Từ mới","example":"我今天学了十个生词。","example_pinyin":"/Wǒ jīntiān xué le shí gè shēngcí/","example_meaning":"Hôm nay tôi đã học mười từ mới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('生活', 'shēnghuó', 'Cuộc sống, sinh hoạt', '他的生活很简单。', 'Tā de shēnghuó hěn jiǎndān', 'Cuộc sống của anh ấy rất đơn giản.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cuộc sống, sinh hoạt","example":"他的生活很简单。","example_pinyin":"/Tā de shēnghuó hěn jiǎndān/","example_meaning":"Cuộc sống của anh ấy rất đơn giản.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('声音', 'shēngyīn', 'Âm thanh, giọng nói', '你的声音很好听。', 'Nǐ de shēngyīn hěn hǎotīng', 'Giọng nói của bạn rất hay.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Âm thanh, giọng nói","example":"你的声音很好听。","example_pinyin":"/Nǐ de shēngyīn hěn hǎotīng/","example_meaning":"Giọng nói của bạn rất hay.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('省（名）', 'shěng', 'Tỉnh (đơn vị hành chính)', '他住在广东省。', 'Tā zhù zài Guǎngdōng shěng', 'Anh ấy sống ở tỉnh Quảng Đông.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tỉnh (đơn vị hành chính)","example":"他住在广东省。","example_pinyin":"/Tā zhù zài Guǎngdōng shěng/","example_meaning":"Anh ấy sống ở tỉnh Quảng Đông.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('省（动）', 'shěng', 'Tiết kiệm', '关灯可以省电。', 'Guān dēng kěyǐ shěng diàn', 'Tắt đèn có thể tiết kiệm điện.', 'Động từ', '[{"pos":"Động từ","meaning":"Tiết kiệm","example":"关灯可以省电。","example_pinyin":"/Guān dēng kěyǐ shěng diàn/","example_meaning":"Tắt đèn có thể tiết kiệm điện.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('十分', 'shífēn', 'Rất, vô cùng', '我十分喜欢这本书。', 'Wǒ shífēn xǐhuān zhè běn shū', 'Tôi rất thích quyển sách này.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Rất, vô cùng","example":"我十分喜欢这本书。","example_pinyin":"/Wǒ shífēn xǐhuān zhè běn shū/","example_meaning":"Tôi rất thích quyển sách này.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('实际', 'shíjì', 'Thực tế', '这个计划很实际。', 'Zhège jìhuà hěn shíjì', 'Kế hoạch này rất thực tế.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Thực tế","example":"这个计划很实际。","example_pinyin":"/Zhège jìhuà hěn shíjì/","example_meaning":"Kế hoạch này rất thực tế.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('实习', 'shíxí', 'Thực tập', '她在国际公司实习。', 'Tā zài guójì gōngsī shíxí', 'Cô ấy đang thực tập tại công ty quốc tế.', 'Động từ', '[{"pos":"Động từ","meaning":"Thực tập","example":"她在国际公司实习。","example_pinyin":"/Tā zài guójì gōngsī shíxí/","example_meaning":"Cô ấy đang thực tập tại công ty quốc tế.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('实现', 'shíxiàn', 'Thực hiện', '他实现了自己的梦想。', 'Tā shíxiàn le zìjǐ de mèngxiǎng', 'Anh ấy đã thực hiện ước mơ của mình.', 'Động từ', '[{"pos":"Động từ","meaning":"Thực hiện","example":"他实现了自己的梦想。","example_pinyin":"/Tā shíxiàn le zìjǐ de mèngxiǎng/","example_meaning":"Anh ấy đã thực hiện ước mơ của mình.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('实在', 'shízài', 'Quả thực, thực sự', '这个问题实在太难了。', 'Zhège wèntí shízài tài nán le', 'Vấn đề này thực sự quá khó.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Quả thực, thực sự","example":"这个问题实在太难了。","example_pinyin":"/Zhège wèntí shízài tài nán le/","example_meaning":"Vấn đề này thực sự quá khó.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('实在', 'shízai', 'Chắc chắn; cẩn thận; kỹ; khéo; tốt (công tác, công việc)', '他工作做得很实在，你放心吧！', 'Tā gōngzuò zuò dé hěn shízài, nǐ fàngxīn ba', 'Anh ấy làm việc rất tốt, bạn yên tâm nhé!', 'Tính từ', '[{"pos":"Tính từ","meaning":"Chắc chắn; cẩn thận; kỹ; khéo; tốt (công tác, công việc)","example":"他工作做得很实在，你放心吧！","example_pinyin":"/Tā gōngzuò zuò dé hěn shízài, nǐ fàngxīn ba/","example_meaning":"Anh ấy làm việc rất tốt, bạn yên tâm nhé!","is_approved":true}]', 'HSK2');
