INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('熟', 'shú 
shóu', 'Quen thuộc', '他对这里很熟。', 'Tā duì zhèlǐ hěn shú', 'Anh ấy rất quen thuộc với nơi này.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Quen thuộc","example":"他对这里很熟。","example_pinyin":"/Tā duì zhèlǐ hěn shú/","example_meaning":"Anh ấy rất quen thuộc với nơi này.","is_approved":true},{"pos":"","meaning":"Chín (trái cây)","example":"这些水果都熟了。","example_pinyin":"/Zhèxiē shuǐguǒ dōu shú le/","example_meaning":"Những trái cây này đều đã chín.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('数', 'shǔ', 'Đếm', '我来数一数有多少人。', 'Wǒ lái shǔ yī shǔ yǒu duōshǎo rén', 'Để tôi đếm có bao nhiêu người.', 'Động từ', '[{"pos":"Động từ","meaning":"Đếm","example":"我来数一数有多少人。","example_pinyin":"/Wǒ lái shǔ yī shǔ yǒu duōshǎo rén/","example_meaning":"Để tôi đếm có bao nhiêu người.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('数字', 'shùzì', 'Chữ số', '请写下这个数字。', 'Qǐng xiě xià zhège shùzì', 'Hãy viết số này xuống.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chữ số","example":"请写下这个数字。","example_pinyin":"/Qǐng xiě xià zhège shùzì/","example_meaning":"Hãy viết số này xuống.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('水平', 'shuǐpíng', 'Trình độ', '他的水平很高。', 'Tā de shuǐpíng hěn gāo', 'Trình độ của anh ấy rất cao.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trình độ","example":"他的水平很高。","example_pinyin":"/Tā de shuǐpíng hěn gāo/","example_meaning":"Trình độ của anh ấy rất cao.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('顺利', 'shùnlì', 'Thuận lợi', '祝你考试顺利！', 'Zhù nǐ kǎoshì shùnlì!', 'Chúc bạn thi cử thuận lợi!', 'Tính từ', '[{"pos":"Tính từ","meaning":"Thuận lợi","example":"祝你考试顺利！","example_pinyin":"/Zhù nǐ kǎoshì shùnlì!/","example_meaning":"Chúc bạn thi cử thuận lợi!","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('说明', 'shuōmíng', 'Giải thích', '请说明一下吧。', 'Qǐng shuōmíng yíxià ba', 'Hãy giải thích một chút.', 'Động từ', '[{"pos":"Động từ","meaning":"Giải thích","example":"请说明一下吧。","example_pinyin":"/Qǐng shuōmíng yíxià ba/","example_meaning":"Hãy giải thích một chút.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('司机', 'sījī', 'Tài xế', '他是出租车司机。', 'Tā shì chūzūchē sījī', 'Anh ấy là tài xế taxi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tài xế","example":"他是出租车司机。","example_pinyin":"/Tā shì chūzūchē sījī/","example_meaning":"Anh ấy là tài xế taxi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('送到', 'sòngdào', 'Gửi đến, đưa đến', '你的快递送到了。', 'Nǐ de kuàidì sòngdào le', 'Bưu kiện của bạn đã được giao đến.', 'Động từ', '[{"pos":"Động từ","meaning":"Gửi đến, đưa đến","example":"你的快递送到了。","example_pinyin":"/Nǐ de kuàidì sòngdào le/","example_meaning":"Bưu kiện của bạn đã được giao đến.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('送给', 'sòng gěi', 'Tặng cho', '他送给我一本书。', 'Tā sòng gěi wǒ yì běn shū', 'Anh ấy tặng tôi một quyển sách.', 'Động từ', '[{"pos":"Động từ","meaning":"Tặng cho","example":"他送给我一本书。","example_pinyin":"/Tā sòng gěi wǒ yì běn shū/","example_meaning":"Anh ấy tặng tôi một quyển sách.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('算', 'suàn', 'Đếm, tính toán

xem như, coi là

thôi, bỏ đi', '我们来算一算有多少人。

这个问题算小的。

算了，我们不说了。', 'Wǒmen lái suàn yí suàn yǒu duōshǎo rén

Zhège wèntí suàn xiǎo de

Suàn le, wǒmen bù shuō le', 'Chúng ta cùng đếm xem có bao nhiêu người.

Vấn đề này được xem như là nhỏ.

Thôi, chúng ta không nói nữa.', 'Động từ', '[{"pos":"Động từ","meaning":"Đếm, tính toán\n\nxem như, coi là\n\nthôi, bỏ đi","example":"我们来算一算有多少人。\n\n这个问题算小的。\n\n算了，我们不说了。","example_pinyin":"/Wǒmen lái suàn yí suàn yǒu duōshǎo rén/\n\n/Zhège wèntí suàn xiǎo de/\n\n/Suàn le, wǒmen bù shuō le/","example_meaning":"Chúng ta cùng đếm xem có bao nhiêu người.\n\nVấn đề này được xem như là nhỏ.\n\nThôi, chúng ta không nói nữa.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('虽然', 'suīrán', 'Mặc dù', '虽然下雨，我还是去。', 'Suīrán xiàyǔ, wǒ háishì qù', 'Mặc dù trời mưa, tôi vẫn đi.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Mặc dù","example":"虽然下雨，我还是去。","example_pinyin":"/Suīrán xiàyǔ, wǒ háishì qù/","example_meaning":"Mặc dù trời mưa, tôi vẫn đi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('随便', 'suíbiàn', 'Tùy tiện, tùy ý', '你可以随便坐。', 'Nǐ kěyǐ suíbiàn zuò', 'Bạn có thể ngồi tùy ý.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Tùy tiện, tùy ý","example":"你可以随便坐。","example_pinyin":"/Nǐ kěyǐ suíbiàn zuò/","example_meaning":"Bạn có thể ngồi tùy ý.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('随时', 'suíshí', 'Bất cứ lúc nào', '你可以随时打给我。', 'Nǐ kěyǐ suíshí dǎ gěi wǒ', 'Bạn có thể gọi cho tôi bất cứ lúc nào.', 'Trạng từ', '[{"pos":"Trạng từ","meaning":"Bất cứ lúc nào","example":"你可以随时打给我。","example_pinyin":"/Nǐ kěyǐ suíshí dǎ gěi wǒ/","example_meaning":"Bạn có thể gọi cho tôi bất cứ lúc nào.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('所以', 'suǒyǐ', 'Cho nên, vậy nên, vì vậy', '我喜欢看书，所以每天都去图书馆。', 'Wǒ xǐhuān kànshū, suǒyǐ měitiān dū qù túshū guǎn', 'Tôi thích đọc sách nên tôi đến thư viện mỗi ngày.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Cho nên, vậy nên, vì vậy","example":"我喜欢看书，所以每天都去图书馆。","example_pinyin":"/Wǒ xǐhuān kànshū, suǒyǐ měitiān dū qù túshū guǎn/","example_meaning":"Tôi thích đọc sách nên tôi đến thư viện mỗi ngày.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('所有', 'suǒyǒu', 'Tất cả', '所有人都来了。', 'Suǒyǒu rén dōu lái le', 'Tất cả mọi người đều đến rồi.', 'Định ngữ', '[{"pos":"Định ngữ","meaning":"Tất cả","example":"所有人都来了。","example_pinyin":"/Suǒyǒu rén dōu lái le/","example_meaning":"Tất cả mọi người đều đến rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('它', 'tā', 'Nó (chỉ đồ vật, động vật)', '这是我的猫，它很可爱。', 'Zhè shì wǒ de māo, tā hěn kě''ài', 'Đây là con mèo của tôi, nó rất đáng yêu.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Nó (chỉ đồ vật, động vật)","example":"这是我的猫，它很可爱。","example_pinyin":"/Zhè shì wǒ de māo, tā hěn kě''ài/","example_meaning":"Đây là con mèo của tôi, nó rất đáng yêu.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('它们', 'tāmen', 'Chúng, bọn chúng (chỉ đồ vật, động vật số nhiều)', '它们(tô đỏ)正在吃东西。', 'Tāmen zhèngzài chī dōngxī', 'Họ đang ăn.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Chúng, bọn chúng (chỉ đồ vật, động vật số nhiều)","example":"它们(tô đỏ)正在吃东西。","example_pinyin":"/Tāmen zhèngzài chī dōngxī/","example_meaning":"Họ đang ăn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('太太', 'tàitai', 'Bà, vợ', '王太太很友好。', 'Wáng tàitai hěn yǒuhǎo', 'Bà Vương rất thân thiện.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bà, vợ","example":"王太太很友好。","example_pinyin":"/Wáng tàitai hěn yǒuhǎo/","example_meaning":"Bà Vương rất thân thiện.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('太阳', 'tàiyáng', 'Mặt trời', '今天太阳很大。', 'Jīntiān tàiyáng hěn dà', 'Hôm nay trời rất nắng.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Mặt trời","example":"今天太阳很大。","example_pinyin":"/Jīntiān tàiyáng hěn dà/","example_meaning":"Hôm nay trời rất nắng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('态度', 'tàidù', 'Thái độ', '他的态度很好。', 'Tā de tàidù hěn hǎo', 'Thái độ của anh ấy rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thái độ","example":"他的态度很好。","example_pinyin":"/Tā de tàidù hěn hǎo/","example_meaning":"Thái độ của anh ấy rất tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('讨论', 'tǎolùn', 'Thảo luận', '他们在讨论问题。', 'Tāmen zài tǎolùn wèntí', 'Họ đang thảo luận vấn đề.', 'Động từ', '[{"pos":"Động từ","meaning":"Thảo luận","example":"他们在讨论问题。","example_pinyin":"/Tāmen zài tǎolùn wèntí/","example_meaning":"Họ đang thảo luận vấn đề.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('套', 'tào', 'Bộ (quần áo, sách, đồ vật)', '我买了一套衣服。', 'Wǒ mǎi le yí tào yīfu', 'Tôi đã mua một bộ quần áo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bộ (quần áo, sách, đồ vật)","example":"我买了一套衣服。","example_pinyin":"/Wǒ mǎi le yí tào yīfu/","example_meaning":"Tôi đã mua một bộ quần áo.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('特别', 'tèbié', 'Đặc biệt, vô cùng, rất', '这本书特别有意思。', 'Zhè běn shū tèbié yǒuyìsi', 'Cuốn sách này đặc biệt thú vị.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Đặc biệt, vô cùng, rất","example":"这本书特别有意思。","example_pinyin":"/Zhè běn shū tèbié yǒuyìsi/","example_meaning":"Cuốn sách này đặc biệt thú vị.","is_approved":true},{"pos":"Tính từ","meaning":"Đặc biệt","example":"这个菜的做法很特别。","example_pinyin":"/Zhège cài de zuòfǎ hěn tèbié/","example_meaning":"Phương pháp làm món ăn này rất đặc biệt","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('特点', 'tèdiǎn', 'Đặc điểm', '这个地方有什么特点？', 'Zhège dìfāng yǒu shénme tèdiǎn', 'Nơi này có đặc điểm gì?', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đặc điểm","example":"这个地方有什么特点？","example_pinyin":"/Zhège dìfāng yǒu shénme tèdiǎn/","example_meaning":"Nơi này có đặc điểm gì?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('疼', 'téng', 'Đau', '我的头很疼。', 'Wǒ de tóu hěn téng', 'Đầu của tôi rất đau.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Đau","example":"我的头很疼。","example_pinyin":"/Wǒ de tóu hěn téng/","example_meaning":"Đầu của tôi rất đau.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('提', 'tí', 'Nêu ra, đề xuất', '他提了一个问题。', 'Tā tí le yí gè wèntí', 'Anh ấy đã nêu ra một câu hỏi.', 'Động từ', '[{"pos":"Động từ","meaning":"Nêu ra, đề xuất","example":"他提了一个问题。","example_pinyin":"/Tā tí le yí gè wèntí/","example_meaning":"Anh ấy đã nêu ra một câu hỏi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('提出', 'tíchū', 'Đề xuất, đưa ra', '老师提出了新问题。', 'Lǎoshī tíchū le xīn wèntí', 'Giáo viên đã đưa ra một câu hỏi mới.', 'Động từ', '[{"pos":"Động từ","meaning":"Đề xuất, đưa ra","example":"老师提出了新问题。","example_pinyin":"/Lǎoshī tíchū le xīn wèntí/","example_meaning":"Giáo viên đã đưa ra một câu hỏi mới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('提到', 'tídào', 'Nhắc đến, đề cập đến', '他提到了我的名字。', 'Tā tídào le wǒ de míngzi', 'Anh ấy đã nhắc đến tên tôi.', 'Động từ', '[{"pos":"Động từ","meaning":"Nhắc đến, đề cập đến","example":"他提到了我的名字。","example_pinyin":"/Tā tídào le wǒ de míngzi/","example_meaning":"Anh ấy đã nhắc đến tên tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('提高', 'tígāo', 'Nâng cao, cải thiện', '我要提高汉语水平。', 'Wǒ yào tígāo Hànyǔ shuǐpíng', 'Tôi muốn nâng cao trình độ tiếng Trung.', 'Động từ', '[{"pos":"Động từ","meaning":"Nâng cao, cải thiện","example":"我要提高汉语水平。","example_pinyin":"/Wǒ yào tígāo Hànyǔ shuǐpíng/","example_meaning":"Tôi muốn nâng cao trình độ tiếng Trung.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('题', 'tí', 'Câu hỏi, đề bài', '这个题很简单。', 'Zhè gè tí hěn jiǎndān', 'Câu hỏi này rất đơn giản.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Câu hỏi, đề bài","example":"这个题很简单。","example_pinyin":"/Zhè gè tí hěn jiǎndān/","example_meaning":"Câu hỏi này rất đơn giản.","is_approved":true}]', 'HSK2');
