INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('体育场', 'tǐyùchǎng', 'Sân vận động', '我们去体育场吧。', 'Wǒmen qù tǐyùchǎng ba', 'Chúng ta đi sân vận động nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Sân vận động","example":"我们去体育场吧。","example_pinyin":"/Wǒmen qù tǐyùchǎng ba/","example_meaning":"Chúng ta đi sân vận động nhé.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('体育馆', 'tǐyùguǎn', 'Nhà thi đấu thể thao', '体育馆很大。', 'Tǐyùguǎn hěn dà', 'Nhà thi đấu thể thao rất lớn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nhà thi đấu thể thao","example":"体育馆很大。","example_pinyin":"/Tǐyùguǎn hěn dà/","example_meaning":"Nhà thi đấu thể thao rất lớn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('天上', 'tiānshàng', 'Trên trời', '天上有很多云。', 'Tiānshàng yǒu hěn duō yún', 'Trên trời có nhiều mây.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Trên trời","example":"天上有很多云。","example_pinyin":"/Tiānshàng yǒu hěn duō yún/","example_meaning":"Trên trời có nhiều mây.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('条', 'tiáo', 'Cái, chiếc (dùng cho vật dài)', '这条裤子很好看。', 'Zhè tiáo kùzi hěn hǎokàn', 'Chiếc quần này rất đẹp.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Cái, chiếc (dùng cho vật dài)","example":"这条裤子很好看。","example_pinyin":"/Zhè tiáo kùzi hěn hǎokàn/","example_meaning":"Chiếc quần này rất đẹp.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('条件', 'tiáojiàn', 'Điều kiện', '他有很好的学习条件(tô đỏ)。', 'Tā yǒu hěn hǎo de xuéxí tiáojiàn', 'Anh ấy có điều kiện học tập rất tốt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Điều kiện","example":"他有很好的学习条件(tô đỏ)。","example_pinyin":"/Tā yǒu hěn hǎo de xuéxí tiáojiàn/","example_meaning":"Anh ấy có điều kiện học tập rất tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('听讲', 'tīngjiǎng', 'Nghe giảng', '学生认真听讲。', 'Xuéshēng rènzhēn tīngjiǎng', 'Học sinh nghe giảng chăm chú.', 'Động từ', '[{"pos":"Động từ","meaning":"Nghe giảng","example":"学生认真听讲。","example_pinyin":"/Xuéshēng rènzhēn tīngjiǎng/","example_meaning":"Học sinh nghe giảng chăm chú.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('听说', 'tīngshuō', 'Nghe nói', '我听说他很忙。', 'Wǒ tīngshuō tā hěn máng', 'Tôi nghe nói anh ấy rất bận.', 'Động từ', '[{"pos":"Động từ","meaning":"Nghe nói","example":"我听说他很忙。","example_pinyin":"/Wǒ tīngshuō tā hěn máng/","example_meaning":"Tôi nghe nói anh ấy rất bận.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('停', 'tíng', 'Dừng lại', '车停在门口了。', 'Chē tíng zài ménkǒu le', 'Xe dừng trước cửa rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Dừng lại","example":"车停在门口了。","example_pinyin":"/Chē tíng zài ménkǒu le/","example_meaning":"Xe dừng trước cửa rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('停车', 'tíngchē', 'Đỗ xe', '请在这里停车。', 'Qǐng zài zhèlǐ tíngchē', 'Vui lòng đỗ xe ở đây.', 'Động từ', '[{"pos":"Động từ","meaning":"Đỗ xe","example":"请在这里停车。","example_pinyin":"/Qǐng zài zhèlǐ tíngchē/","example_meaning":"Vui lòng đỗ xe ở đây.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('停车场', 'tíngchēchǎng', 'Bãi đỗ xe', '停车场很大。', 'Tíngchēchǎng hěn dà', 'Bãi đỗ xe rất lớn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Bãi đỗ xe","example":"停车场很大。","example_pinyin":"/Tíngchēchǎng hěn dà/","example_meaning":"Bãi đỗ xe rất lớn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('挺 （副）', 'tǐng', 'Rất, khá', '这部电影挺好看的。', 'Zhè bù diànyǐng tǐng hǎokàn de', 'Bộ phim này rất hay.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Rất, khá","example":"这部电影挺好看的。","example_pinyin":"/Zhè bù diànyǐng tǐng hǎokàn de/","example_meaning":"Bộ phim này rất hay.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('挺好', 'tǐng hǎo', 'Khá tốt', '这个饭馆挺好。', 'Zhè gè fànguǎn tǐng hǎo', 'Nhà hàng này khá tốt.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Khá tốt","example":"这个饭馆挺好。","example_pinyin":"/Zhè gè fànguǎn tǐng hǎo/","example_meaning":"Nhà hàng này khá tốt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('通', 'tōng', 'Thông, thông suốt', '电话已经打通了。', 'Diànhuà yǐjīng dǎ tōng le', 'Điện thoại đã kết nối được rồi.', 'Động từ', '[{"pos":"Động từ","meaning":"Thông, thông suốt","example":"电话已经打通了。","example_pinyin":"/Diànhuà yǐjīng dǎ tōng le/","example_meaning":"Điện thoại đã kết nối được rồi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('通过', 'tōngguò', 'Thông qua', '他通过了考试。', 'Tā tōngguò le kǎoshì', 'Anh ấy đã vượt qua kỳ thi.', 'Động từ', '[{"pos":"Động từ","meaning":"Thông qua","example":"他通过了考试。","example_pinyin":"/Tā tōngguò le kǎoshì/","example_meaning":"Anh ấy đã vượt qua kỳ thi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('通知', 'tōngzhī', 'Thông báo', '我收到一个通知。', 'Wǒ shōudào yí gè tōngzhī', 'Tôi nhận được một thông báo.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thông báo","example":"我收到一个通知。","example_pinyin":"/Wǒ shōudào yí gè tōngzhī/","example_meaning":"Tôi nhận được một thông báo.","is_approved":true},{"pos":"Động từ","meaning":"Báo tin, báo cho biết, thông tri","example":"你走以前通知我一声。","example_pinyin":"/Nǐ zǒu yǐqián tōngzhī wǒ yīshēng/","example_meaning":"Trước khi bạn đi báo cho tôi một tiếng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('同时', 'tóngshí', 'Đồng thời', '我同时做两件事。', 'Wǒ tóngshí zuò liǎng jiàn shì', 'Tôi làm hai việc cùng một lúc.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Đồng thời","example":"我同时做两件事。","example_pinyin":"/Wǒ tóngshí zuò liǎng jiàn shì/","example_meaning":"Tôi làm hai việc cùng một lúc.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('同事', 'tóngshì', 'Đồng nghiệp', '他是我的同事。', 'Tā shì wǒ de tóngshì', 'Anh ấy là đồng nghiệp của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Đồng nghiệp","example":"他是我的同事。","example_pinyin":"/Tā shì wǒ de tóngshì/","example_meaning":"Anh ấy là đồng nghiệp của tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('同样', 'tóngyàng', 'Giống nhau', '我们的想法同样。', 'Wǒmen de xiǎngfǎ tóngyàng', 'Suy nghĩ của chúng tôi giống nhau.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Giống nhau","example":"我们的想法同样。","example_pinyin":"/Wǒmen de xiǎngfǎ tóngyàng/","example_meaning":"Suy nghĩ của chúng tôi giống nhau.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('头 (名，量）', 'tóu', 'Con (lượng từ cho gia súc)

củ (lượng từ cho củ quả)', '我家有一头牛。

我买了两头蒜。', 'Wǒjiā yǒu yītóu niú

Wǒ mǎile liǎngtóu suàn', 'Nhà tôi có một con bò.

Tôi đã mua hai củ tỏi.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Con (lượng từ cho gia súc)\n\ncủ (lượng từ cho củ quả)","example":"我家有一头牛。\n\n我买了两头蒜。","example_pinyin":"/Wǒjiā yǒu yītóu niú/\n\n/Wǒ mǎile liǎngtóu suàn/","example_meaning":"Nhà tôi có một con bò.\n\nTôi đã mua hai củ tỏi.","is_approved":true},{"pos":"Danh từ","meaning":"Đầu","example":"我的头有点疼。","example_pinyin":"/Wǒ de tóu yǒudiǎn téng/","example_meaning":"Đầu tôi hơi đau.","is_approved":true}]', 'HSK2');
