INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('往', 'wǎng', 'Hướng về', '他往学校走去了。', 'Tā wǎng xuéxiào zǒu qù le', 'Anh ấy đi về hướng trường học.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Hướng về","example":"他往学校走去了。","example_pinyin":"/Tā wǎng xuéxiào zǒu qù le/","example_meaning":"Anh ấy đi về hướng trường học.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('为', 'wèi', 'Vì, để', '我为你准备了礼物。', 'Wǒ wèi nǐ zhǔnbèi le lǐwù', 'Tôi đã chuẩn bị quà cho bạn.', 'Giới từ', '[{"pos":"Giới từ","meaning":"Vì, để","example":"我为你准备了礼物。","example_pinyin":"/Wǒ wèi nǐ zhǔnbèi le lǐwù/","example_meaning":"Tôi đã chuẩn bị quà cho bạn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('为什么', 'wèi shénme', 'Tại sao', '你为什么不去？', 'Nǐ wèi shénme bù qù', 'Tại sao bạn không đi?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Tại sao","example":"你为什么不去？","example_pinyin":"/Nǐ wèi shénme bù qù/","example_meaning":"Tại sao bạn không đi?","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('位', 'wèi', 'Vị, ngài', '这位老师很有名。', 'Zhè wèi lǎoshī hěn yǒumíng', 'Vị giáo viên này rất nổi tiếng.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Vị, ngài","example":"这位老师很有名。","example_pinyin":"/Zhè wèi lǎoshī hěn yǒumíng/","example_meaning":"Vị giáo viên này rất nổi tiếng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('味道', 'wèidào', 'Hương vị', '这个菜味道很好。', 'Zhè gè cài wèidào hěn hǎo', 'Món ăn này có hương vị rất ngon.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Hương vị","example":"这个菜味道很好。","example_pinyin":"/Zhè gè cài wèidào hěn hǎo/","example_meaning":"Món ăn này có hương vị rất ngon.","is_approved":true}]', 'HSK2');
