INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('温度', 'wēndù', 'Nhiệt độ', '今天的温度很高。', 'Jīntiān de wēndù hěn gāo', 'Hôm nay nhiệt độ rất cao.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nhiệt độ","example":"今天的温度很高。","example_pinyin":"/Jīntiān de wēndù hěn gāo/","example_meaning":"Hôm nay nhiệt độ rất cao.","is_approved":true}]', 'HSK2');
