INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小时候', 'xiǎoshíhòu', 'Thời thơ ấu', '小时候，我喜欢画画。', 'Xiǎoshíhòu, wǒ xǐhuān huàhuà', 'Khi còn nhỏ, tôi thích vẽ tranh.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Thời thơ ấu","example":"小时候，我喜欢画画。","example_pinyin":"/Xiǎoshíhòu, wǒ xǐhuān huàhuà/","example_meaning":"Khi còn nhỏ, tôi thích vẽ tranh.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('小说', 'xiǎoshuō', 'Tiểu thuyết', '她在看一本小说。', 'Tā zài kàn yī běn xiǎoshuō', 'Cô ấy đang đọc một cuốn tiểu thuyết.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tiểu thuyết","example":"她在看一本小说。","example_pinyin":"/Tā zài kàn yī běn xiǎoshuō/","example_meaning":"Cô ấy đang đọc một cuốn tiểu thuyết.","is_approved":true}]', 'HSK2');
