INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('校园', 'xiàoyuán', 'Khuôn viên trường', '我们的校园很大。', 'Wǒmen de xiàoyuán hěn dà', 'Khuôn viên trường chúng tôi rất lớn.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Khuôn viên trường","example":"我们的校园很大。","example_pinyin":"/Wǒmen de xiàoyuán hěn dà/","example_meaning":"Khuôn viên trường chúng tôi rất lớn.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('校长', 'xiàozhǎng', 'Hiệu trưởng', '校长在开会。', 'Xiàozhǎng zài kāihuì', 'Hiệu trưởng đang họp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Hiệu trưởng","example":"校长在开会。","example_pinyin":"/Xiàozhǎng zài kāihuì/","example_meaning":"Hiệu trưởng đang họp.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('笑话', 'xiàohuà', 'Cười, trêu đùa

chế nhạo, cười nhạo', '不要笑话(tô đỏ)别人。

别笑话他，要互相尊重。', 'Búyào xiàohuà biérén

Bié xiàohuà tā, yào hùxiāng zūnzhòng', 'Đừng chê cười người khác.

Đừng cười nhạo anh ấy, phải tôn trọng lẫn nhau.', 'Động từ', '[{"pos":"Động từ","meaning":"Cười, trêu đùa\n\nchế nhạo, cười nhạo","example":"不要笑话(tô đỏ)别人。\n\n别笑话他，要互相尊重。","example_pinyin":"/Búyào xiàohuà biérén/\n\n/Bié xiàohuà tā, yào hùxiāng zūnzhòng/","example_meaning":"Đừng chê cười người khác.\n\nĐừng cười nhạo anh ấy, phải tôn trọng lẫn nhau.","is_approved":true},{"pos":"Danh từ","meaning":"Truyện cười","example":"他说了一个笑话。","example_pinyin":"/Tā shuō le yī gè xiàohuà/","example_meaning":"Anh ấy kể một câu chuyện cười.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('鞋', 'xié', 'Giày', '你的鞋很好看。', 'Nǐ de xié hěn hǎokàn', 'Đôi giày của bạn rất đẹp.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Giày","example":"你的鞋很好看。","example_pinyin":"/Nǐ de xié hěn hǎokàn/","example_meaning":"Đôi giày của bạn rất đẹp.","is_approved":true}]', 'HSK2');
