INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('怎样', 'zěnyàng', 'Như thế nào', '今天的天气怎样？', 'Jīntiān de tiānqì zěnyàng', 'Thời tiết hôm nay thế nào?', 'Đại từ', '[{"pos":"Đại từ","meaning":"Như thế nào","example":"今天的天气怎样？","example_pinyin":"/Jīntiān de tiānqì zěnyàng/","example_meaning":"Thời tiết hôm nay thế nào?","is_approved":true}]', 'HSK2');
