INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('站', 'zhàn', 'Đứng', '你站在这里吧。', 'Nǐ zhàn zài zhèlǐ ba', 'Bạn đứng ở đây đi.', 'Động từ', '[{"pos":"Động từ","meaning":"Đứng","example":"你站在这里吧。","example_pinyin":"/Nǐ zhàn zài zhèlǐ ba/","example_meaning":"Bạn đứng ở đây đi.","is_approved":true}]', 'HSK2');
