INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('正好', 'zhènghǎo', 'Vừa hay, đúng lúc', '我来得正好。', 'Wǒ lái de zhènghǎo', 'Tôi đến vừa đúng lúc.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Vừa hay, đúng lúc","example":"我来得正好。","example_pinyin":"/Wǒ lái de zhènghǎo/","example_meaning":"Tôi đến vừa đúng lúc.","is_approved":true}]', 'HSK2');
