INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('只', 'zhǐ', 'Chỉ (trong phạm vi)', '他只喝咖啡，不喝茶。', 'Tā zhǐ hē kāfēi, bù hē chá', 'Anh ấy chỉ uống cà phê, không uống trà.', 'Phó từ', '[{"pos":"Phó từ","meaning":"Chỉ (trong phạm vi)","example":"他只喝咖啡，不喝茶。","example_pinyin":"/Tā zhǐ hē kāfēi, bù hē chá/","example_meaning":"Anh ấy chỉ uống cà phê, không uống trà.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('只要', 'zhǐyào', 'Chỉ cần', '只要努力，就会成功。', 'Zhǐyào nǔlì, jiù huì chénggōng', 'Chỉ cần cố gắng, bạn sẽ thành công.', 'Liên từ', '[{"pos":"Liên từ","meaning":"Chỉ cần","example":"只要努力，就会成功。","example_pinyin":"/Zhǐyào nǔlì, jiù huì chénggōng/","example_meaning":"Chỉ cần cố gắng, bạn sẽ thành công.","is_approved":true}]', 'HSK2');
