INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('周末', 'zhōumò', 'Cuối tuần', '周末我们一起去公园吧。', 'Zhōumò wǒmen yīqǐ qù gōngyuán ba', 'Cuối tuần chúng ta cùng đi công viên nhé.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Cuối tuần","example":"周末我们一起去公园吧。","example_pinyin":"/Zhōumò wǒmen yīqǐ qù gōngyuán ba/","example_meaning":"Cuối tuần chúng ta cùng đi công viên nhé.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('周年', 'zhōunián', 'Kỷ niệm năm', '他们庆祝结婚十周年。', 'Tāmen qìngzhù jiéhūn shí zhōunián', 'Họ kỷ niệm 10 năm ngày cưới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Kỷ niệm năm","example":"他们庆祝结婚十周年。","example_pinyin":"/Tāmen qìngzhù jiéhūn shí zhōunián/","example_meaning":"Họ kỷ niệm 10 năm ngày cưới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('主人', 'zhǔrén', 'Chủ nhân', '狗跟着它的主人走。', 'Gǒu gēnzhe tā de zhǔrén zǒu', 'Con chó đi theo chủ nhân của nó.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Chủ nhân","example":"狗跟着它的主人走。","example_pinyin":"/Gǒu gēnzhe tā de zhǔrén zǒu/","example_meaning":"Con chó đi theo chủ nhân của nó.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('主要', 'zhǔyào', 'Chủ yếu', '这本书的内容很主要。', 'Zhè běn shū de nèiróng hěn zhǔyào', 'Nội dung của cuốn sách này rất quan trọng.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Chủ yếu","example":"这本书的内容很主要。","example_pinyin":"/Zhè běn shū de nèiróng hěn zhǔyào/","example_meaning":"Nội dung của cuốn sách này rất quan trọng.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('住房', 'zhùfáng', 'Nhà ở', '这里的住房很贵。', 'Zhèlǐ de zhùfáng hěn guì', 'Nhà ở đây rất đắt.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Nhà ở","example":"这里的住房很贵。","example_pinyin":"/Zhèlǐ de zhùfáng hěn guì/","example_meaning":"Nhà ở đây rất đắt.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('住院', 'zhùyuàn', 'Nhập viện', '他生病了需要住院。', 'Tā shēngbìng le xūyào zhùyuàn', 'Anh ấy bị bệnh nên cần nhập viện.', 'Động từ', '[{"pos":"Động từ","meaning":"Nhập viện","example":"他生病了需要住院。","example_pinyin":"/Tā shēngbìng le xūyào zhùyuàn/","example_meaning":"Anh ấy bị bệnh nên cần nhập viện.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('装', 'zhuāng', 'Lắp đặt, giả vờ', '他在装电脑软件。', 'Tā zài zhuāng diànnǎo ruǎnjiàn', 'Anh ấy đang cài đặt phần mềm máy tính.', 'Động từ', '[{"pos":"Động từ","meaning":"Lắp đặt, giả vờ","example":"他在装电脑软件。","example_pinyin":"/Tā zài zhuāng diànnǎo ruǎnjiàn/","example_meaning":"Anh ấy đang cài đặt phần mềm máy tính.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('准确', 'zhǔnquè', 'Chính xác', '你的答案很准确。', 'Nǐ de dá''àn hěn zhǔnquè', 'Câu trả lời của bạn rất chính xác.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Chính xác","example":"你的答案很准确。","example_pinyin":"/Nǐ de dá''àn hěn zhǔnquè/","example_meaning":"Câu trả lời của bạn rất chính xác.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('自己', 'zìjǐ', 'Bản thân', '我可以自己完成作业。', 'Wǒ kěyǐ zìjǐ wánchéng zuòyè', 'Tôi có thể tự mình hoàn thành bài tập.', 'Đại từ', '[{"pos":"Đại từ","meaning":"Bản thân","example":"我可以自己完成作业。","example_pinyin":"/Wǒ kěyǐ zìjǐ wánchéng zuòyè/","example_meaning":"Tôi có thể tự mình hoàn thành bài tập.","is_approved":true}]', 'HSK2');
