INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('字典', 'zìdiǎn', 'Từ điển', '我买了一本新字典。', 'Wǒ mǎi le yī běn xīn zìdiǎn', 'Tôi đã mua một cuốn từ điển mới.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Từ điển","example":"我买了一本新字典。","example_pinyin":"/Wǒ mǎi le yī běn xīn zìdiǎn/","example_meaning":"Tôi đã mua một cuốn từ điển mới.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('走过', 'zǒuguò', 'Đi qua', '他走过那家商店。', 'Tā zǒuguò nà jiā shāngdiàn', 'Anh ấy đi qua cửa hàng đó.', 'Động từ', '[{"pos":"Động từ","meaning":"Đi qua","example":"他走过那家商店。","example_pinyin":"/Tā zǒuguò nà jiā shāngdiàn/","example_meaning":"Anh ấy đi qua cửa hàng đó.","is_approved":true}]', 'HSK2');
