INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('最近', 'zuìjìn', 'Gần đây', '最近天气很冷。', 'Zuìjìn tiānqì hěn lěng', 'Gần đây thời tiết rất lạnh.', 'Tính từ', '[{"pos":"Tính từ","meaning":"Gần đây","example":"最近天气很冷。","example_pinyin":"/Zuìjìn tiānqì hěn lěng/","example_meaning":"Gần đây thời tiết rất lạnh.","is_approved":true}]', 'HSK2');
