INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('作用', 'zuòyòng', 'Tác dụng, ảnh hưởng', '这本书对我的学习很有作用。', 'Zhè běn shū duì wǒ de xuéxí hěn yǒu zuòyòng', 'Cuốn sách này có tác dụng lớn đối với việc học của tôi.', 'Danh từ', '[{"pos":"Danh từ","meaning":"Tác dụng, ảnh hưởng","example":"这本书对我的学习很有作用。","example_pinyin":"/Zhè běn shū duì wǒ de xuéxí hěn yǒu zuòyòng/","example_meaning":"Cuốn sách này có tác dụng lớn đối với việc học của tôi.","is_approved":true}]', 'HSK2');
INSERT OR REPLACE INTO vocabulary (hanzi, pinyin, meaning, example, example_pinyin, example_meaning, pos, meanings_json, level) VALUES ('座', 'zuò', 'Tòa (dùng cho núi, cầu, công trình lớn)', '这座山非常高。', 'Zhè zuò shān fēicháng gāo', 'Ngọn núi này rất cao.', 'Lượng từ', '[{"pos":"Lượng từ","meaning":"Tòa (dùng cho núi, cầu, công trình lớn)","example":"这座山非常高。","example_pinyin":"/Zhè zuò shān fēicháng gāo/","example_meaning":"Ngọn núi này rất cao.","is_approved":true}]', 'HSK2');
